// ============================================================
// HELPER GLOBAL — Sincronización Bidireccional Slider <-> Number
// (LOTE 2 de "Entrada Numérica Directa"; ver informe de auditoría LOTE 1
// para el mapeo previo de patrones). Centraliza, para todos los
// laboratorios, la lógica que hoy sólo vive duplicada dos veces dentro
// de #multicapa-custom-sim (bindBcNumberInput / applyLayerL / applyLayerK)
// — sin tocar ninguna de esas dos implementaciones existentes.
//
// Uso: syncSliderAndNumberInput(sliderEl, numberEl, onUpdate)
//   sliderEl  — <input type="range">, fuente de verdad de min/max/step
//               (el slider clampa su propio .value de forma nativa).
//   numberEl  — <input type="number">; hereda min/max/step del slider
//               si no los trae ya declarados en el HTML.
//   onUpdate  — callback propio del laboratorio (cálculo/refresco de la
//               simulación); se invoca con el valor numérico ya
//               sincronizado, sin duplicar ni tocar ninguna fórmula.
// ============================================================

// Cuenta los decimales declarados en el atributo `step` (ej. "0.001" -> 3,
// "5" -> 0, "0.5" -> 1) para redondear el campo numérico de forma
// consistente con la granularidad propia de cada control.
function getStepDecimals(stepAttr) {
    if (!stepAttr) return 0;
    const s = String(stepAttr);
    const dotIdx = s.indexOf('.');
    if (dotIdx === -1) return 0;
    return s.length - dotIdx - 1;
}

function syncSliderAndNumberInput(sliderEl, numberEl, onUpdate) {
    if (!sliderEl || !numberEl || typeof onUpdate !== 'function') return;

    // El número hereda min/max/step del slider si no los trae ya
    // declarados en el HTML (evita mantenerlos duplicados en dos sitios).
    ['min', 'max', 'step'].forEach(attr => {
        if (!numberEl.hasAttribute(attr) && sliderEl.hasAttribute(attr)) {
            numberEl.setAttribute(attr, sliderEl.getAttribute(attr));
        }
    });

    const decimals = getStepDecimals(sliderEl.step || numberEl.step);

    // Clamp explícito a [min,max] — Math.min(max, Math.max(min, val)).
    function clamp(val) {
        const min = parseFloat(sliderEl.min);
        const max = parseFloat(sliderEl.max);
        if (!isNaN(min)) val = Math.max(min, val);
        if (!isNaN(max)) val = Math.min(max, val);
        return val;
    }

    // Estado inicial: el número refleja el valor actual del slider.
    numberEl.value = parseFloat(sliderEl.value).toFixed(decimals);

    // Slider -> Number: el slider ya clampa nativamente su .value a
    // [min,max], así que basta con leerlo y reflejarlo en el número.
    sliderEl.addEventListener('input', () => {
        if (document.activeElement !== numberEl) {
            numberEl.value = parseFloat(sliderEl.value).toFixed(decimals);
        }
        if (typeof updateSliderFill === 'function') updateSliderFill(sliderEl);
        onUpdate(parseFloat(sliderEl.value));
    });

    // Number -> Slider mientras se escribe (evento 'input'): sin clamp
    // todavía, para no pisar lo que el usuario está tecleando (un "-" a
    // medio escribir, un campo vacío mientras borra, etc.) — sólo se
    // descartan entradas que aún no son un número válido.
    numberEl.addEventListener('input', () => {
        const raw = numberEl.value.trim();
        if (raw === '' || raw === '-' || isNaN(parseFloat(raw))) return; // el usuario sigue escribiendo
        const val = parseFloat(raw);
        sliderEl.value = val;
        if (typeof updateSliderFill === 'function') updateSliderFill(sliderEl);
        onUpdate(parseFloat(sliderEl.value));
    });

    // Number -> Slider al confirmar (eventos 'change' y 'blur'): clamp
    // explícito a [min,max] y formateo final con los decimales de `step`.
    function commitNumber() {
        let val = parseFloat(numberEl.value);
        if (isNaN(val)) val = parseFloat(sliderEl.value); // recupera el último valor válido conocido
        val = clamp(val);
        numberEl.value = val.toFixed(decimals);
        sliderEl.value = val;
        if (typeof updateSliderFill === 'function') updateSliderFill(sliderEl);
        onUpdate(parseFloat(sliderEl.value));
    }
    numberEl.addEventListener('change', commitNumber);
    numberEl.addEventListener('blur', commitNumber);
}
// ============================================================
// FIN HELPER GLOBAL — Sincronización Bidireccional Slider <-> Number
// ============================================================

// Function to start main initializations
function startApp() {
    const safeInit = (name, fn) => {
        try {
            const f = (typeof fn === 'function') ? fn : (window[fn] || (typeof fn === 'string' ? eval(fn) : null));
            if (typeof f === 'function') f();
        }
        catch (e) { console.warn(`Skipping ${name}:`, e); }
    };

    safeInit('Timeline', () => initTopTimeline());
    safeInit('TimelineCards', () => initTimeline());
    safeInit('Tabs', () => initTabs());
    safeInit('FilterLabs', () => { if(window.filterLabs) window.filterLabs(); });
    safeInit('Fourier', () => initFourierSimulation());
    safeInit('Planck', () => initPlanckSimulation());
    safeInit('Maxwell', () => initMaxwellSimulation());
    safeInit('InvSq', () => initInvSqSimulation());
    safeInit('Bernoulli', () => initBernoulliSimulation());
    safeInit('Fin', () => initFinSimulation());
    safeInit('Prandtl', () => initPrandtlSimulation());
    safeInit('ViewFactor', () => initViewFactorSimulation());
    safeInit('Generation', () => initGenerationSimulation());
    safeInit('Newton', () => initNewtonSimulation());
    safeInit('Nusselt', () => initNusseltSimulation());
    safeInit('BoundaryLayer', () => initBoundaryLayerSimulation());
    safeInit('Reynolds', () => initReynoldsSimulation());
    safeInit('NatConv', () => initNatConvSimulation());
    safeInit('KelvinScale', () => initKelvinSimulation());
    safeInit('Clausius', () => initClausiusSimulation());
    safeInit('NavierStokes', () => initNavierStokesSimulation());
    safeInit('JouleEquivalent', () => initJouleSimulation());
    safeInit('HerschelSimulation', () => initHerschelSimulation());
    safeInit('Microchannel', () => initMicrochannelSimulation());
    safeInit('CpCv', () => initCpCvSimulation());
    safeInit('DoublePipe', () => initDoublePipeSimulation());
    safeInit('VortexStreet', () => initVortexSimulation());
    safeInit('BoilingRegimes', () => initBoilingSimulation());
    safeInit('Transient', () => initTransientSimulation());
    safeInit('MulticapaCustom', () => initMulticapaCustomSimulation());
    safeInit('Carnot', () => initCarnotSimulation());
    safeInit('OttoDiesel', () => initOttoDieselSimulation());
    safeInit('Pelton', () => initPeltonSimulation());
    safeInit('Celsius', () => initCelsiusSimulation());
    safeInit('InternalBL', () => initInternalBLSimulation());
    safeInit('Chatelet', () => initChateletSimulation());
    safeInit('Pennington', () => initPenningtonSimulation());
    safeInit('Telkes', () => initTelkesSimulation());
    safeInit('RadiacionPlacaPlana', () => initRadiacionPlacaPlanaSimulation());
    safeInit('ContactResistance', () => { if (window.initContactResSimulation) window.initContactResSimulation(); });

    // Modal close logic
    const modal = document.getElementById('image-modal');
    const closeBtn = document.querySelector('.close-modal');
    const newtonModal = document.getElementById('newton-tribute-modal');

    if (modal && closeBtn) {
        closeBtn.addEventListener('click', () => {
            modal.classList.remove('show');
        });
        modal.addEventListener('click', (e) => {
            if (e.target === modal) {
                modal.classList.remove('show');
            }
        });
    }
    if (newtonModal) {
        newtonModal.addEventListener('click', (e) => {
            if (e.target === newtonModal) {
                newtonModal.classList.remove('show');
            }
        });
    }

    // Theme Toggle Logic
    const themeBtn = document.getElementById('theme-toggle');
    if (themeBtn) {
        const savedTheme = localStorage.getItem('theme') || 'dark';
        if (savedTheme === 'light') {
            document.body.classList.add('light-theme');
            themeBtn.innerHTML = '<i class="fas fa-sun"></i>';
        } else {
            document.body.classList.remove('light-theme');
            themeBtn.innerHTML = '<i class="fas fa-moon"></i>';
        }

        themeBtn.addEventListener('click', () => {
            const isLight = document.body.classList.toggle('light-theme');
            localStorage.setItem('theme', isLight ? 'light' : 'dark');
            themeBtn.innerHTML = isLight ? '<i class="fas fa-sun"></i>' : '<i class="fas fa-moon"></i>';
            updateAllChartsTheme();
        });
    }

    // Contact Toggle Logic
    const contactBtn = document.getElementById('contact-toggle');
    const contactBox = document.getElementById('contact-box');
    if (contactBtn && contactBox) {
        contactBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            if (contactBox.style.display === 'none' || contactBox.style.display === '') {
                contactBox.style.display = 'flex';
                contactBtn.innerHTML = '<i class="fas fa-times"></i>';
            } else {
                contactBox.style.display = 'none';
                contactBtn.innerHTML = '<i class="fas fa-envelope"></i>';
            }
        });

        // Close contact box when clicking anywhere else
        document.addEventListener('click', (e) => {
            if (!contactBox.contains(e.target) && e.target !== contactBtn && !contactBtn.contains(e.target)) {
                contactBox.style.display = 'none';
                contactBtn.innerHTML = '<i class="fas fa-envelope"></i>';
            }
        });
    }

    // Downloads (Clases PDF) Toggle Logic
    const downloadsBtn = document.getElementById('downloads-toggle');
    const downloadsBox = document.getElementById('downloads-box');
    const downloadsIcon = document.getElementById('downloads-toggle-icon');
    if (downloadsBtn && downloadsBox) {
        downloadsBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            const isOpen = downloadsBox.style.display === 'flex';
            if (!isOpen) {
                downloadsBox.style.display = 'flex';
                if (downloadsIcon) downloadsIcon.className = 'fas fa-times';
                // Evita solapamiento visual con el panel de contacto
                if (contactBox && contactBox.style.display !== 'none') {
                    contactBox.style.display = 'none';
                    if (contactBtn) contactBtn.innerHTML = '<i class="fas fa-envelope"></i>';
                }
            } else {
                downloadsBox.style.display = 'none';
                if (downloadsIcon) downloadsIcon.className = 'fas fa-file-pdf';
            }
        });

        // Close downloads box when clicking anywhere else
        document.addEventListener('click', (e) => {
            if (!downloadsBox.contains(e.target) && e.target !== downloadsBtn && !downloadsBtn.contains(e.target)) {
                downloadsBox.style.display = 'none';
                if (downloadsIcon) downloadsIcon.className = 'fas fa-file-pdf';
            }
        });
    }

    // Search and Filter Listeners
    const searchInput = document.getElementById('timeline-search');
    const categorySelect = document.getElementById('timeline-filter-category');

    if (searchInput && categorySelect) {
        const handleFilter = () => {
            initTimeline(searchInput.value, categorySelect.value);
        };
        searchInput.addEventListener('input', handleFilter);
        categorySelect.addEventListener('change', handleFilter);
    }

    const sciModal = document.getElementById("scientist-details-modal");
    if (sciModal) {
        sciModal.addEventListener("click", (e) => {
            if (e.target === sciModal) {
                sciModal.classList.remove("show");
            }
        });
    }

    // Sync initial theme for charts after they load
    setTimeout(updateAllChartsTheme, 800);

    // Lógica del Gatekeeper (Temporizador de 10 minutos para registro)
    initGatekeeper();
}

if (document.readyState === 'loading') {
    document.addEventListener("DOMContentLoaded", startApp);
} else {
    startApp();
}

// ============================================================
// GATEKEEPER — Aviso de registro a los 5 minutos (tiempo absoluto)
// ============================================================
// Tiempo objetivo antes de mostrar el modal de registro.
const REGISTRATION_DELAY_MS = 5 * 60 * 1000; // 5 minutos (300,000 ms)
// const REGISTRATION_DELAY_MS = 10 * 1000;   // Descomentar para pruebas locales rápidas (10s)

// Función para manejar el bloqueo de registro y contador de usuarios
function initGatekeeper() {
    const isLocalEnv = (window.location.hostname === '127.0.0.1' || window.location.hostname === 'localhost' || window.location.protocol === 'file:');
    // Permite forzar la prueba del temporizador en local añadiendo ?testGatekeeper=1
    // a la URL (ej. file:///.../index.html?testGatekeeper=1), sin tocar código.
    const forceTest = new URLSearchParams(window.location.search).get('testGatekeeper') === '1';

    // Auto-unlock for local development (se salta si se pide la prueba explícita)
    if (isLocalEnv && !forceTest) {
        console.log("[Auth] Entorno local detectado (" + (window.location.protocol === 'file:' ? 'file://' : window.location.hostname) + "). gatekeeper_registered=true automático → el modal NO se mostrará. Añade ?testGatekeeper=1 a la URL para probar el temporizador real.");
        localStorage.setItem("gatekeeper_registered", "true");
    } else if (isLocalEnv && forceTest) {
        console.log("[Auth] Modo de prueba forzado (?testGatekeeper=1): se ignora el auto-desbloqueo local.");
    }

    // Consultar siempre el total de usuarios reales registrados en Firebase
    fetchRealUserCount();

    const userCountText = document.getElementById("user-count-text");

    // Lógica para verificar el estado de registro local
    const checkRegistration = () => {
        // Si ya está registrado localmente, no bloquear y salir
        const isRegistered = localStorage.getItem("gatekeeper_registered") === "true";

        // También comprobar si hay una sesión activa de Firebase
        const hasFirebaseUser = typeof firebase !== 'undefined' && firebase.auth && firebase.auth().currentUser;

        if (isRegistered || hasFirebaseUser) {
            if (isRegistered && userCountText) {
                userCountText.parentElement.style.borderColor = "#10b981";
                userCountText.parentElement.style.color = "#10b981";
            }
            return true; // Acceso concedido
        }
        return false;
    };

    // Si ya está concedido el acceso, salir de inmediato
    if (checkRegistration()) return;

    // Si no está registrado localmente, dar un margen de espera de 2 segundos
    // para que la autenticación asíncrona de Firebase intente restaurar la sesión antes de bloquear.
    setTimeout(() => {
        if (checkRegistration()) return; // Concedido tras restaurar sesión

        // --- Temporizador robusto basado en tiempo absoluto (Date.now()) ---
        // Se guarda en sessionStorage: mide el tiempo REAL de permanencia en la
        // pestaña actual, sin depender de mouse/teclado y sobreviviendo a
        // regargas de la misma pestaña (no se reinicia con cada interacción).
        let sessionStartTime = sessionStorage.getItem("gatekeeper_session_start");
        if (!sessionStartTime) {
            sessionStartTime = Date.now().toString();
            sessionStorage.setItem("gatekeeper_session_start", sessionStartTime);
        }
        sessionStartTime = parseInt(sessionStartTime, 10);

        console.log("[Auth] Temporizador de registro iniciado. Tiempo objetivo: " + (REGISTRATION_DELAY_MS / 1000) + "s");

        // Comprobación periódica cada 5s (independiente de eventos de mouse/teclado).
        const gatekeeperInterval = setInterval(() => {
            if (checkRegistration()) {
                console.log("[Auth] Registro/login detectado. Deteniendo temporizador.");
                clearInterval(gatekeeperInterval);
                return;
            }

            const elapsedMs = Date.now() - sessionStartTime;
            console.log("[Auth] Tiempo transcurrido: " + Math.round(elapsedMs / 1000) + "s");

            if (elapsedMs >= REGISTRATION_DELAY_MS) {
                console.log("[Auth] Límite de " + (REGISTRATION_DELAY_MS / 1000) + "s alcanzado. Mostrando modal de registro.");
                showGatekeeperModal();
                clearInterval(gatekeeperInterval);
            }
        }, 5000);
    }, 2000);
}

function fetchRealUserCount() {
    const userCountText = document.getElementById("user-count-text");
    if (typeof firebase !== 'undefined' && firebase.apps && firebase.apps.length > 0) {
        try {
            const db = firebase.database();
            db.ref("users").on("value", (snapshot) => {
                const count = snapshot.numChildren();
                const displayCount = Math.max(1, count);
                if (userCountText) {
                    userCountText.textContent = displayCount.toLocaleString();
                }
                localStorage.setItem("gatekeeper_registered_count_real", displayCount);
            });
        } catch (e) {
            console.error("Error al obtener recuento de usuarios reales de Firebase:", e);
        }
    } else {
        setTimeout(fetchRealUserCount, 1000);
    }

    // Iniciar rastreo de presencia en línea
    initOnlinePresence();
}

function initOnlinePresence() {
    const onlineCountText = document.getElementById("online-count-text");
    const btnOnline = document.getElementById("online-count-btn");

    const setDisplay = (n, tooltip) => {
        if (onlineCountText) onlineCountText.textContent = `${Math.max(1, n)} en línea`;
        if (btnOnline) btnOnline.title = tooltip || `${Math.max(1, n)} usuario(s) conectado(s)`;
    };

    // --- Estrategia 1: Firebase Realtime Database con nodo público "presence" ---
    if (typeof firebase !== 'undefined') {
        try {
            if (!firebase.apps.length) {
                firebase.initializeApp({
                    apiKey: "AIzaSyCVeHphav65sj851u72ikIcDXY1e2BN3Qk",
                    authDomain: "thermal-science-history.firebaseapp.com",
                    projectId: "thermal-science-history",
                    storageBucket: "thermal-science-history.firebasestorage.app",
                    messagingSenderId: "820331402760",
                    appId: "1:820331402760:web:706f1ea98599a474ce23bd",
                    measurementId: "G-X3KWMMZE1J",
                    databaseURL: "https://thermal-science-history-default-rtdb.firebaseio.com"
                });
            }

            const db = firebase.database();

            // Clave única por pestaña/dispositivo (no por usuario)
            const sessionKey = 'session_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);
            const myRef = db.ref('online_sessions/' + sessionKey);

            // Escribir presencia sin autenticación (nodo público en reglas Firebase)
            myRef.set({ t: firebase.database.ServerValue.TIMESTAMP })
                .then(() => {
                    myRef.onDisconnect().remove();
                    if (btnOnline) btnOnline.title = `Conectado (Sesión: ${sessionKey})`;
                })
                .catch(err => {
                    // Si permission denied: el nodo "online_sessions" no es público
                    // Usar método alternativo: contador REST/Cloud Function
                    if (btnOnline) btnOnline.title = `Error: ${err.code} - ${err.message}`;
                    useCounterFallback(setDisplay);
                });

            // Escuchar el total de sesiones activas
            let listening = false;
            db.ref('online_sessions').on('value', snap => {
                listening = true;
                setDisplay(snap.numChildren(), `Conectados ahora: ${snap.numChildren()}`);
            }, err => {
                if (btnOnline) btnOnline.title = `Error lectura: ${err.message}`;
                setDisplay(1);
            });

            // Fallback si Firebase no responde en 5s
            setTimeout(() => {
                if (!listening) {
                    if (btnOnline) btnOnline.title = "Firebase sin respuesta (5s)";
                    setDisplay(1);
                }
            }, 5000);

        } catch (e) {
            if (btnOnline) btnOnline.title = `Excepción JS: ${e.message}`;
            setDisplay(1);
        }
    } else {
        // Firebase no cargó (adblocker, red lenta, etc.)
        if (btnOnline) btnOnline.title = "Firebase no disponible";
        setDisplay(1);
    }
}

// Contador alternativo vía Cloud Function o variable de sesión temporal
function useCounterFallback(setDisplay) {
    // Si Firebase RTDB está bloqueado, intentar con Firestore REST API (sin SDK, sin autenticación)
    const projectId = "thermal-science-history";
    const collection = "online_sessions";
    const docId = 'session_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);
    const url = `https://firestore.googleapis.com/v1/projects/${projectId}/databases/(default)/documents/${collection}/${docId}`;

    // Escribir documento de presencia via REST (no requiere auth si reglas lo permiten)
    fetch(url, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
            fields: { t: { integerValue: Date.now() } }
        })
    }).then(r => r.json())
        .then(data => {
            if (data.name) {
                // Leer el conteo total
                const listUrl = `https://firestore.googleapis.com/v1/projects/${projectId}/databases/(default)/documents/${collection}`;
                return fetch(listUrl).then(r => r.json());
            }
        })
        .then(data => {
            const count = (data && data.documents) ? data.documents.length : 1;
            setDisplay(count, `Conectados: ${count} (vía Firestore)`);
        })
        .catch(() => {
            setDisplay(1, "Sin conteo disponible");
        });
}

