window.abrirHistoria = function (storyId) {
    const modal = document.getElementById("story-modal-" + storyId);
    if (modal) {
        modal.style.display = "flex";
        setTimeout(() => modal.classList.add("show"), 10);
        document.body.classList.add("body-lock");
        
        const bodyEl = modal.querySelector(".story-modal-body");
        if (bodyEl && window.MathJax && window.MathJax.typesetPromise) {
            window.MathJax.typesetPromise([bodyEl]).catch(err => console.log('MathJax story error:', err));
        }
    }
};

window.cerrarHistoria = function (storyId) {
    const modal = document.getElementById("story-modal-" + storyId);
    if (modal) {
        modal.classList.remove("show");
        setTimeout(() => {
            modal.style.display = "none";
        }, 300);
        
        const openModals = document.querySelectorAll(".story-modal-overlay.show");
        if (openModals.length <= 1) {
            document.body.classList.remove("body-lock");
        }
    }
};

document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") {
        const activeModal = document.querySelector(".story-modal-overlay.show");
        if (activeModal) {
            const storyId = activeModal.id.replace("story-modal-", "");
            window.cerrarHistoria(storyId);
        }
    }
});

document.addEventListener("click", (e) => {
    if (e.target.classList.contains("story-modal-overlay")) {
        const storyId = e.target.id.replace("story-modal-", "");
        window.cerrarHistoria(storyId);
    }
});

window.currentLanguage = 'es';

// Render timeline cards
function initTimeline(searchText = '', selectedCategory = 'all') {
    const container = document.getElementById("timeline");
    if (!container) return;
    container.innerHTML = "";

    const query = searchText.toLowerCase().trim();

    timelineEvents.forEach((ev, idx) => {
        let matchesCategory = false;
        if (selectedCategory === 'Otros' || selectedCategory === 'otros') {
            matchesCategory = (ev.category === 'Otros' || ev.category === 'otros');
        } else {
            matchesCategory = (ev.category !== 'Otros' && ev.category !== 'otros') &&
                              (selectedCategory === 'all' || ev.category === selectedCategory);
        }

        const titleVal = (window.currentLanguage === 'en' ? (ev.title_en || ev.title) : ev.title) || "";
        const descVal = (window.currentLanguage === 'en' ? (ev.desc_en || ev.desc) : ev.desc) || "";
        const lawVal = (window.currentLanguage === 'en' ? (ev.law_en || ev.law) : ev.law) || "";
        const countryVal = (window.currentLanguage === 'en' ? (ev.country_en || ev.country) : ev.country) || "";
        const surnameVal = ev.surname || "";
        const yearVal = ev.year !== undefined && ev.year !== null ? ev.year.toString() : "";

        const matchesSearch = !query ||
            titleVal.toLowerCase().includes(query) ||
            surnameVal.toLowerCase().includes(query) ||
            lawVal.toLowerCase().includes(query) ||
            descVal.toLowerCase().includes(query) ||
            yearVal.includes(query);

        if (!matchesCategory || !matchesSearch) return;
        const card = document.createElement("div");
        card.setAttribute("data-index", idx);
        // Maintain active default (Fourier is now idx 12) and add highlight-card if requested
        const activeClass = idx === 12 ? 'active ' : '';
        const highlightClass = ev.highlight ? 'highlight-card ' : '';
        const highlightJplClass = ev.highlight_jpl ? 'highlight-jpl ' : '';
        const isNewton = ev.surname === "Newton";
        const newtonClass = isNewton ? 'newton-special-card ' : '';

        card.className = `timeline-card ${activeClass}${highlightClass}${highlightJplClass}${newtonClass}`.trim();

        let imageHtml = ev.image ? `<img src="${ev.image}" alt="${titleVal}" class="card-avatar" onclick="window.openModal(${idx}, event)" style="cursor: zoom-in;" title="Ampliar imagen" />` : '';

        let newtonTributeButton = '';
        if (isNewton) {
            const btnText = window.currentLanguage === 'en' ? 'Explore Scientific Legacy' : 'Explorar Legado Científico';
            newtonTributeButton = `
                <div style="margin-top: 10px; display: flex; gap: 8px; flex-wrap: wrap;">
                    <button class="btn-clear" onclick="window.openNewtonLegacy(event)" style="font-weight: 700; background: linear-gradient(135deg, var(--accent-orange), #ea580c); color: white; border: none; padding: 6px 12px; border-radius: 6px; font-size: 0.72rem; cursor: pointer; display: inline-flex; align-items: center; gap: 6px; box-shadow: 0 4px 10px rgba(234, 88, 12, 0.25); transition: all 0.2s;"><i class="fas fa-crown"></i> ${btnText}</button>
                </div>
            `;
        }

        const yearLabel = ev.year < 0 ? (window.currentLanguage === 'en' ? `${Math.abs(ev.year)} BC` : `${Math.abs(ev.year)} a.C.`) : ev.year;

        card.innerHTML = `
            <div class="card-header">
                <span class="card-year">${yearLabel}</span>
                <span class="card-country">${countryVal}</span>
            </div>
            <div class="card-content-wrapper" style="display: flex; gap: 1rem; align-items: flex-start; margin-top: 0.5rem;">
                ${imageHtml}
                <div style="flex: 1;">
                    <h3 class="card-title">${titleVal}</h3>
                    <p class="card-desc">${descVal}</p>
                    <div style="margin-top: 6px; display: flex; gap: 6px; flex-wrap: wrap; align-items: center;">
                        <button class="btn-clear" onclick="window.openScientistModalDirect(${idx}, event)" style="font-weight: 600; background: rgba(59, 130, 246, 0.12); color: var(--accent-blue); border: 1px solid rgba(59, 130, 246, 0.25); padding: 4px 8px; border-radius: 4px; font-size: 0.68rem; cursor: pointer; display: inline-flex; align-items: center; gap: 4px; transition: all 0.2s;"><i class="fas fa-info-circle"></i> <span class="lang-es">Ver Detalles</span><span class="lang-en" style="display:none;">View Details</span></button>
                        ${newtonTributeButton}
                    </div>
                </div>
            </div>
        `;

        // Determine tab target
        let tabTarget = "";
        if (ev["tab-target"]) tabTarget = ev["tab-target"];
        else if (ev.surname === "Bernoulli") tabTarget = "bernoulli-sim";
        else if (ev.surname === "Reynolds") tabTarget = "reynolds-sim";
        else if (ev.surname === "Celsius") tabTarget = "celsius-sim";
        else if (ev.surname === "Watt") tabTarget = "watt-sim";
        else if (ev.surname === "Navier & Stokes") tabTarget = "ns-sim";
        else if (ev.surname === "Nukiyama") tabTarget = "boiling-sim";
        else if (ev.surname === "von Kármán") tabTarget = "vortex-sim";
        else if (ev.year === 1701) tabTarget = "newton-sim";
        else if (ev.year === 1800) tabTarget = "herschel-sim";
        else if (ev.year === 1822) tabTarget = "fourier-sim";
        else if (ev.year === 1900 || ev.year === 1879) tabTarget = "planck-sim";
        else if (ev.year === 1904) tabTarget = "prandtl-sim";
        else if (ev.year === 1915 || ev.year === 1930) tabTarget = "nusselt-sim";
        else if (ev.year === 1936) tabTarget = "bl-sim";
        else if (ev.surname === "Joule") tabTarget = "joule-sim";
        else if (ev.surname === "Kelvin") tabTarget = "kelvin-sim";
        else if (ev.surname === "Clausius") tabTarget = "clausius-sim";
        else if (ev.surname === "Colburn & Hougen" || ev.surname === "Chilton & Colburn" || ev.surname === "Bell-Delaware") tabTarget = "doublepipe-sim";
        else if (ev.surname === "Jakob") tabTarget = "fourier-sim";
        else {
            if (ev.category === "Radiación") tabTarget = "planck-sim";
            else if (ev.category === "Convección") tabTarget = "prandtl-sim";
            else if (ev.category === "Conducción") tabTarget = "fourier-sim";
            else if (ev.category === "Termodinámica") tabTarget = "carnot-sim";
        }

        if (tabTarget) card.setAttribute("data-tab-target", tabTarget);

        card.addEventListener("click", () => {
            // Remove active and reset inline styles on all cards
            document.querySelectorAll(".timeline-card").forEach(c => {
                c.classList.remove("active");
                const d = c.querySelector(".card-desc");
                if (d) {
                    d.style.display = "";
                    d.style.webkitLineClamp = "";
                    d.style.lineClamp = "";
                    d.style.overflow = "";
                }
            });
            // Add active and force expand styles on clicked card
            card.classList.add("active");
            const descEl = card.querySelector(".card-desc");
            if (descEl) {
                descEl.style.display = "block";
                descEl.style.webkitLineClamp = "unset";
                descEl.style.lineClamp = "none";
                descEl.style.overflow = "visible";
            }
            if (tabTarget) {
                switchTab(tabTarget, true);
            }

            // Mobile popup modal logic (width <= 1024px)
            if (window.innerWidth <= 1024) {
                window.openScientistModalDirect(idx);
            }
        });

        container.appendChild(card);
    });

    // Special Relationships Card at the end
    if (!query && selectedCategory === 'all') {
        const relationsCard = document.createElement("div");
        relationsCard.className = "timeline-card";
        relationsCard.style.background = "linear-gradient(145deg, rgba(30,27,75,0.9), rgba(49,46,129,0.95))";
        relationsCard.style.border = "1px solid rgba(139, 92, 246, 0.4)";
        relationsCard.style.boxShadow = "0 8px 30px rgba(139, 92, 246, 0.2)";

        if (window.currentLanguage === 'en') {
            let storiesHtml = "";
            connectionsStories.forEach(story => {
                const titleVal = story.title_en;
                const descVal = story.desc_en;
                storiesHtml += `
                    <div class="relations-subcard" style="border-left: 3px solid ${story.color};">
                        <div>
                            <div class="relations-subcard-meta"><i class="fas ${story.icon}" style="color: ${story.color};"></i> ${story.year}</div>
                            <h4 class="relations-subcard-title" style="margin-top: 4px; margin-bottom: 8px;">${titleVal}</h4>
                            <div style="font-size: 0.82rem; color: #cbd5e1; opacity: 0.9; line-height: 1.5; text-align: justify; margin-bottom: 12px;">${descVal}</div>
                        </div>
                        <button class="relations-subcard-btn" onclick="window.abrirHistoria('${story.id}')"><i class="fas fa-search-plus"></i> Expand Story</button>
                    </div>
                `;
            });

            relationsCard.innerHTML = `
                <div class="card-header" style="border-bottom: 1px solid rgba(139, 92, 246, 0.2); padding-bottom: 10px;">
                    <span class="card-year" style="color: #c4b5fd; background: rgba(139, 92, 246, 0.2); font-size: 1rem; padding: 6px 14px;"><i class="fas fa-network-wired"></i> Historical Connections Network</span>
                </div>
                <div style="margin-top: 15px; font-size: 0.9rem; color: #e2e8f0; line-height: 1.6;">
                    <p style="margin-bottom: 15px; font-style: italic; opacity: 0.9;">Science was not built in isolation. Behind the great equations, there are deep human relationships, intense rivalries, and unbreakable legacies from mentor to pupil:</p>
                    <div class="relations-grid">
                        ${storiesHtml}
                    </div>
                </div>
            `;
        } else {
            let storiesHtml = "";
            connectionsStories.forEach(story => {
                const titleVal = story.title;
                const descVal = story.desc;
                storiesHtml += `
                    <div class="relations-subcard" style="border-left: 3px solid ${story.color};">
                        <div>
                            <div class="relations-subcard-meta"><i class="fas ${story.icon}" style="color: ${story.color};"></i> ${story.year}</div>
                            <h4 class="relations-subcard-title" style="margin-top: 4px; margin-bottom: 8px;">${titleVal}</h4>
                            <div style="font-size: 0.82rem; color: #cbd5e1; opacity: 0.9; line-height: 1.5; text-align: justify; margin-bottom: 12px;">${descVal}</div>
                        </div>
                        <button class="relations-subcard-btn" onclick="window.abrirHistoria('${story.id}')"><i class="fas fa-search-plus"></i> Ampliar Historia</button>
                    </div>
                `;
            });

            relationsCard.innerHTML = `
                <div class="card-header" style="border-bottom: 1px solid rgba(139, 92, 246, 0.2); padding-bottom: 10px;">
                    <span class="card-year" style="color: #c4b5fd; background: rgba(139, 92, 246, 0.2); font-size: 1rem; padding: 6px 14px;"><i class="fas fa-network-wired"></i> Red de Conexiones Históricas</span>
                </div>
                <div style="margin-top: 15px; font-size: 0.9rem; color: #e2e8f0; line-height: 1.6;">
                    <p style="margin-bottom: 15px; font-style: italic; opacity: 0.9;">La ciencia no se construyó en aislamiento. Detrás de las grandes ecuaciones, existen relaciones humanas profundas, rivalidades intensas y legados inquebrantables de maestro a pupilo:</p>
                    <div class="relations-grid">
                        ${storiesHtml}
                    </div>
                </div>
            `;
        }
        
        // Clean up previous story modals if any
        document.querySelectorAll(".story-modal-overlay").forEach(el => el.remove());
        
        // Append story modals to body
        connectionsStories.forEach(story => {
            const modalEl = document.createElement("div");
            modalEl.id = `story-modal-${story.id}`;
            modalEl.className = "story-modal-overlay";
            
            const titleVal = window.currentLanguage === 'en' ? story.title_en : story.title;
            const descVal = window.currentLanguage === 'en' ? story.desc_en : story.desc;
            
            modalEl.innerHTML = `
                <div class="story-modal-content">
                    <div class="story-modal-header">
                        <h3 class="story-modal-title"><i class="fas ${story.icon}" style="color: ${story.color}; margin-right: 8px;"></i> ${titleVal} [${story.year}]</h3>
                        <span class="story-modal-close" onclick="window.cerrarHistoria('${story.id}')">&times;</span>
                    </div>
                    <div class="story-modal-body">
                        ${descVal}
                    </div>
                </div>
            `;
            document.body.appendChild(modalEl);
        });

        container.appendChild(relationsCard);
    }

    // Defer MathJax typesetting to allow script to load
    setTimeout(() => {
        if (window.MathJax && window.MathJax.typesetPromise) {
            MathJax.typesetPromise().catch((err) => console.log('MathJax error: ', err));
        }
    }, 1000);
}

// Render top horizontal timeline
function initTopTimeline() {
    const container = document.getElementById("top-timeline");
    if (!container) return;

    container.innerHTML = "";

    timelineEvents.forEach((ev, idx) => {
        if (!ev.surname) return; // Only show main events with surname

        const chip = document.createElement("div");
        chip.className = "timeline-chip";

        const lawVal = (window.currentLanguage === 'en' ? (ev.law_en || ev.law) : ev.law);
        const yearLabel = ev.year < 0 ? (window.currentLanguage === 'en' ? `${Math.abs(ev.year)} BC` : `${Math.abs(ev.year)} a.C.`) : ev.year;
        chip.innerHTML = `
            <div class="chip-year">${yearLabel}</div>
            <div class="chip-name">${ev.surname}</div>
            <div class="chip-law">${lawVal}</div>
        `;

        chip.addEventListener("click", () => {
            // Find corresponding vertical card by data-index and click it
            const targetCard = document.querySelector(`.timeline-card[data-index="${idx}"]`);
            if (targetCard) {
                targetCard.scrollIntoView({ behavior: 'smooth', block: 'center' });
                targetCard.click();
            }
        });

        container.appendChild(chip);
    });
}

// Simple tab navigation system
function initTabs() {
    const tabButtons = document.querySelectorAll(".tab-btn");
    tabButtons.forEach(btn => {
        btn.addEventListener("click", () => {
            const targetId = btn.getAttribute("data-target");
            switchTab(targetId);
        });
    });
}

window.filterLabs = function () {
    const searchInput = document.getElementById("lab-search");
    const categorySelect = document.getElementById("lab-filter-category");
    const query = searchInput ? searchInput.value.toLowerCase().trim() : "";
    const category = categorySelect ? categorySelect.value : "all";

    // Helper: does this button carry a given tag?
    function hasTag(tab, tag) {
        var tags = (tab.getAttribute("data-tags") || "").split(" ");
        return tags.indexOf(tag) !== -1;
    }

    // Tag-based filter categories (multi-value data-tags attribute)
    var TAG_FILTERS = { "transferencia-calor":true, "conduccion":true, "conveccion":true, "radiacion":true };

    const tabs = document.querySelectorAll(".tabs-header .tab-btn");

    tabs.forEach(tab => {
        let catTitle = "";
        let prev = tab.previousElementSibling;
        while (prev) {
            if (prev.classList.contains('tab-category-title')) {
                catTitle = prev.textContent;
                break;
            }
            prev = prev.previousElementSibling;
        }

        const text = tab.textContent.toLowerCase();

        // Identificar si la pestaña es uno de los laboratorios "Otros"
        const isOtro = tab.classList.contains("lab-otros") ||
                       tab.getAttribute("data-category") === "Otros" ||
                       (catTitle && catTitle.toLowerCase().includes("otros"));

        let matchesSearch = text.includes(query);
        let matchesCategory = false;

        if (category === "all") {
            // "Todos": mostrar todo excepto lab-otros (comportamiento original)
            matchesCategory = !isOtro;
        } else if (TAG_FILTERS[category]) {
            // Filtro por tag semántico: muestra sólo labs que tienen ese tag en data-tags
            // Para "transferencia-calor" también acepta data-category legacy
            if (category === "transferencia-calor") {
                matchesCategory = hasTag(tab, "transferencia-calor") ||
                                  tab.getAttribute("data-category") === "transferencia-calor";
            } else {
                matchesCategory = hasTag(tab, category);
            }
        } else if (category === "Otros" || category === "otros") {
            matchesCategory = isOtro;
        } else {
            // Filtros de sección estructural (Principios, Mecánica, Termodinámica, etc.)
            if (isOtro) {
                matchesCategory = false;
            } else {
                matchesCategory = (catTitle && catTitle.includes(category)) ||
                                  text.includes(category.toLowerCase());
            }
        }

        if (matchesSearch && matchesCategory) {
            tab.style.display = "";
        } else {
            tab.style.display = "none";
        }
    });

    // Ocultar categorías enteras si no tienen laboratorios visibles
    const categories = document.querySelectorAll(".tabs-header .tab-category-title");
    categories.forEach(cat => {
        let hasVisible = false;
        let next = cat.nextElementSibling;
        while (next && !next.classList.contains('tab-category-title')) {
            if (next.style.display !== "none") {
                hasVisible = true;
                break;
            }
            next = next.nextElementSibling;
        }
        cat.style.display = hasVisible ? "" : "none";
    });
};

// Pill filter helper: activates a pill, syncs the select, and triggers filterLabs
window.activatePillFilter = function(pillBtn) {
    var filterVal = pillBtn.getAttribute("data-filter");
    // Update pill active styles
    document.querySelectorAll(".tc-pill").forEach(function(p) {
        var isActive = p === pillBtn;
        p.style.fontWeight = isActive ? "700" : "600";
        p.style.boxShadow = isActive ? "0 0 0 2px currentColor" : "";
        p.style.opacity = isActive ? "1" : "0.7";
    });
    // Sync the category select
    var sel = document.getElementById("lab-filter-category");
    if (sel) {
        var found = false;
        for (var i = 0; i < sel.options.length; i++) {
            if (sel.options[i].value === filterVal) {
                sel.selectedIndex = i;
                found = true;
                break;
            }
        }
        if (!found) { sel.selectedIndex = 0; }  // fallback to "all"
    }
    window.filterLabs();
};

function switchTab(tabId, disableTimelineSync = false) {
    // Update buttons active status
    document.querySelectorAll(".tab-btn").forEach(btn => {
        if (btn.getAttribute("data-target") === tabId) {
            btn.classList.add("active");
        } else {
            btn.classList.remove("active");
        }
    });

    // Update pane active status
    document.querySelectorAll(".tab-pane").forEach(pane => {
        // GUARD anti-colisión: mientras el laboratorio Multicapa esté en modo
        // pantalla completa (clase 'fullscreen', gestionada exclusivamente por su
        // propio controlador IIFE), switchTab no debe tocarlo en absoluto -ni su
        // estado active/inactive ni sus estilos inline- para eliminar cualquier
        // posibilidad de que switchTab interfiera con el fullscreen mientras el
        // modal vive teletransportado en document.body.
        if (pane.getAttribute("id") === "multicapa-custom-sim" && pane.classList.contains("fullscreen")) {
            return;
        }
        if (pane.getAttribute("id") === tabId) {
            pane.classList.add("active");
            if (tabId === "multicapa-custom-sim") {
                pane.style.setProperty('display', 'block', 'important');
                pane.style.setProperty('visibility', 'visible', 'important');
                pane.style.setProperty('opacity', '1', 'important');
                pane.style.setProperty('height', 'auto', 'important');
                pane.style.setProperty('position', 'relative', 'important');
                pane.style.setProperty('z-index', '9999', 'important');
                pane.style.setProperty('background', 'var(--bg-dark, #0f172a)', 'important');
                setTimeout(() => pane.scrollIntoView({ behavior: 'smooth', block: 'start' }), 10);
            }
        } else {
            pane.classList.remove("active");
            if (pane.getAttribute("id") === "multicapa-custom-sim") {
                pane.style.display = '';
                pane.style.visibility = '';
                pane.style.opacity = '';
                pane.style.height = '';
                pane.style.position = '';
                pane.style.zIndex = '';
                pane.style.background = '';
            }
        }
    });

    // Sync timeline card active status and scroll into view only if not clicked from timeline
    if (!disableTimelineSync) {
        const primaryYears = {
            "carnot-sim": "1824",
            "fourier-sim": "1822",
            "planck-sim": "1900",
            "nusselt-sim": "1915",
            "prandtl-sim": "1904",
            "newton-sim": "1701",
            "boiling-sim": "1934",
            "bl-sim": "1908",
            "ns-sim": "1822",
            "celsius-sim": "1742",
            "bernoulli-sim": "1738",
            "herschel-sim": "1800",
            "joule-sim": "1843",
            "kelvin-sim": "1848",
            "clausius-sim": "1850",
            "doublepipe-sim": "1934"
        };

        const targetYear = primaryYears[tabId];
        const timelineCards = document.querySelectorAll(".timeline-card");

        timelineCards.forEach(card => {
            card.classList.remove("active");
            const d = card.querySelector(".card-desc");
            if (d) {
                d.style.display = "";
                d.style.webkitLineClamp = "";
                d.style.lineClamp = "";
                d.style.overflow = "";
            }
            if (targetYear && card.querySelector('.card-year') && card.querySelector('.card-year').textContent.includes(targetYear)) {
                card.classList.add("active");
                if (d) {
                    d.style.display = "block";
                    d.style.webkitLineClamp = "unset";
                    d.style.lineClamp = "none";
                    d.style.overflow = "visible";
                }
                card.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }
        });
    }

    // Trigger window resize to adjust canvas dimensions when tab becomes visible
    setTimeout(() => {
        window.dispatchEvent(new Event('resize'));
    }, 50);

    // FIX newton-sim: forzar resize+update del chart de Newton si es el tab activo.
    // Chart.js colapsa a 0x0 cuando el contenedor estaba oculto al renderizar;
    // hay que pedirle explícitamente que recalcule sus dimensiones.
    if (tabId === 'newton-sim') {
        setTimeout(() => {
            const newtonGraphCanvas = document.getElementById('newtonGraph');
            if (newtonGraphCanvas && window.Chart) {
                const newtonChart = Chart.getChart
                    ? Chart.getChart(newtonGraphCanvas)
                    : null;
                if (newtonChart) {
                    newtonChart.resize();
                    newtonChart.update('none'); // 'none' = sin animación para evitar flicker
                }
            }
            // Forzar redimensionamiento del canvas de animación física.
            // CRÍTICO: leer dimensiones del SHELL (padre con altura CSS fija),
            // nunca de canvas.clientHeight que podría estar inflado en el bucle.
            const newtonCanvas = document.getElementById('newtonCanvas');
            if (newtonCanvas) {
                const shell = newtonCanvas.closest('.newton-canvas-shell');
                const rect = shell ? shell.getBoundingClientRect() : null;
                const w = rect && rect.width > 0 ? Math.floor(rect.width) : (newtonCanvas.clientWidth || newtonCanvas.offsetWidth || 600);
                const h = rect && rect.height > 0 ? Math.floor(rect.height) : (newtonCanvas.clientHeight || newtonCanvas.offsetHeight || 280);
                newtonCanvas.width = w;
                newtonCanvas.height = h;
            }
        }, 80); // 80 ms > 50 ms del resize event, para que el DOM ya esté pintado
    }

    // FIX multicapa-custom-sim: inicialización diferida cuando el canvas ya tiene dimensiones reales
    if (tabId === 'multicapa-custom-sim') {
        setTimeout(() => {
            const activePane = document.getElementById(tabId);
            // GUARD anti-colisión: si el modal ya está en pantalla completa, este
            // bloque de switchTab no debe hacer nada -su controlador IIFE dedicado
            // ya gestiona init/resize/scroll por sí solo-.
            if (activePane && activePane.classList.contains('fullscreen')) return;
            // Si la inicialización falló al cargar (canvas en display:none), reintentar ahora
            if (!window._multicapaInited) {
                try {
                    initMulticapaCustomSimulation();
                } catch(e) {
                    console.error('Error al inicializar Multicapa Custom:', e);
                }
            }
            // Forzar resize de los gráficos
            if (window.MulticapaLab && typeof window.MulticapaLab.resize === 'function') {
                window.MulticapaLab.resize();
            }
            if (activePane) {
                activePane.scrollIntoView({ behavior: 'smooth', block: 'start' });
            }
        }, 80);
    }

    // FIX nusselt-sim: reintento de inicialización diferida (Lazy Init) +
    // recálculo de dimensiones/partículas del perfil de velocidad al abrir
    // esta pestaña. initNusseltSimulation() puede haber abortado en el
    // arranque (DOMContentLoaded) porque el canvas estaba en 0x0 mientras
    // la pestaña permanecía oculta; aquí, con display:block ya aplicado,
    // reintentamos con las dimensiones reales.
    if (tabId === 'nusselt-sim') {
        setTimeout(() => {
            const activePane = document.getElementById(tabId);
            if (activePane && activePane.classList.contains('fullscreen')) return;
            if (!window._nusseltInited) {
                // Primer intento fallido al cargar: reintentar ahora que el
                // canvas ya tiene dimensiones reales.
                try {
                    initNusseltSimulation();
                } catch (e) {
                    console.error('Error al inicializar Nusselt:', e);
                }
            } else {
                // Ya estaba inicializado: recalcular el tamaño real del
                // canvas de animación y reinstanciar sus partículas para
                // que el perfil de velocidad se dibuje correctamente sin
                // depender de abrir/cerrar pantalla completa.
                const animCanvas = document.getElementById('nusseltCanvas');
                if (animCanvas && animCanvas.parentElement) {
                    const parentWidth = animCanvas.parentElement.clientWidth;
                    const parentHeight = animCanvas.parentElement.clientHeight;
                    if (parentWidth > 0 && parentHeight > 0) {
                        animCanvas.width = parentWidth;
                        animCanvas.height = parentHeight;
                    }
                }
                if (typeof window.resetNusseltParticles === 'function') {
                    window.resetNusseltParticles();
                }
            }
            // Redimensionar la gráfica Chart.js del perfil de temperatura
            if (window.NusseltLab && typeof window.NusseltLab.resize === 'function') {
                window.NusseltLab.resize();
            }
        }, 80);
    }

    // FIX v2: Re-render MathJax equations for the newly visible tab pane
    setTimeout(() => {
        if (window.MathJax && MathJax.typesetPromise) {
            const activePane = document.querySelector('.tab-pane.active');
            if (activePane) {
                MathJax.typesetPromise([activePane]).catch(function (err) {
                    console.warn('MathJax tab typeset error:', err);
                });
            }
        }
    }, 100);
}

/* =========================================================================
   FOURIER CONDUCTION SIMULATOR
   ========================================================================= */
let fourierAnimationId = null;
let fourierChart = null;
let fourierT1 = 100;
let fourierT2 = 20;
let fourierK = 205;
let fourierL = 0.1;
let fourierQ = 1000;

function initFourierSimulation() {
    const sliderT1 = document.getElementById("fourier-t1");
    if (!sliderT1) return;
    const sliderT2 = document.getElementById("fourier-t2");
    const sliderK = document.getElementById("fourier-k");
    const sliderL = document.getElementById("fourier-l"); // L acts as thickness for plane
    const sliderR2 = document.getElementById("fourier-r2");
    const sliderQin = document.getElementById("fourier-q-in");
    const sliderR1 = document.getElementById("fourier-r1");
    const sliderAH = document.getElementById("fourier-ah");
    const geomSelect = document.getElementById("fourier-geom");

    const modeSelect = document.getElementById("fourier-mode-select");
    const t2Container = document.getElementById("fourier-t2-container");
    const qInContainer = document.getElementById("fourier-q-in-container");
    const r1Container = document.getElementById("fourier-r1-container");
    const lContainer = document.getElementById("fourier-l-container");
    const r2Container = document.getElementById("fourier-r2-container");
    const ahContainer = document.getElementById("fourier-ah-container");

    const labelAH = document.getElementById("fourier-ah-label");

    const valT1 = document.getElementById("fourier-t1-val");
    const valT2 = document.getElementById("fourier-t2-val");
    const valK = document.getElementById("fourier-k-val");
    const valQin = document.getElementById("fourier-q-in-val");
    const valR = document.getElementById("fourier-r-val");
    const valR1 = document.getElementById("fourier-r1-val");
    const valR2 = document.getElementById("fourier-r2-val");
    const valRlabel = document.getElementById("fourier-r-label");
    const valCalcL = document.getElementById("fourier-calc-l-val");

    const geomStats = document.getElementById("fourier-geom-stats");
    const valA1 = document.getElementById("fourier-a1-val");
    const valA2 = document.getElementById("fourier-a2-val");
    const valVol = document.getElementById("fourier-vol-val");

    const resultLabel = document.getElementById("fourier-result-label");
    const resultVal = document.getElementById("fourier-result-val");

    let currentMode = "calc-q";
    const canvas = document.getElementById("fourierChart");
    const ctx = canvas.getContext("2d");

    if (fourierAnimationId) {
        cancelAnimationFrame(fourierAnimationId);
    }

    let particles = [];

    function initParticles() {
        particles = [];
        const numParticles = 80;
        for (let i = 0; i < numParticles; i++) {
            particles.push({
                x: Math.random(),
                y: Math.random(),
                size: 2 + Math.random() * 2,
                angle: Math.random() * Math.PI * 2,
                r_norm: Math.random()
            });
        }
    }
    initParticles();

    const graphCanvas = document.getElementById("fourierGraph");
    const graphCtx = graphCanvas.getContext("2d");

    fourierChart = new Chart(graphCtx, {
        type: 'line',
        data: {
            labels: [0, fourierL],
            datasets: [{
                label: 'Perfil de Temperatura T(x) o T(r)',
                data: [fourierT1, fourierT2],
                borderColor: '#f59e0b',
                backgroundColor: 'rgba(245, 158, 11, 0.1)',
                borderWidth: 3,
                pointBackgroundColor: '#f59e0b',
                pointRadius: 0,
                fill: true,
                tension: 0
            }]
        },
        options: {
            legend: { display: false },
            plugins: { legend: { display: false } },
            responsive: true,
            maintainAspectRatio: false,
            animation: false,
            scales: {
                x: {
                    title: { display: true, text: 'Posición x/r (m)', color: '#94a3b8' },
                    ticks: { color: '#cbd5e1' },
                    grid: { color: 'rgba(255,255,255,0.1)' }
                },
                y: {
                    title: { display: true, text: 'Temperatura (°C)', color: '#94a3b8' },
                    ticks: { color: '#cbd5e1' },
                    grid: { color: 'rgba(255,255,255,0.1)' }
                }
            },
            plugins: {
                legend: { labels: { color: '#e2e8f0' } }
            }
        }
    });

    function formatValue(value, type) {
        if (type === "q") {
            if (!isFinite(value)) {
                return (value < 0 ? "-" : "") + "&infin; W";
            }
            const absQ = Math.abs(value);
            // LOTE Fourier rangos extremos: con k hasta 2200 W/(m·K), L
            // hasta 0.001 m y ΔT hasta ~5273 °C, q puede alcanzar el orden
            // de los GW; con k=0.001 y L=1 m también puede caer muy por
            // debajo de 1 W. Se agregan escalones TW/GW arriba y mW/µW
            // abajo para que nunca se desborde el texto ni se muestren
            // demasiados dígitos.
            if (absQ >= 1e12) {
                return `${(value / 1e12).toFixed(2)} TW`;
            } else if (absQ >= 1e9) {
                return `${(value / 1e9).toFixed(2)} GW`;
            } else if (absQ >= 1e6) {
                return `${(value / 1e6).toFixed(2)} MW`;
            } else if (absQ >= 1000) {
                return `${(value / 1000).toFixed(2)} kW`;
            } else if (absQ >= 1 || absQ === 0) {
                return `${value.toFixed(2)} W`;
            } else if (absQ >= 1e-3) {
                return `${(value * 1000).toFixed(2)} mW`;
            } else {
                return `${(value * 1e6).toFixed(2)} &micro;W`;
            }
        } else if (type === "t") {
            return `${value.toFixed(2)} &deg;C`;
        }
    }

    function getColorForTemp(T) {
        // LOTE Fourier rangos extremos: antes normalizaba sobre 0-500 °C
        // (rango antiguo del slider). Ahora se normaliza sobre el rango
        // físico completo permitido (-273 a 5000 °C) para que el gradiente
        // de color siga siendo representativo en todo el dominio nuevo.
        const TMIN = -273, TMAX = 5000;
        const normalized = Math.max(0, Math.min(1, (T - TMIN) / (TMAX - TMIN)));
        const r = Math.round(normalized * 255);
        const b = Math.round((1 - normalized) * 255);
        return `rgb(${r}, 50, ${b})`;
    }

    // LOTE Fourier — flujo de calor impuesto (q''): formateo compacto de
    // -1,000,000 a 1,000,000 W/m² en 3 escalones (W/m² · kW/m² · MW/m²),
    // sin ceros decimales sobrantes ("164" en vez de "164.00", "1.5" en
    // vez de "1.50"). computeFluxDisplay() calcula el número/unidad base;
    // formatFlux() (HTML, para el badge) y formatFluxPlain() (texto plano,
    // para el <canvas>, que NO interpreta entidades HTML como &sup2;)
    // reutilizan el mismo cálculo sin duplicar la lógica de escalones.
    function computeFluxDisplay(value) {
        const absQ = Math.abs(value);
        let scaled, unitBase;
        if (absQ >= 1e6) {
            scaled = value / 1e6; unitBase = 'MW';
        } else if (absQ >= 1000) {
            scaled = value / 1000; unitBase = 'kW';
        } else {
            scaled = value; unitBase = 'W';
        }
        let str = scaled.toFixed(2).replace(/\.?0+$/, '');
        if (str === '-0') str = '0';
        return { str, unitBase };
    }

    function formatFlux(value) {
        const { str, unitBase } = computeFluxDisplay(value);
        return `${str} ${unitBase}/m&sup2;`;
    }

    function formatFluxPlain(value) {
        const { str, unitBase } = computeFluxDisplay(value);
        return `${str} ${unitBase}/m²`;
    }

    // LOTE 3: labelAH.innerHTML se reconstruye por completo cada vez que
    // cambia la geometría (el texto y la unidad dependen de plano/
    // cilindro), lo que destruye y recrea el <input type="number"
    // id="fourier-ah-num"> junto con el resto del label — un nodo DOM
    // nuevo no conserva los listeners que syncSliderAndNumberInput() le
    // haya adjuntado antes. Este helper centraliza la reconstrucción y
    // vuelve a conectar el número recién creado con el mismo slider,
    // igual que renderLayersConfig() ya hace en #multicapa-custom-sim al
    // regenerar sus tarjetas de capa.
    function setLabelAHContent(html) {
        labelAH.innerHTML = html;
        const numEl = document.getElementById('fourier-ah-num');
        if (numEl && sliderAH) syncSliderAndNumberInput(sliderAH, numEl, updateSimulation);
    }

    function updateGeometryUI() {
        const geom = geomSelect.value;
        const formulaDiv = document.getElementById("fourier-analytical-formula");
        if (geom === "plane") {
            r1Container.style.display = "none";
            r2Container.style.display = "none";
            lContainer.style.display = "block";
            ahContainer.style.display = "block";
            // LOTE 3: fourier-l-val/fourier-ah-val ahora son <input
            // type="number"> (fourier-l-num/fourier-ah-num), sincronizados
            // por syncSliderAndNumberInput() (LOTE 2) — ya no hay badge de
            // sólo lectura que actualizar aquí.
            setLabelAHContent(`Área transversal (A): <input type="number" id="fourier-ah-num" class="sim-number-input" min="${sliderAH.min}" max="${sliderAH.max}" step="${sliderAH.step}" value="${sliderAH.value}"> m&sup2;`);
            if (geomStats) geomStats.style.display = "none";
            if (formulaDiv) formulaDiv.innerHTML = "\\[ T(x) = T_1 - (T_1 - T_2) \\frac{x}{L} \\]";
        } else if (geom === "cylinder") {
            r1Container.style.display = "block";
            r2Container.style.display = "block";
            lContainer.style.display = "none";
            ahContainer.style.display = "block";
            setLabelAHContent(`Longitud cilindro (H): <input type="number" id="fourier-ah-num" class="sim-number-input" min="${sliderAH.min}" max="${sliderAH.max}" step="${sliderAH.step}" value="${sliderAH.value}"> m`);
            if (geomStats) geomStats.style.display = "flex";
            if (formulaDiv) formulaDiv.innerHTML = "\\[ T(r) = T_1 - (T_1 - T_2) \\frac{\\ln(r/r_1)}{\\ln(r_2/r_1)} \\]";
        } else if (geom === "sphere") {
            r1Container.style.display = "block";
            r2Container.style.display = "block";
            lContainer.style.display = "none";
            ahContainer.style.display = "none";
            if (geomStats) geomStats.style.display = "flex";
            if (formulaDiv) formulaDiv.innerHTML = "\\[ T(r) = T_1 - (T_1 - T_2) \\frac{1/r_1 - 1/r}{1/r_1 - 1/r_2} \\]";
        }

        if (window.MathJax && typeof window.MathJax.typesetPromise === 'function' && formulaDiv) {
            MathJax.typesetPromise([formulaDiv]).catch(function (err) {
                console.log(err.message);
            });
        }
    }

    function updateSimulation() {
        fourierT1 = parseFloat(sliderT1.value);
        fourierK = parseFloat(sliderK.value);
        const geom = geomSelect ? geomSelect.value : "plane";

        // LOTE Fourier — flujo de calor impuesto (q''): badge de lectura
        // compacta en tiempo real junto al input numérico, independiente
        // del modo activo (se mantiene actualizado aunque el contenedor
        // esté oculto en modo "calcular q", listo para cuando se muestre).
        if (sliderQin) {
            const qFluxRaw = parseFloat(sliderQin.value);
            const qCompactBadge = document.getElementById('fourier-q-in-compact');
            if (qCompactBadge && !isNaN(qFluxRaw)) qCompactBadge.innerHTML = formatFlux(qFluxRaw);
        }

        const r1 = sliderR1 ? parseFloat(sliderR1.value) : 0.05;
        let r2 = sliderR2 ? parseFloat(sliderR2.value) : 0.15;

        // Prevent r2 from being smaller than r1
        if (geom !== "plane" && r2 < r1) {
            r2 = r1;
            if (sliderR2) sliderR2.value = r2;
        }

        if (geom === "plane") {
            fourierL = parseFloat(sliderL.value);
        } else {
            fourierL = r2 - r1;
        }

        const AH = sliderAH ? parseFloat(sliderAH.value) : 1.0;

        // LOTE 3: fourier-t1-val/fourier-k-val/fourier-l-val/fourier-ah-val
        // ahora son <input type="number"> (fourier-t1-num/fourier-k-num/
        // fourier-l-num/fourier-ah-num), sincronizados por
        // syncSliderAndNumberInput() (LOTE 2) — estas escrituras al badge
        // de sólo lectura quedaron obsoletas y se retiraron.
        if (valR1) valR1.textContent = r1.toFixed(2);
        if (valR2) valR2.textContent = r2.toFixed(2);
        if (valCalcL) valCalcL.textContent = fourierL.toFixed(3) + " m";

        let R_cond = 0;
        const isEn = (window.currentLanguage === 'en');

        if (geom === "plane") {
            R_cond = fourierL / (fourierK * AH);
            valRlabel.innerHTML = isEn ? "Thermal Resistance (R<sub>t</sub> = L/kA):" : "Resistencia Térmica (R<sub>t</sub> = L/kA):";
        } else if (geom === "cylinder") {
            if (fourierL === 0) {
                R_cond = 0;
            } else {
                R_cond = Math.log(r2 / r1) / (2 * Math.PI * fourierK * AH);
            }
            valRlabel.innerHTML = isEn ? "Thermal Resistance (R<sub>t</sub> = ln(r₂/r₁)/(2πkH)):" : "Resistencia Térmica (R<sub>t</sub> = ln(r₂/r₁)/(2πkH)):";

            if (valA1 && valA2 && valVol) {
                document.getElementById("fourier-a1-label").innerHTML = isEn ? "Internal Area (A<sub>1</sub> = 2&pi;r<sub>1</sub>H):" : "Área Interna (A<sub>1</sub> = 2&pi;r<sub>1</sub>H):";
                document.getElementById("fourier-a2-label").innerHTML = isEn ? "External Area (A<sub>2</sub> = 2&pi;r<sub>2</sub>H):" : "Área Externa (A<sub>2</sub> = 2&pi;r<sub>2</sub>H):";
                document.getElementById("fourier-vol-label").innerHTML = isEn ? "Volume (V = &pi;(r<sub>2</sub>&sup2;-r<sub>1</sub>&sup2;)H):" : "Volumen (V = &pi;(r<sub>2</sub>&sup2;-r<sub>1</sub>&sup2;)H):";
                const a1 = 2 * Math.PI * r1 * AH;
                const a2 = 2 * Math.PI * r2 * AH;
                const v = Math.PI * (r2 * r2 - r1 * r1) * AH;
                valA1.innerHTML = `${a1.toFixed(3)} m&sup2;`;
                valA2.innerHTML = `${a2.toFixed(3)} m&sup2;`;
                valVol.innerHTML = `${v.toFixed(4)} m&sup3;`;
            }
        } else if (geom === "sphere") {
            if (fourierL === 0) {
                R_cond = 0;
            } else {
                R_cond = (r2 - r1) / (4 * Math.PI * fourierK * r1 * r2);
            }
            valRlabel.innerHTML = isEn ? "Thermal Resistance (R<sub>t</sub> = (r₂-r₁)/(4πkr₁r₂)):" : "Resistencia Térmica (R<sub>t</sub> = (r₂-r₁)/(4πkr₁r₂)):";

            if (valA1 && valA2 && valVol) {
                document.getElementById("fourier-a1-label").innerHTML = isEn ? "Internal Area (A<sub>1</sub> = 4&pi;r<sub>1</sub>&sup2;):" : "Área Interna (A<sub>1</sub> = 4&pi;r<sub>1</sub>&sup2;):";
                document.getElementById("fourier-a2-label").innerHTML = isEn ? "External Area (A<sub>2</sub> = 4&pi;r<sub>2</sub>&sup2;):" : "Área Externa (A<sub>2</sub> = 4&pi;r<sub>2</sub>&sup2;):";
                document.getElementById("fourier-vol-label").innerHTML = isEn ? "Volume (V = &#8308;/&#8323;&pi;(r<sub>2</sub>&sup3;-r<sub>1</sub>&sup3;)):" : "Volumen (V = &#8308;/&#8323;&pi;(r<sub>2</sub>&sup3;-r<sub>1</sub>&sup3;)):";
                const a1 = 4 * Math.PI * r1 * r1;
                const a2 = 4 * Math.PI * r2 * r2;
                const v = (4 / 3) * Math.PI * (Math.pow(r2, 3) - Math.pow(r1, 3));
                valA1.innerHTML = `${a1.toFixed(3)} m&sup2;`;
                valA2.innerHTML = `${a2.toFixed(3)} m&sup2;`;
                valVol.innerHTML = `${v.toFixed(4)} m&sup3;`;
            }
        }

        if (valR) {
            valR.textContent = R_cond.toFixed(5) + " K/W";
        }

        let absoluteZeroReached = false;

        if (currentMode === "calc-q") {
            fourierT2 = parseFloat(sliderT2.value);
            // LOTE 3: fourier-t2-val ahora es fourier-t2-num, sincronizado
            // por syncSliderAndNumberInput().

            if (R_cond === 0) {
                if (fourierT1 === fourierT2) fourierQ = 0;
                else fourierQ = (fourierT1 > fourierT2) ? Infinity : -Infinity;
            } else {
                fourierQ = (fourierT1 - fourierT2) / R_cond;
            }

            resultLabel.innerHTML = isEn ? "Heat transfer rate (q):" : "Tasa de transferencia (q):";
            resultVal.innerHTML = formatValue(fourierQ, "q");
        } else {
            // LOTE Fourier — flujo de calor impuesto (q''): el input ya no
            // representa una tasa total en kW (como en LOTE 3), sino el
            // flujo de calor por unidad de área q'' en W/m² directamente
            // (rango ±1,000,000 W/m², sin factor de conversión ×1000).
            // Para pared plana, integrando la Ley de Fourier:
            //   T(L) = T(0) - q''·L/k          (independiente del área)
            // Se reconstruye la tasa total Q = q''·AH y se reutiliza el
            // mismo camino de cálculo (Q·R_cond) ya usado en modo
            // "calcular q", porque R_cond = L/(k·AH) ya divide por AH:
            //   Q·R_cond = (q''·AH)·(L/(k·AH)) = q''·L/k  → AH se cancela.
            // Para cilindro/esfera se preserva la semántica previa (tasa
            // total en W, AH representa la longitud H o no aplica) — un
            // flujo por unidad de área no tiene una definición simple de
            // una sola variable en esas geometrías radiales, y este LOTE
            // sólo pide la forma plana T(x) = T0 - q''x/k.
            const qFlux = parseFloat(sliderQin.value);
            const tempQ = (geom === "plane") ? (qFlux * AH) : qFlux;

            let computedT2 = fourierT1 - (tempQ * R_cond);

            if (computedT2 <= -273.15) {
                fourierT2 = -273.15;
                absoluteZeroReached = true;
                if (R_cond === 0) {
                    fourierQ = (fourierT1 === fourierT2) ? 0 : ((fourierT1 > fourierT2) ? Infinity : -Infinity);
                } else {
                    fourierQ = (fourierT1 - fourierT2) / R_cond;
                }
            } else {
                fourierT2 = computedT2;
                fourierQ = tempQ;
            }

            resultLabel.innerHTML = isEn ? "Temperature T<sub>2</sub> (Outer):" : "Temperatura T<sub>2</sub> (Externa):";
            resultVal.innerHTML = formatValue(fourierT2, "t");
        }

        const warningEl = document.getElementById("fourier-limit-warning");
        if (warningEl) {
            warningEl.style.display = absoluteZeroReached ? "block" : "none";
        }

        // LOTE Fourier rangos extremos: la escala anterior forzaba
        // siempre un mínimo de 500°C visibles y un piso en 0°C, lo cual
        // con el nuevo rango físico (-273 a 5000 °C) dejaba franjas
        // enormes de espacio vacío (o, en el extremo opuesto, casi
        // recortaba el perfil si T1/T2 se acercaban a 5000). Ahora la
        // escala se autoajusta siempre a los valores actuales de T1/T2
        // con un margen proporcional, sin piso ni techo fijos.
        const tMin = Math.min(fourierT1, fourierT2);
        const tMax = Math.max(fourierT1, fourierT2);
        const margin = Math.max(10, (tMax - tMin) * 0.1);
        let minY = tMin - margin;
        let maxY = tMax + margin;
        fourierChart.options.scales.y.min = minY;
        fourierChart.options.scales.y.max = maxY;

        let points_x = [];
        let points_y = [];
        const steps = 20;

        if (geom === "plane") {
            for (let i = 0; i <= steps; i++) {
                let f = i / steps;
                points_x.push(fourierL * f);
                points_y.push(fourierT1 - f * (fourierT1 - fourierT2));
            }
        } else if (geom === "cylinder") {
            if (fourierL === 0) {
                points_x.push(r1); points_y.push(fourierT1);
                points_x.push(r1); points_y.push(fourierT2);
            } else {
                for (let i = 0; i <= steps; i++) {
                    let f = i / steps;
                    let r = r1 + f * fourierL;
                    points_x.push(r);
                    let Tr = fourierT1 - fourierQ * Math.log(r / r1) / (2 * Math.PI * fourierK * AH);
                    if (!isFinite(Tr)) Tr = fourierT1; // fallback if infinite flow
                    points_y.push(Tr);
                }
            }
        } else if (geom === "sphere") {
            if (fourierL === 0) {
                points_x.push(r1); points_y.push(fourierT1);
                points_x.push(r1); points_y.push(fourierT2);
            } else {
                for (let i = 0; i <= steps; i++) {
                    let f = i / steps;
                    let r = r1 + f * fourierL;
                    points_x.push(r);
                    let Tr = fourierT1 - fourierQ * (r - r1) / (4 * Math.PI * fourierK * r1 * r);
                    if (!isFinite(Tr)) Tr = fourierT1;
                    points_y.push(Tr);
                }
            }
        }

        fourierChart.data.labels = points_x.map(x => x.toFixed(3));
        fourierChart.data.datasets[0].data = points_y;

        const color = (fourierT1 >= fourierT2) ? '#ef4444' : '#3b82f6';
        fourierChart.data.datasets[0].borderColor = color;
        fourierChart.data.datasets[0].pointBackgroundColor = color;
        fourierChart.data.datasets[0].backgroundColor = (fourierT1 >= fourierT2) ? 'rgba(239, 68, 68, 0.15)' : 'rgba(59, 130, 246, 0.15)';

        fourierChart.update('none');
    }

    function draw() {
        const parent = canvas.parentElement;
        if (canvas.width !== parent.clientWidth || canvas.height !== parent.clientHeight) {
            canvas.width = parent.clientWidth;
            canvas.height = parent.clientHeight;
        }

        ctx.clearRect(0, 0, canvas.width, canvas.height);
        const w = canvas.width;
        const h = canvas.height;
        const geom = geomSelect ? geomSelect.value : "plane";

        const absQ = Math.abs(fourierQ);
        const direction = Math.sign(fourierQ);

        let speedMultiplier = 0;
        if (isFinite(absQ)) {
            speedMultiplier = direction * Math.sqrt(absQ) * 0.00015;
        } else {
            speedMultiplier = direction * 0.02; // max speed for infinity
        }

        const maxSpeed = 0.02;
        if (speedMultiplier > maxSpeed) speedMultiplier = maxSpeed;
        if (speedMultiplier < -maxSpeed) speedMultiplier = -maxSpeed;
        const hasActiveFlow = Math.abs(fourierT1 - fourierT2) > 0.5 && fourierL > 0;

        if (geom === "plane") {
            const minWallWidth = w * 0.1;
            const maxWallWidth = w * 0.7;
            // LOTE Fourier rangos extremos: antes usaba 0.01/1.0
            // hardcodeados como límites de L para mapear el ancho visual;
            // ahora lee min/max reales del slider (0.001 a 1.0 m) para que
            // el mapeo siga siendo válido si el rango físico cambia de
            // nuevo en el futuro.
            const Lmin = parseFloat(sliderL.min) || 0.001;
            const Lmax = parseFloat(sliderL.max) || 1.0;
            const wallWidth = (fourierL <= 0 || Lmax === Lmin) ? 2 : minWallWidth + (fourierL - Lmin) / (Lmax - Lmin) * (maxWallWidth - minWallWidth);
            const wallLeft = (w - wallWidth) / 2;
            const wallRight = wallLeft + wallWidth;
            const wallTop = h * 0.15;
            const wallHeight = h * 0.7;

            const wallGrad = ctx.createLinearGradient(wallLeft, 0, wallRight, 0);
            wallGrad.addColorStop(0, getColorForTemp(fourierT1));
            wallGrad.addColorStop(1, getColorForTemp(fourierT2));

            ctx.fillStyle = wallGrad;
            ctx.fillRect(wallLeft, wallTop, wallWidth, wallHeight);
            ctx.strokeStyle = "rgba(255,255,255,0.3)";
            ctx.lineWidth = 2;
            ctx.strokeRect(wallLeft, wallTop, wallWidth, wallHeight);

            ctx.fillStyle = "rgba(255, 255, 255, 0.75)";
            particles.forEach(p => {
                if (hasActiveFlow) p.x += speedMultiplier;
                else p.x += (Math.random() - 0.5) * 0.001;

                if (p.x > 1.0) p.x = 0;
                if (p.x < 0) p.x = 1.0;
                const px = wallLeft + p.x * wallWidth;
                const py = wallTop + p.y * wallHeight;
                ctx.beginPath(); ctx.arc(px, py, p.size, 0, Math.PI * 2); ctx.fill();
            });

            ctx.fillStyle = "#ffffff"; ctx.font = "bold 14px Outfit";
            ctx.textAlign = "right"; ctx.fillText(`T₁ = ${fourierT1.toFixed(0)}°C`, wallLeft - 10, h * 0.5);
            ctx.textAlign = "left"; ctx.fillText(`T₂ = ${fourierT2.toFixed(0)}°C`, wallRight + 10, h * 0.5);

            // LOTE Fourier — flujo de calor impuesto (q''): flecha
            // direccional sobre la pared, sólo en modo "calcular T₂"
            // (frontera de flujo impuesto) y sólo para pared plana (única
            // geometría con fórmula q'' pedida en este LOTE). El largo se
            // escala en log10 sobre el rango completo ±1,000,000 W/m² para
            // que tanto valores pequeños (1 W/m²) como el máximo permitido
            // produzcan una flecha visualmente distinguible sin salirse
            // nunca del ancho de la pared (clamp a maxArrowLen).
            if (currentMode === "calc-t2") {
                const qFluxNow = parseFloat(sliderQin.value);
                if (!isNaN(qFluxNow) && qFluxNow !== 0) {
                    const arrowY = wallTop - 22;
                    const minArrowLen = 18;
                    const maxArrowLen = Math.max(minArrowLen, wallWidth * 0.6);
                    const logMag = Math.log10(Math.abs(qFluxNow) + 1);
                    const logMax = Math.log10(1000001);
                    const norm = Math.max(0, Math.min(1, logMag / logMax));
                    const arrowLen = minArrowLen + norm * (maxArrowLen - minArrowLen);
                    const dir = Math.sign(qFluxNow);
                    const midX = (wallLeft + wallRight) / 2;
                    const startX = midX - dir * (arrowLen / 2);
                    const endX = midX + dir * (arrowLen / 2);

                    ctx.save();
                    ctx.strokeStyle = "#fbbf24";
                    ctx.fillStyle = "#fbbf24";
                    ctx.lineWidth = 3;
                    ctx.beginPath();
                    ctx.moveTo(startX, arrowY);
                    ctx.lineTo(endX, arrowY);
                    ctx.stroke();

                    const headSize = 7;
                    ctx.beginPath();
                    ctx.moveTo(endX, arrowY);
                    ctx.lineTo(endX - dir * headSize, arrowY - headSize * 0.6);
                    ctx.lineTo(endX - dir * headSize, arrowY + headSize * 0.6);
                    ctx.closePath();
                    ctx.fill();

                    ctx.font = "bold 11px Outfit";
                    ctx.textAlign = "center";
                    ctx.fillText(formatFluxPlain(qFluxNow), midX, arrowY - 8);
                    ctx.restore();
                }
            }

        } else {
            const cx = w / 2;
            const cy = h / 2;
            const maxR = Math.min(w, h) * 0.45;
            const r1 = sliderR1 ? parseFloat(sliderR1.value) : 0.05;
            let r2 = sliderR2 ? parseFloat(sliderR2.value) : 0.15;
            if (r2 < r1) r2 = r1;

            // Map physical radius to pixels
            const r_inner_px = maxR * (r1 / r2) || 0.1;
            const r_outer_px = maxR;

            ctx.fillStyle = "rgba(0,0,0,0.1)";
            ctx.fillRect(0, 0, w, h);

            // Handle zero thickness gracefully visually
            if (r2 === r1) {
                ctx.beginPath();
                ctx.arc(cx, cy, r_outer_px, 0, Math.PI * 2);
                ctx.strokeStyle = getColorForTemp(fourierT1);
                ctx.lineWidth = 4;
                ctx.stroke();
            } else {
                const rGrad = ctx.createRadialGradient(cx, cy, r_inner_px, cx, cy, r_outer_px);
                rGrad.addColorStop(0, getColorForTemp(fourierT1));
                rGrad.addColorStop(1, getColorForTemp(fourierT2));

                ctx.beginPath();
                ctx.arc(cx, cy, r_outer_px, 0, Math.PI * 2);
                ctx.arc(cx, cy, r_inner_px, 0, Math.PI * 2, true);
                ctx.fillStyle = rGrad;
                ctx.fill();

                ctx.strokeStyle = "rgba(255,255,255,0.4)";
                ctx.lineWidth = 2;
                ctx.stroke();

                ctx.beginPath();
                ctx.arc(cx, cy, r_inner_px, 0, Math.PI * 2);
                ctx.fillStyle = "rgba(0,0,0,0.6)";
                ctx.fill();
                ctx.stroke();

                ctx.fillStyle = "rgba(255, 255, 255, 0.75)";
                particles.forEach(p => {
                    if (hasActiveFlow) p.r_norm += speedMultiplier;
                    else p.r_norm += (Math.random() - 0.5) * 0.001;

                    if (p.r_norm > 1.0) p.r_norm = 0;
                    if (p.r_norm < 0) p.r_norm = 1.0;

                    const pr = r_inner_px + p.r_norm * (r_outer_px - r_inner_px);
                    const px = cx + Math.cos(p.angle) * pr;
                    const py = cy + Math.sin(p.angle) * pr;
                    ctx.beginPath(); ctx.arc(px, py, p.size, 0, Math.PI * 2); ctx.fill();
                });
            }

            // Draw dimension lines
            ctx.strokeStyle = "rgba(255, 255, 255, 0.5)";
            ctx.lineWidth = 1;
            ctx.setLineDash([5, 5]);

            // r1 line (draw upwards slightly angled to not overlap with text)
            ctx.beginPath();
            ctx.moveTo(cx, cy);
            ctx.lineTo(cx - r_inner_px * 0.707, cy - r_inner_px * 0.707);
            ctx.stroke();

            // r2 line (draw straight right)
            ctx.beginPath();
            ctx.moveTo(cx, cy);
            ctx.lineTo(cx + r_outer_px, cy);
            ctx.stroke();

            ctx.setLineDash([]);

            // Draw labels for dimensions
            ctx.fillStyle = "rgba(255, 255, 255, 0.9)";
            ctx.font = "13px Outfit";
            ctx.textAlign = "right";
            ctx.fillText("r₁", cx - r_inner_px * 0.707 - 5, cy - r_inner_px * 0.707 - 5);
            ctx.textAlign = "center";
            ctx.fillText("r₂", cx + r_outer_px / 2, cy - 8);

            ctx.fillStyle = "#ffffff"; ctx.font = "bold 14px Outfit";
            ctx.textAlign = "center";
            ctx.fillText(`T₁=${fourierT1.toFixed(0)}°C`, cx, cy + 5);
            ctx.textAlign = "left";
            ctx.fillText(`T₂=${fourierT2.toFixed(0)}°C`, cx + r_outer_px + 10, cy);
        }

        fourierAnimationId = requestAnimationFrame(draw);
    }

    if (geomSelect) geomSelect.addEventListener("change", () => {
        updateGeometryUI();
        updateSimulation();
    });

    if (modeSelect) modeSelect.addEventListener("change", (e) => {
        currentMode = e.target.value;
        if (currentMode === "calc-q") {
            t2Container.style.display = "block";
            qInContainer.style.display = "none";
        } else {
            t2Container.style.display = "none";
            qInContainer.style.display = "block";
        }
        updateSimulation();
    });

    [sliderT1, sliderT2, sliderQin, sliderK, sliderL, sliderR1, sliderR2, sliderAH].forEach(el => {
        if (el) el.addEventListener('input', updateSimulation);
    });

    // LOTE 3 — entrada numérica directa: conecta cada slider con su
    // <input type="number"> hermano (mismo id + "-num") vía el helper
    // global del LOTE 2, reutilizando updateSimulation sin duplicarla.
    [
        ['fourier-t1-num', sliderT1], ['fourier-t2-num', sliderT2], ['fourier-q-in-num', sliderQin],
        ['fourier-k-num', sliderK], ['fourier-l-num', sliderL], ['fourier-r1-num', sliderR1],
        ['fourier-r2-num', sliderR2], ['fourier-ah-num', sliderAH]
    ].forEach(([numId, sliderEl]) => {
        const numEl = document.getElementById(numId);
        if (numEl && sliderEl) syncSliderAndNumberInput(sliderEl, numEl, updateSimulation);
    });

    window.addEventListener('resize', () => {
        if (document.getElementById('fourier-sim').classList.contains('active')) {
            if (fourierChart) fourierChart.resize();
        }
    });

    const observer = new IntersectionObserver((entries) => {
        if (entries[0].isIntersecting) {
            updateSimulation();
            if (fourierChart) fourierChart.resize();
        }
    });
    observer.observe(canvas);

    updateGeometryUI();
    updateSimulation();
    draw();
}

// ==========================================
// Newton's Cooling Simulation
// ==========================================
function initNewtonSimulation_OLD_UNUSED() {
    const canvas = document.getElementById('newtonCanvas');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');

    const sliderTi = document.getElementById('newton-ti');
    const sliderTinf = document.getElementById('newton-tinf');
    const selectMedium = document.getElementById('newton-medium');
    const sliderD = document.getElementById('newton-d');

    const valTi = document.getElementById('newton-ti-val');
    const valTinf = document.getElementById('newton-tinf-val');
    const valD = document.getElementById('newton-d-val');
    const resBi = document.getElementById('newton-bi-res');
    const resTau = document.getElementById('newton-tau-res');
    const resTime = document.getElementById('newton-time');

    const graphCanvas = document.getElementById('newtonGraph');
    const graphCtx = graphCanvas.getContext('2d');

    // Propiedades del hierro puro
    const rho = 7870; // kg/m^3
    const cp = 450; // J/kg.K
    const k_hierro = 80.2; // W/m.K
    const L_cylinder = 0.1; // m (Longitud del cilindro)

    let chartInstance = new Chart(graphCtx, {
        type: 'line',
        data: {
            datasets: [{
                label: 'T(t) Cilindro de Hierro',
                data: [],
                borderColor: '#ef4444',
                backgroundColor: 'rgba(239, 68, 68, 0.1)',
                borderWidth: 2,
                pointRadius: 0,
                fill: true,
                tension: 0.1
            }]
        },
        options: {
            legend: { display: false },
            plugins: { legend: { display: false } },
            responsive: true,
            maintainAspectRatio: false,
            animation: false,
            scales: {
                x: {
                    type: 'linear',
                    title: { display: true, text: 'Tiempo (s)', color: '#94a3b8' },
                    ticks: { color: '#cbd5e1' },
                    grid: { color: 'rgba(255,255,255,0.1)' }
                },
                y: {
                    title: { display: true, text: 'Temperatura (°C)', color: '#94a3b8' },
                    ticks: { color: '#cbd5e1' },
                    grid: { color: 'rgba(255,255,255,0.1)' }
                }
            },
            plugins: {
                legend: { labels: { color: '#e2e8f0' } }
            }
        }
    });

    let animationId;
    let simTime = 0;
    let particles = [];
    const timeScale = 50; // Acelerador de tiempo
    let lastTimestamp = 0;

    // Parámetros actuales
    let currentTi, currentTinf, currentH, currentD;
    let currentTau, currentBi;

    function initParticles() {
        particles = [];
        const numParticles = 100;
        for (let i = 0; i < numParticles; i++) {
            particles.push({
                x: Math.random() * canvas.width,
                y: Math.random() * canvas.height,
                vx: (Math.random() - 0.5) * 2,
                vy: (Math.random() - 0.5) * 2 - 1
            });
        }
    }

    function updateSimulationParams() {
        currentTi = parseFloat(sliderTi.value);
        currentTinf = parseFloat(sliderTinf.value);
        currentH = parseFloat(selectMedium.value);
        currentD = parseFloat(sliderD.value);

        valTi.textContent = currentTi;
        valTinf.textContent = currentTinf;
        valD.textContent = currentD.toFixed(2);

        // Área superficial y Volumen
        const r = currentD / 2;
        const As = 2 * Math.PI * r * L_cylinder + 2 * Math.PI * r * r;
        const V = Math.PI * r * r * L_cylinder;
        const Lc = V / As;

        currentBi = (currentH * Lc) / k_hierro;
        currentTau = (rho * V * cp) / (currentH * As);

        resBi.innerHTML = currentBi.toFixed(4) + (currentBi < 0.1 ? " <span style='color:#10b981;'>(Válido)</span>" : " <span style='color:#ef4444;'>(Inválido)</span>");
        resTau.innerHTML = currentTau.toFixed(1) + " s";

        simTime = 0; // Reiniciar simulación
        lastTimestamp = performance.now();
        initParticles();

        // Pre-calcular la gráfica teórica (hasta 5 Tau)
        const tMax = currentTau * 5;
        const graphData = [];
        for (let t = 0; t <= tMax; t += tMax / 50) {
            const T = currentTinf + (currentTi - currentTinf) * Math.exp(-t / currentTau);
            graphData.push({ x: t, y: T });
        }
        chartInstance.data.datasets[0].data = graphData;

        const maxTemp = Math.max(currentTi, currentTinf);
        const minTemp = Math.min(currentTi, currentTinf);
        const yMax = maxTemp > 500 ? Math.ceil(maxTemp / 100) * 100 : (Math.ceil(maxTemp / 10) * 10 + 10);
        const yMin = minTemp < 0 ? Math.floor(minTemp / 10) * 10 : (minTemp > 20 ? 0 : Math.floor(minTemp / 10) * 10 - 10);
        chartInstance.options.scales.y.max = yMax;
        chartInstance.options.scales.y.min = yMin;
        currentChartMax = tMax;
        chartInstance.options.scales.x.max = tMax;
        chartInstance.options.scales.x.ticks.stepSize = tMax <= 200 ? 10 : 100;

        // Update markers
        chartInstance.data.datasets[4].data = [
            { x: simTime, y: yMin },
            { x: simTime, y: yMax }
        ];
        chartInstance.data.datasets[5].data = simData.map((d) => {
            const T = currentTinf + (currentTi - currentTinf) * Math.exp(-simTime / d.tau);
            return { x: simTime, y: T };
        });

        chartInstance.update();
    }

    function getColorForTemp(T) {
        const minT = 0;
        const maxT = 500;
        const normalized = Math.max(0, Math.min(1, (T - minT) / (maxT - minT)));
        const r = Math.round(normalized * 255);
        const b = Math.round((1 - normalized) * 255);
        return `rgb(${r}, 50, ${b})`;
    }

    function draw(timestamp) {
        if (!lastTimestamp) lastTimestamp = timestamp;
        const dt = (timestamp - lastTimestamp) / 1000; // segundos reales
        lastTimestamp = timestamp;

        simTime += dt * timeScale;
        resTime.innerHTML = simTime.toFixed(1) + " s";

        // Temperatura actual del cilindro
        const currentT = currentTinf + (currentTi - currentTinf) * Math.exp(-simTime / currentTau);

        // Make canvas responsive
        const parent = canvas.parentElement;
        if (canvas.width !== parent.clientWidth || canvas.height !== parent.clientHeight) {
            canvas.width = parent.clientWidth;
            canvas.height = parent.clientHeight;
            initParticles();
        }

        // Efecto de desvanecimiento para estelas
        ctx.fillStyle = 'rgba(15, 23, 42, 0.3)';
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        const cx = canvas.width / 2;
        const cy = canvas.height / 2;

        // Escala visual del cilindro basada en el diámetro (0.01 a 0.2 m -> 20 a 100 px radio)
        const minR = 20;
        const maxR = 100;
        const visualR = minR + ((currentD - 0.01) / (0.2 - 0.01)) * (maxR - minR);

        // Actualizar y dibujar partículas de convección (fluido)
        ctx.fillStyle = getColorForTemp(currentTinf);
        particles.forEach(p => {
            // Acelerar partículas según la diferencia de temperatura
            const deltaT = currentT - currentTinf;
            // Si el cilindro está más caliente, las partículas suben más rápido cerca del cilindro
            const dist = Math.hypot(p.x - cx, p.y - cy);

            let speedFactor = 1;
            if (dist < visualR * 3) {
                speedFactor = 1 + (deltaT / 100) * (1 - dist / (visualR * 3));
            }

            p.x += p.vx * speedFactor;
            p.y += p.vy * speedFactor;

            // Reaparecer partículas que salen de la pantalla
            if (p.x < 0 || p.x > canvas.width || p.y < 0 || p.y > canvas.height) {
                if (Math.random() > 0.5) {
                    p.x = Math.random() * canvas.width;
                    p.y = canvas.height;
                } else {
                    p.x = Math.random() > 0.5 ? 0 : canvas.width;
                    p.y = Math.random() * canvas.height;
                }
                // Si la distancia al centro es muy grande, forzar a que reaparezca más cerca a veces
                if (Math.random() > 0.7) {
                    p.x = cx + (Math.random() - 0.5) * visualR * 4;
                    p.y = cy + (Math.random() - 0.5) * visualR * 4;
                }
            }

            ctx.beginPath();
            ctx.arc(p.x, p.y, 2, 0, Math.PI * 2);
            ctx.fill();
        });

        // Dibujar el cilindro
        ctx.beginPath();
        ctx.arc(cx, cy, visualR, 0, Math.PI * 2);
        ctx.fillStyle = getColorForTemp(currentT);
        ctx.fill();
        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = 2;
        ctx.stroke();

        // Texto de temperatura
        ctx.fillStyle = '#ffffff';
        ctx.font = 'bold 16px Outfit';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(`${currentT.toFixed(1)} °C`, cx, cy);

        animationId = requestAnimationFrame(draw);
    }

    [sliderTi, sliderTinf, selectMedium, sliderD].forEach(el => {
        el.addEventListener('input', updateSimulationParams);
    });

    // Intersection Observer para detener/iniciar animación
    const observer = new IntersectionObserver((entries) => {
        if (entries[0].isIntersecting) {
            updateSimulationParams();
            lastTimestamp = performance.now();
            animationId = requestAnimationFrame(draw);
        } else {
            if (animationId) cancelAnimationFrame(animationId);
        }
    });

    observer.observe(canvas);
}

// ==========================================
// Conduction + Convection Simulation
// ==========================================
// ==========================================
// 12. NUSSELT SIMULATION
// ==========================================
function initNusseltSimulation_OLD_UNUSED() {
    const uSlider = document.getElementById("nu-u");
    const kSlider = document.getElementById("nu-k");
    const lcSlider = document.getElementById("nu-lc");
    const tsSlider = document.getElementById("nu-ts");
    const tinfSlider = document.getElementById("nu-tinf");

    const uVal = document.getElementById("nu-u-val");
    const kVal = document.getElementById("nu-k-val");
    const lcVal = document.getElementById("nu-lc-val");
    const tsVal = document.getElementById("nu-ts-val");
    const tinfVal = document.getElementById("nu-tinf-val");

    const resQCond = document.getElementById("nu-qcond-res");
    const resQConv = document.getElementById("nu-qconv-res");
    const resNu = document.getElementById("nu-res");

    const canvas = document.getElementById("nusseltChart");
    if (!canvas) return;
    const ctx = canvas.getContext("2d");

    let chartInstance = new Chart(ctx, {
        type: "line",
        data: {
            datasets: [
                {
                    label: "Conducción Pura (Fluido estático)",
                    data: [],
                    borderColor: "#94a3b8",
                    backgroundColor: "rgba(148, 163, 184, 0.1)",
                    borderWidth: 2,
                    borderDash: [5, 5],
                    fill: false,
                    tension: 0
                },
                {
                    label: "Convección (Fluido en movimiento)",
                    data: [],
                    borderColor: "#38bdf8",
                    backgroundColor: "rgba(56, 189, 248, 0.2)",
                    borderWidth: 3,
                    fill: true,
                    tension: 0.4
                }
            ]
        },
        options: {
            legend: { display: false },
            plugins: { legend: { display: false } },
            responsive: true,
            maintainAspectRatio: false,
            animation: false,
            scales: {
                x: {
                    type: "linear",
                    min: 0,
                    max: 0.2, // max Lc is 0.2
                    title: { display: true, text: "Distancia desde la pared (y)", color: "#94a3b8" },
                    ticks: { color: "#cbd5e1" },
                    grid: { color: "rgba(255,255,255,0.1)" }
                },
                y: {
                    min: 20,
                    max: 100,
                    title: { display: true, text: "Temperatura (°C)", color: "#94a3b8" },
                    ticks: { color: "#cbd5e1" },
                    grid: { color: "rgba(255,255,255,0.1)" }
                }
            },
            plugins: {
                legend: { labels: { color: "#e2e8f0" } }
            }
        }
    });

    function updateSimulation() {
        const u = parseFloat(uSlider.value);
        const k = parseFloat(kSlider.value);
        const Lc = parseFloat(lcSlider.value);

        uVal.textContent = u.toFixed(1);
        kVal.textContent = k.toFixed(2);
        lcVal.textContent = Lc.toFixed(2);

        // Temperatures
        const Ts = 100; // Wall temp
        const Tinf = 20; // Fluid free stream temp

        // If u = 0, it's pure conduction. Nu = 1.
        // As u increases, h increases. Let's assume h = (k/Lc) * (1 + C * u^0.8)
        // So Nu = 1 + C * u^0.8
        const C = 2.5; // Arbitrary constant for visual effect
        let Nu = 1.0;
        if (u > 0) {
            Nu = 1.0 + C * Math.pow(u, 0.8);
        }

        const h = (k / Lc) * Nu;

        const q_cond = k * (Ts - Tinf) / Lc;
        const q_conv = h * (Ts - Tinf);

        resQCond.textContent = q_cond.toFixed(1) + " W/m²";
        resQConv.textContent = q_conv.toFixed(1) + " W/m²";
        resNu.textContent = Nu.toFixed(2);

        // Update Chart
        chartInstance.options.scales.x.max = Math.max(0.2, Lc);

        const condData = [];
        const convData = [];

        const numPoints = 50;
        for (let i = 0; i <= numPoints; i++) {
            const y = (i / numPoints) * Lc;

            // Conduction Profile (Linear from Ts at y=0 to Tinf at y=Lc)
            const T_cond = Ts - (Ts - Tinf) * (y / Lc);
            condData.push({ x: y, y: T_cond });

            // Convection Profile
            // Must have gradient at wall equal to -h(Ts-Tinf)/k = -Nu*(Ts-Tinf)/Lc
            // A simple profile that matches Ts at y=0, Tinf at y=Lc, and has the correct initial slope:
            // T(y) = Tinf + (Ts - Tinf) * (1 - y/Lc)^Nu
            const T_conv = Tinf + (Ts - Tinf) * Math.pow(1 - y / Lc, Nu);
            convData.push({ x: y, y: T_conv });
        }

        chartInstance.data.datasets[0].data = condData;
        chartInstance.data.datasets[1].data = convData;
        chartInstance.update();
    }

    uSlider.addEventListener("input", updateSimulation);
    kSlider.addEventListener("input", updateSimulation);
    lcSlider.addEventListener("input", updateSimulation);
    if (tsSlider) tsSlider.addEventListener("input", updateSimulation);
    if (tinfSlider) tinfSlider.addEventListener("input", updateSimulation);

    // Initial call
    updateSimulation();
}

/* =========================================================================
   BOUNDARY LAYER & ANALOGY SIMULATOR
   ========================================================================= */
function initBoundaryLayerSimulation_OLD_UNUSED() {
    const prSlider = document.getElementById("bl-pr");
    const scSlider = document.getElementById("bl-sc");

    const prVal = document.getElementById("bl-pr-val");
    const scVal = document.getElementById("bl-sc-val");

    const resDeltaT = document.getElementById("bl-deltat-res");
    const resDeltaC = document.getElementById("bl-deltac-res");

    const canvas = document.getElementById("blChart");
    if (!canvas) return;
    const ctx = canvas.getContext("2d");

    let chartInstance = new Chart(ctx, {
        type: "line",
        data: {
            datasets: [
                {
                    label: "Velocidad (u/Uinfinity)",
                    data: [],
                    borderColor: "#3b82f6",
                    backgroundColor: "rgba(59, 130, 246, 0.1)",
                    borderWidth: 2,
                    fill: true,
                    tension: 0.4
                },
                {
                    label: "Temperatura ((T-Ts)/(Tinf-Ts))",
                    data: [],
                    borderColor: "#ef4444",
                    backgroundColor: "rgba(239, 68, 68, 0.1)",
                    borderWidth: 2,
                    borderDash: [5, 5],
                    fill: false,
                    tension: 0.4
                },
                {
                    label: "Concentración ((C-Cs)/(Cinf-Cs))",
                    data: [],
                    borderColor: "#10b981",
                    backgroundColor: "rgba(16, 185, 129, 0.1)",
                    borderWidth: 2,
                    borderDash: [2, 2],
                    fill: false,
                    tension: 0.4
                }
            ]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                x: {
                    type: "linear",
                    position: "bottom",
                    title: {
                        display: true,
                        text: "Distancia desde la pared (y/δ)",
                        color: "#94a3b8"
                    },
                    min: 0,
                    max: 1.5,
                    grid: { color: "#334155" },
                    ticks: {
                        color: "#94a3b8",
                        callback: function (value) {
                            if (value === 0) return '0 (Pared)';
                            if (value === 1) return '1 (Borde de Capa)';
                            return value;
                        }
                    }
                },
                y: {
                    title: {
                        display: true,
                        text: "Perfil Adimensional (Velocidad, Temperatura, Masa)",
                        color: "#94a3b8"
                    },
                    min: 0,
                    max: 1.05,
                    grid: { color: "#334155" },
                    ticks: {
                        color: "#94a3b8",
                        callback: function (value) {
                            if (value === 0) return '0 (Superficie)';
                            if (value === 1) return '1 (Infinito)';
                            return value;
                        }
                    }
                }
            },
            plugins: {
                legend: { labels: { color: "#cbd5e1" } }
            }
        }
    });

    function updateSimulation() {
        const Pr = parseFloat(prSlider.value);
        const Sc = parseFloat(scSlider.value);

        prVal.textContent = Pr.toFixed(1);
        scVal.textContent = Sc.toFixed(1);

        // Relaciones empíricas de espesor de capa límite
        const delta_t_ratio = Math.pow(Pr, -1 / 3);
        const delta_c_ratio = Math.pow(Sc, -1 / 3);

        resDeltaT.textContent = delta_t_ratio.toFixed(2) + " δ";
        resDeltaC.textContent = delta_c_ratio.toFixed(2) + " δ";

        const velData = [];
        const tempData = [];
        const concData = [];

        // Eje y va de 0 a 1.5 (donde 1.0 es el borde de la capa límite hidrodinámica)
        const numPoints = 50;
        for (let i = 0; i <= numPoints; i++) {
            const y = (i / numPoints) * 1.5;

            // Perfil de velocidad (Polinomio de orden 2, aproximación de Von Kármán)
            // u/Uinfinity = 2(y/δ) - (y/δ)^2 for y/δ <= 1, else 1
            let u_ratio = 1.0;
            if (y <= 1.0) {
                u_ratio = 2 * y - Math.pow(y, 2);
            }
            velData.push({ x: y, y: u_ratio });

            // Perfil de Temperatura
            // y_t = y / (δ_t) = y / (δ * delta_t_ratio)
            let y_t = y / delta_t_ratio;
            let t_ratio = 1.0;
            if (y_t <= 1.0) {
                t_ratio = 2 * y_t - Math.pow(y_t, 2);
            }
            tempData.push({ x: y, y: t_ratio });

            // Perfil de Concentración
            let y_c = y / delta_c_ratio;
            let c_ratio = 1.0;
            if (y_c <= 1.0) {
                c_ratio = 2 * y_c - Math.pow(y_c, 2);
            }
            concData.push({ x: y, y: c_ratio });
        }

        chartInstance.data.datasets[0].data = velData;
        chartInstance.data.datasets[1].data = tempData;
        chartInstance.data.datasets[2].data = concData;

        chartInstance.update();
    }

    prSlider.addEventListener('input', updateSimulation);
    scSlider.addEventListener('input', updateSimulation);

    updateSimulation();
}

// Planck's Law and Wavelength to Color Helper Functions
function calculatePlanck(lambda, T) {
    // Planck's Law: E_lambda = (C1) / (lambda^5 * (exp(C2 / (lambda * T)) - 1))
    // lambda is in micrometers, T is in Kelvin
    // C1 = 2 * pi * h * c^2 = 3.74177e8 W * um^4 / m^2
    // C2 = h * c / k_B = 1.43878e4 um * K
    // The result is spectral emissive power E_lambda in kW / (m^2 * nm) (which is equivalent to MW / (m^2 * um))
    const C1 = 3.74177e8;
    const C2 = 1.43878e4;

    const exponent = C2 / (lambda * T);
    if (exponent > 100) return 0; // Prevent overflow in Math.exp

    const spectralRadiance = C1 / (Math.pow(lambda, 5) * (Math.exp(exponent) - 1));
    // Scale value to match standard display ranges (e.g., peak of ~80 kW/(m²·nm) at 5800 K)
    // 1 W / (m^2 * m) = 1e-9 W / (m^2 * nm) = 1e-12 kW / (m^2 * nm)
    // Using scaled constant C1 gives output in W / (m^2 * um) = 1e-6 W / (m^2 * nm) = 1e-9 kW / (m^2 * nm)
    // To match typical spectral emissive power in kW / (m^2 * nm), we divide by 1000.
    return spectralRadiance / 1000;
}

function getWavelengthColor(lambda) {
    // lambda is in micrometers. Convert to nanometers.
    const wl = lambda * 1000;

    // Simple RGB conversion from wavelength (wl in nm)
    let r = 0, g = 0, b = 0;

    if (wl < 0.01) {
        return { name: "Rayos Gamma", color: "#4c1d95" }; // Deep purple
    } else if (wl >= 0.01 && wl < 10) {
        return { name: "Rayos X", color: "#7c3aed" }; // Neon purple
    } else if (wl >= 10 && wl < 380) {
        return { name: "Ultravioleta (UV)", color: "#a78bfa" }; // Light purple
    } else if (wl >= 380 && wl < 440) {
        r = -(wl - 440) / (440 - 380);
        g = 0.0;
        b = 1.0;
    } else if (wl >= 440 && wl < 490) {
        r = 0.0;
        g = (wl - 440) / (490 - 440);
        b = 1.0;
    } else if (wl >= 490 && wl < 510) {
        r = 0.0;
        g = 1.0;
        b = -(wl - 510) / (510 - 490);
    } else if (wl >= 510 && wl < 580) {
        r = (wl - 510) / (580 - 510);
        g = 1.0;
        b = 0.0;
    } else if (wl >= 580 && wl < 645) {
        r = 1.0;
        g = -(wl - 645) / (645 - 580);
        b = 0.0;
    } else if (wl >= 645 && wl <= 780) {
        r = 1.0;
        g = 0.0;
        b = 0.0;
    } else if (wl < 380) {
        // Ultraviolet representation (violet/purple/grey blend)
        return { name: "Ultravioleta (Invisible)", color: "#7c3aed" };
    } else {
        // Infrared representation (deep red/infra-red)
        return { name: "Infrarrojo (Invisible)", color: "#b91c1c" };
    }

    // Intensity factor near the limits of human vision
    let factor = 0;
    if (wl >= 380 && wl < 420) {
        factor = 0.3 + 0.7 * (wl - 380) / (420 - 380);
    } else if (wl >= 420 && wl < 701) {
        factor = 1.0;
    } else if (wl >= 701 && wl <= 780) {
        factor = 0.3 + 0.7 * (780 - wl) / (780 - 701);
    }

    const R = Math.round(r * factor * 255);
    const G = Math.round(g * factor * 255);
    const B = Math.round(b * factor * 255);

    // Descriptive names
    let name = "Visible";
    if (wl >= 380 && wl < 450) name = "Visible (Violeta)";
    else if (wl >= 450 && wl < 485) name = "Visible (Azul)";
    else if (wl >= 485 && wl < 500) name = "Visible (Cian)";
    else if (wl >= 500 && wl < 565) name = "Visible (Verde)";
    else if (wl >= 565 && wl < 590) name = "Visible (Amarillo)";
    else if (wl >= 590 && wl < 625) name = "Visible (Naranja)";
    else if (wl >= 625 && wl <= 780) name = "Visible (Rojo)";

    return {
        name: name,
        color: `rgb(${R}, ${G}, ${B})`
    };
}

function initMaxwellSimulation() {
    const canvas = document.getElementById("maxwellChart");
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    const slider = document.getElementById("maxwell-temp");
    const valDisplay = document.getElementById("maxwell-temp-val");
    const gasSelect = document.getElementById("maxwell-gas");

    const R = 8.314; // Ideal gas constant J/(mol*K)

    // Function to calculate PDF of v
    function calculateMaxwell(v, M, T) {
        // v in m/s, M in kg/mol, T in K
        const factor = Math.pow(M / (2 * Math.PI * R * T), 1.5);
        const expTerm = Math.exp(- (M * v * v) / (2 * R * T));
        return 4 * Math.PI * factor * v * v * expTerm;
    }

    let maxwellChart = new Chart(ctx, {
        type: 'line',
        data: {
            labels: [],
            datasets: [{
                label: 'Distribución de Velocidades',
                data: [],
                borderColor: '#10b981',
                backgroundColor: 'rgba(16, 185, 129, 0.15)',
                borderWidth: 3,
                fill: true,
                tension: 0.4,
                pointRadius: 0
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
                legend: { labels: { color: '#f1f5f9', font: { family: 'Outfit', size: 12 } } },
                tooltip: {
                    callbacks: {
                        label: function (c) {
                            return `Probabilidad: ${(c.parsed.y * 1000).toFixed(2)} (x10^-3)`;
                        }
                    }
                }
            },
            scales: {
                x: {
                    title: { display: true, text: 'Velocidad Molecular v (m/s)', color: '#94a3b8' },
                    grid: { color: 'rgba(255, 255, 255, 0.05)' },
                    ticks: { color: '#94a3b8' }
                },
                y: {
                    title: { display: true, text: 'Densidad de Probabilidad f(v)', color: '#94a3b8' },
                    grid: { color: 'rgba(255, 255, 255, 0.05)' },
                    ticks: { color: '#94a3b8' }
                }
            }
        }
    });

    function updateSimulation() {
        const T = parseFloat(slider.value);
        const M = parseFloat(gasSelect.value); // kg/mol

        // Calculate characteristic speeds
        const vrms = Math.sqrt((3 * R * T) / M);
        const vp = Math.sqrt((2 * R * T) / M);
        const vmean = Math.sqrt((8 * R * T) / (Math.PI * M));

        // Fix the X and Y axes based on the selected gas to visually show the curve flattening
        const maxT = 2500;
        const minT = 50;
        const vrms_maxT = Math.sqrt((3 * R * maxT) / M);
        let newMaxV = Math.ceil((vrms_maxT * 3.5) / 100) * 100;

        // Max probability occurs at minimum temperature (50K) at vp_minT
        const vp_minT = Math.sqrt((2 * R * minT) / M);
        const maxProb = calculateMaxwell(vp_minT, M, minT);

        const newVelocities = [];
        const step = newMaxV / 100;
        for (let v = 0; v <= newMaxV; v += step) {
            newVelocities.push(Math.round(v));
        }

        const newData = newVelocities.map(v => calculateMaxwell(v, M, T));

        maxwellChart.data.labels = newVelocities;
        maxwellChart.data.datasets[0].data = newData;
        maxwellChart.data.datasets[0].label = `T = ${T} K`;

        maxwellChart.options.scales.y.max = maxProb * 1.05;
        maxwellChart.options.scales.x.max = newMaxV;

        // Dynamic color based on Temp (cool blue to hot red)
        const hue = Math.max(0, 240 - (T / 2500) * 240);
        maxwellChart.data.datasets[0].borderColor = `hsl(${hue}, 80%, 55%)`;
        maxwellChart.data.datasets[0].backgroundColor = `hsla(${hue}, 80%, 55%, 0.15)`;

        maxwellChart.update('none');

        // Update stats
        document.getElementById("maxwell-vp").textContent = `${Math.round(vp)} m/s`;
        document.getElementById("maxwell-vmean").textContent = `${Math.round(vmean)} m/s`;
        document.getElementById("maxwell-vrms").textContent = `${Math.round(vrms)} m/s`;
    }

    slider.addEventListener("input", updateSimulation);
    gasSelect.addEventListener("change", updateSimulation);

    syncSliderAndNumberInput(slider, document.getElementById('maxwell-temp-num'), updateSimulation);

    // Initial call
    updateSimulation();
}

function initPlanckSimulation() {
    const slider = document.getElementById("planck-temp");
    const valDisplay = document.getElementById("planck-temp-val");
    const ctx = document.getElementById("planckChart").getContext("2d");

    // Generate wavelengths from 0.1 um to 4.0 um
    const wavelengths = [];
    for (let w = 0.1; w <= 4.0; w += 0.05) {
        wavelengths.push(parseFloat(w.toFixed(2)));
    }

    const T = parseInt(slider.value);
    const dataPoints = wavelengths.map(w => calculatePlanck(w, T));

    // Update Wien values on init
    const updateWienDisplay = (temp) => {
        const lambda_max = temp > 0 ? 2897.8 / temp : Infinity;
        document.getElementById("planck-wien-val").innerHTML = temp > 0 ? `${lambda_max.toFixed(3)} &micro;m` : "&infin; &micro;m";
        const colorInfo = temp > 0 ? getWavelengthColor(lambda_max) : { color: '#000000', name: 'Ninguno (0K)' };
        document.getElementById("planck-color-name").textContent = colorInfo.name;

        const box = document.getElementById("planck-color-box");
        box.style.backgroundColor = colorInfo.color;
        box.style.boxShadow = `0 0 15px ${colorInfo.color}`;

        // Stefan-Boltzmann Law: E = sigma * T^4
        const sigma = 5.670374e-8;
        const E = sigma * Math.pow(temp, 4);
        let E_str = "";
        if (E < 1000) {
            E_str = `${E.toFixed(2)} W/m&sup2;`;
        } else if (E < 1e6) {
            E_str = `${(E / 1000).toFixed(2)} kW/m&sup2;`;
        } else {
            E_str = `${(E / 1e6).toFixed(2)} MW/m&sup2;`;
        }
        document.getElementById("planck-sb-val").innerHTML = E_str;

        // Calculate Blackbody Energy Fractions
        const getFraction = (lmb, t) => {
            if (t <= 0 || lmb <= 0) return 0;
            const C2 = 14387.8;
            const zeta = C2 / (lmb * t);
            if (zeta > 100) return 0; // effectively zero
            let sum = 0;
            for (let n = 1; n <= 40; n++) {
                sum += (Math.exp(-n * zeta) / n) * (Math.pow(zeta, 3) + 3 * Math.pow(zeta, 2) / n + 6 * zeta / (n * n) + 6 / Math.pow(n, 3));
            }
            return (15 / Math.pow(Math.PI, 4)) * sum;
        };

        const fXray = temp > 0 ? getFraction(0.01, temp) : 0;
        const fUV = temp > 0 ? getFraction(0.38, temp) - fXray : 0;
        const fVis = temp > 0 ? getFraction(0.78, temp) - getFraction(0.38, temp) : 0;
        const fIR = temp > 0 ? 1.0 - getFraction(0.78, temp) : 1;

        if (document.getElementById("frac-xray")) {
            document.getElementById("frac-xray").textContent = (fXray * 100).toFixed(4) + "%";
            document.getElementById("frac-uv").textContent = (Math.max(0, fUV) * 100).toFixed(2) + "%";
            document.getElementById("frac-vis").textContent = (Math.max(0, fVis) * 100).toFixed(2) + "%";
            document.getElementById("frac-ir").textContent = (Math.max(0, fIR) * 100).toFixed(2) + "%";
        }
    };

    updateWienDisplay(T);

    const activeDataset = {
        label: `Dinámico: ${T} K`,
        data: dataPoints,
        borderColor: '#f97316',
        backgroundColor: 'rgba(249, 115, 22, 0.1)',
        borderWidth: 3,
        fill: true,
        tension: 0.4,
        pointRadius: 0
    };

    const datasets = [activeDataset];

    // Reference curves to illustrate Wien's Displacement Law
    const refs = [
        { temp: 3000, color: 'rgba(239, 68, 68, 0.8)' },   // Red
        { temp: 4500, color: 'rgba(234, 179, 8, 0.8)' },   // Yellow
        { temp: 6000, color: 'rgba(56, 189, 248, 0.8)' }   // Blue
    ];

    refs.forEach(ref => {
        datasets.push({
            label: `Ref: ${ref.temp} K`,
            data: wavelengths.map(w => calculatePlanck(w, ref.temp)),
            borderColor: ref.color,
            borderWidth: 2,
            borderDash: [5, 5],
            fill: false,
            tension: 0.4,
            pointRadius: 0
        });
    });

    const visibleSpectrumPlugin = {
        id: 'visibleSpectrum',
        beforeDraw: (chart) => {
            const ctx = chart.ctx;
            const chartArea = chart.chartArea;
            const labels = chart.data.labels;

            if (!labels || labels.length === 0) return;

            const minVal = labels[0];
            const maxVal = labels[labels.length - 1];

            const getPix = (val) => {
                const ratio = (val - minVal) / (maxVal - minVal);
                return chartArea.left + ratio * (chartArea.right - chartArea.left);
            };

            const leftPx = getPix(0.38);
            const rightPx = getPix(0.75);

            if (rightPx > chartArea.left && leftPx < chartArea.right) {
                const drawLeft = Math.max(leftPx, chartArea.left);
                const drawRight = Math.min(rightPx, chartArea.right);

                ctx.save();
                const gradient = ctx.createLinearGradient(leftPx, 0, rightPx, 0);
                gradient.addColorStop(0, 'rgba(138, 43, 226, 0.25)'); // Violeta
                gradient.addColorStop(0.2, 'rgba(0, 0, 255, 0.25)');   // Azul
                gradient.addColorStop(0.5, 'rgba(0, 255, 0, 0.25)');   // Verde
                gradient.addColorStop(0.8, 'rgba(255, 255, 0, 0.25)'); // Amarillo
                gradient.addColorStop(1, 'rgba(255, 0, 0, 0.25)');     // Rojo

                ctx.fillStyle = gradient;
                ctx.fillRect(drawLeft, chartArea.top, drawRight - drawLeft, chartArea.bottom - chartArea.top);

                ctx.fillStyle = 'rgba(255, 255, 255, 0.6)';
                ctx.font = '10px Outfit, sans-serif';
                ctx.textAlign = 'center';

                // Draw text only if it's wide enough
                if (drawRight - drawLeft > 30) {
                    ctx.fillText('Visible', (drawLeft + drawRight) / 2, chartArea.top + 15);
                }

                ctx.restore();
            }
        }
    };

    planckChart = new Chart(ctx, {
        type: 'line',
        plugins: [visibleSpectrumPlugin],
        data: {
            labels: wavelengths,
            datasets: datasets
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
                legend: {
                    labels: { color: '#f1f5f9', font: { family: 'Outfit', size: 12 } }
                },
                tooltip: {
                    callbacks: {
                        label: function (context) {
                            return `Radiancia: ${context.parsed.y.toFixed(2)} kW/(m²·nm)`;
                        }
                    }
                }
            },
            scales: {
                x: {
                    title: { display: true, text: 'Longitud de onda, λ (µm)', color: '#94a3b8' },
                    grid: { color: 'rgba(255, 255, 255, 0.05)' },
                    ticks: { color: '#94a3b8' }
                },
                y: {
                    title: { display: true, text: 'Radiancia Espectral (kW / m² / nm)', color: '#94a3b8' },
                    grid: { color: 'rgba(255, 255, 255, 0.05)' },
                    ticks: { color: '#94a3b8' }
                }
            }
        }
    });

    function planckUpdate() {
        const multiplier = parseInt(document.getElementById("planck-multiplier") ? document.getElementById("planck-multiplier").value : 1);
        const T_val = parseInt(slider.value) * multiplier;
        valDisplay.textContent = T_val.toLocaleString();

        // Mathematically elegant dynamic X-axis scaling: ALWAYS center the peak!
        // lambda_max = 2897.8 / T_val. We set maxW to ~8x the peak wavelength.
        let maxW = T_val > 0 ? (2897.8 / T_val) * 8 : 20.0;

        const newWavelengths = [];
        const step = maxW / 80.0;
        // Start close to 0 to capture Gamma/X-ray peaks
        const startW = maxW / 80.0;
        for (let w = startW; w <= maxW; w += step) {
            // Keep precision dynamic based on scale
            const precision = maxW < 0.001 ? 8 : (maxW < 0.1 ? 5 : 3);
            newWavelengths.push(parseFloat(w.toFixed(precision)));
        }

        planckChart.data.labels = newWavelengths;

        // Recalculate values for the active dataset
        const newData = newWavelengths.map(w => calculatePlanck(w, T_val));

        planckChart.data.datasets[0].label = `Dinámico: ${T_val} K`;
        planckChart.data.datasets[0].data = newData;

        // Recalculate values for the reference datasets
        planckChart.data.datasets[1].data = newWavelengths.map(w => calculatePlanck(w, refs[0].temp));
        planckChart.data.datasets[2].data = newWavelengths.map(w => calculatePlanck(w, refs[1].temp));
        planckChart.data.datasets[3].data = newWavelengths.map(w => calculatePlanck(w, refs[2].temp));

        // Update Wien indicator
        updateWienDisplay(T_val);

        // Dynamically adjust color gradient based on temperature
        const hue = Math.max(15, 240 - (T_val - 1000) * 0.025);
        planckChart.data.datasets[0].borderColor = `hsl(${hue}, 90%, 55%)`;
        planckChart.data.datasets[0].backgroundColor = `hsla(${hue}, 90%, 55%, 0.15)`;

        // Handle logarithmic scale dynamically
        const isLog = document.getElementById("planck-log-scale").checked;
        const maxVal = Math.max(...newData);

        if (isLog) {
            planckChart.options.scales.y.type = 'logarithmic';
            planckChart.options.scales.y.min = 1e-8; // Prevent log(0)
            // Allow Y max to float in log scale or force it to slightly above maxVal
            delete planckChart.options.scales.y.max;
        } else {
            planckChart.options.scales.y.type = 'linear';
            delete planckChart.options.scales.y.min;
            if (T_val < 3000) {
                planckChart.options.scales.y.max = maxVal * 1.5;
            } else {
                delete planckChart.options.scales.y.max;
            }
        }

        planckChart.update('none'); // silent update for performance
    }
    slider.addEventListener("input", planckUpdate);

    syncSliderAndNumberInput(slider, document.getElementById('planck-temp-num'), planckUpdate);

    // Attach listener for logarithmic scale checkbox
    const logCheckbox = document.getElementById("planck-log-scale");
    if (logCheckbox) {
        logCheckbox.addEventListener("change", (e) => {
            slider.dispatchEvent(new Event("input"));
        });
    }

    // Attach listener for the multiplier dropdown
    const multiplierSelect = document.getElementById("planck-multiplier");
    if (multiplierSelect) {
        multiplierSelect.addEventListener("change", (e) => {
            slider.dispatchEvent(new Event("input"));
        });
    }
}

/* =========================================================================
   PRANDTL BOUNDARY LAYER VELOCITY PROFILE SIMULATOR
   ========================================================================= */
let prandtlChart;

function initPrandtlSimulation() {
    const fluidSelect = document.getElementById("prandtl-fluid");
    const sliderP = document.getElementById("prandtl-p");
    const sliderU = document.getElementById("prandtl-u");
    const sliderNu = document.getElementById("prandtl-nu");
    const sliderX = document.getElementById("prandtl-x");
    const sliderL = document.getElementById("prandtl-l");
    const sliderPr = document.getElementById("prandtl-pr");
    const sliderTs = document.getElementById("prandtl-ts");
    const sliderTinf = document.getElementById("prandtl-tinf");
    const sliderSc = document.getElementById("prandtl-sc");
    const sliderCs = document.getElementById("prandtl-cs");
    const sliderCinf = document.getElementById("prandtl-cinf");

    const cbHydro = document.getElementById("prandtl-show-hydro");
    const cbTherm = document.getElementById("prandtl-show-therm");
    const cbConc = document.getElementById("prandtl-show-conc");

    const numNu = document.getElementById("prandtl-nu-num");
    const numPr = document.getElementById("prandtl-pr-num");

    const valPDisplay = document.getElementById("prandtl-p-val");
    const valUDisplay = document.getElementById("prandtl-u-val");
    const valNuDisplay = document.getElementById("prandtl-nu-val");
    const valXDisplay = document.getElementById("prandtl-x-val");
    const valLDisplay = document.getElementById("prandtl-l-val");
    const valPrDisplay = document.getElementById("prandtl-pr-val");
    const valTsDisplay = document.getElementById("prandtl-ts-val");
    const valTinfDisplay = document.getElementById("prandtl-tinf-val");
    const valScDisplay = document.getElementById("prandtl-sc-val");
    const valCsDisplay = document.getElementById("prandtl-cs-val");
    const valCinfDisplay = document.getElementById("prandtl-cinf-val");
    const ctx = document.getElementById("prandtlChart").getContext("2d");

    // Empirical fluid properties at 1 atm (P in atm, Tf in Celsius)
    function getFluidProperties(fluid, Tf, P) {
        const Tk = Tf + 273.15; // Kelvin
        const P_Pa = P * 101325; // Pascals
        let rho, mu, nu, k, Pr;

        if (fluid === "air") {
            // Ideal gas law for density
            rho = P_Pa / (287.05 * Tk);
            // Sutherland's law for viscosity
            mu = 1.458e-6 * Math.pow(Tk, 1.5) / (Tk + 110.4);
            nu = mu / rho;
            // Simplified k for air
            k = 0.0241 * Math.pow(Tk / 273.15, 0.8);
            Pr = 0.71;
        } else if (fluid === "water") {
            // Liquid water (incompressible approx)
            rho = 1000 - Math.pow(Tf - 4, 2) / 250;
            if (rho < 900) rho = 900; // rough limit
            // Viscosity empirical
            mu = 2.414e-5 * Math.pow(10, 247.8 / (Tk - 140));
            nu = mu / rho;
            // Thermal conductivity
            k = 0.56 + 0.0018 * Tf - 7e-6 * Tf * Tf;
            // Cp approx 4184
            Pr = (mu * 4184) / k;
        } else if (fluid === "co2") {
            // Ideal gas CO2
            rho = P_Pa / (188.9 * Tk);
            // Sutherland-like for CO2
            mu = 1.57e-6 * Math.pow(Tk, 1.5) / (Tk + 240);
            nu = mu / rho;
            // Thermal conductivity
            k = 0.0146 + 7.3e-5 * Tf;
            Pr = 0.77;
        } else if (fluid === "steam") {
            // Superheated steam approx (ideal gas)
            rho = P_Pa / (461.5 * Tk);
            // Viscosity
            mu = 8.0e-6 + 4.0e-8 * Tf; // rough linear approx
            nu = mu / rho;
            k = 0.016 + 7.5e-5 * Tf;
            // Cp approx 2000 for steam
            Pr = (mu * 2000) / k;
        } else {
            // Custom fallback (won't be used directly to override sliders)
            return null;
        }

        return { rho, mu, nu, k, Pr };
    }

    function getBoundaryLayer(U, nu, x_m, Pr, Sc) {
        const Rex = (U * x_m) / nu;
        const Rex_crit = 500000;
        let delta = 0;
        let delta_t = 0;
        let delta_c = 0;
        let isTurbulent = false;

        const validPr = Math.max(Pr, 0.01);
        const validSc = Math.max(Sc, 0.01);

        if (Rex < Rex_crit) {
            delta = (5.0 * x_m) / Math.sqrt(Math.max(Rex, 1));
            delta_t = delta / Math.pow(validPr, 1.0 / 3.0);
            delta_c = delta / Math.pow(validSc, 1.0 / 3.0);
        } else {
            isTurbulent = true;
            delta = (0.37 * x_m) / Math.pow(Math.max(Rex, 1), 0.2);
            delta_t = delta / Math.pow(validPr, 1.0 / 3.0);
            delta_c = delta / Math.pow(validSc, 1.0 / 3.0);
        }

        return { delta, delta_t, delta_c, isTurbulent, Rex };
    }

    // Update profile using laminar (Blasius) or turbulent (1/7 power law) depending on Rex
    function updatePrandtlData(U, nu, x, Pr, Sc) {
        const bl = getBoundaryLayer(U, nu, x, Pr, Sc);
        const delta_mm = bl.delta * 1000;
        const delta_t_mm = bl.delta_t * 1000;
        const delta_c_mm = bl.delta_c * 1000;

        // Dynamic y max based on max delta to always show the profile properly, but at least 20mm
        const max_y_mm = Math.max(30, Math.max(delta_mm, Math.max(delta_t_mm, delta_c_mm)) * 1.5);

        const yPoints = [];
        const uPoints = [];
        const tPoints = [];
        const cPoints = [];

        // Generate points up to max_y_mm
        const steps = 100;
        const step_y = max_y_mm / steps;

        for (let y_mm = 0; y_mm <= max_y_mm; y_mm += step_y) {
            yPoints.push(parseFloat(y_mm.toFixed(2)));

            const ratio = y_mm / delta_mm;
            if (ratio >= 1.0) {
                uPoints.push(1.0);
            } else {
                if (!bl.isTurbulent) {
                    const u_ratio = 1.5 * ratio - 0.5 * Math.pow(ratio, 3);
                    uPoints.push(parseFloat(u_ratio.toFixed(4)));
                } else {
                    const u_ratio = Math.pow(ratio, 1.0 / 7.0);
                    uPoints.push(parseFloat(u_ratio.toFixed(4)));
                }
            }

            const ratio_t = y_mm / delta_t_mm;
            if (ratio_t >= 1.0) {
                tPoints.push(1.0);
            } else {
                if (!bl.isTurbulent) {
                    const t_ratio = 1.5 * ratio_t - 0.5 * Math.pow(ratio_t, 3);
                    tPoints.push(parseFloat(t_ratio.toFixed(4)));
                } else {
                    const t_ratio = Math.pow(ratio_t, 1.0 / 7.0);
                    tPoints.push(parseFloat(t_ratio.toFixed(4)));
                }
            }

            const ratio_c = y_mm / delta_c_mm;
            if (ratio_c >= 1.0) {
                cPoints.push(1.0);
            } else {
                if (!bl.isTurbulent) {
                    const c_ratio = 1.5 * ratio_c - 0.5 * Math.pow(ratio_c, 3);
                    cPoints.push(parseFloat(c_ratio.toFixed(4)));
                } else {
                    const c_ratio = Math.pow(ratio_c, 1.0 / 7.0);
                    cPoints.push(parseFloat(c_ratio.toFixed(4)));
                }
            }
        }

        return { yPoints, uPoints, tPoints, cPoints, delta_mm, delta_t_mm, delta_c_mm, isTurbulent: bl.isTurbulent, Rex: bl.Rex };
    }

    const U = parseFloat(sliderU.value);
    const nu = parseFloat(sliderNu.value) * 1e-5;
    const x = parseFloat(sliderX.value);
    const Pr = parseFloat(sliderPr.value);
    const Sc = parseFloat(sliderSc.value);
    let simData = updatePrandtlData(U, nu, x, Pr, Sc);

    prandtlChart = new Chart(ctx, {
        type: 'line',
        data: {
            labels: simData.yPoints, // Height above plate y
            datasets: [
                {
                    label: 'Perfil de Velocidad u/U_inf',
                    data: simData.uPoints,
                    borderColor: '#06b6d4',
                    backgroundColor: 'rgba(6, 182, 212, 0.05)',
                    borderWidth: 3,
                    tension: 0.1,
                    pointRadius: 0,
                    fill: true
                },
                {
                    label: 'Espesor Capa Hidrodinámica (δ)',
                    data: simData.yPoints.map(y => (Math.abs(y - simData.delta_mm) < (simData.delta_mm * 1.5 / 100) * 1.5) ? 1.0 : null),
                    borderColor: 'rgba(239, 68, 68, 0.8)',
                    borderDash: [5, 5],
                    borderWidth: 2,
                    showLine: true,
                    pointRadius: 3,
                    pointBackgroundColor: '#ef4444'
                },
                {
                    label: 'Perfil Temp. Adimensional (θ)',
                    data: simData.tPoints,
                    borderColor: '#f59e0b',
                    backgroundColor: 'rgba(245, 158, 11, 0.05)',
                    borderWidth: 3,
                    tension: 0.1,
                    pointRadius: 0,
                    fill: true
                },
                {
                    label: 'Espesor Capa Térmica (δ_t)',
                    data: simData.yPoints.map(y => (Math.abs(y - simData.delta_t_mm) < (simData.delta_t_mm * 1.5 / 100) * 1.5) ? 1.0 : null),
                    borderColor: 'rgba(245, 158, 11, 0.8)',
                    borderDash: [2, 2],
                    borderWidth: 2,
                    showLine: true,
                    pointRadius: 3,
                    pointBackgroundColor: '#f59e0b'
                },
                {
                    label: 'Perfil Conc. Adimensional (φ)',
                    data: simData.cPoints,
                    borderColor: '#8b5cf6',
                    backgroundColor: 'rgba(139, 92, 246, 0.05)',
                    borderWidth: 3,
                    tension: 0.1,
                    pointRadius: 0,
                    fill: true
                },
                {
                    label: 'Espesor Capa Concentración (δ_c)',
                    data: simData.yPoints.map(y => (Math.abs(y - simData.delta_c_mm) < (simData.delta_c_mm * 1.5 / 100) * 1.5) ? 1.0 : null),
                    borderColor: 'rgba(139, 92, 246, 0.8)',
                    borderDash: [3, 3],
                    borderWidth: 2,
                    showLine: true,
                    pointRadius: 3,
                    pointBackgroundColor: '#8b5cf6'
                }
            ]
        },
        options: {
            indexAxis: 'y', // Swap axes to plot velocity u on horizontal axis and y on vertical!
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
                legend: {
                    labels: { color: '#f1f5f9', font: { family: 'Outfit', size: 12 } }
                }
            },
            scales: {
                x: {
                    min: 0,
                    max: 1.1,
                    title: { display: true, text: 'Valor Normalizado (u/U_inf , θ, φ)', color: '#94a3b8' },
                    grid: { color: 'rgba(255, 255, 255, 0.05)' },
                    ticks: { color: '#94a3b8' }
                },
                y: {
                    title: { display: true, text: 'Distancia normal a la placa, y (mm)', color: '#94a3b8' },
                    grid: { color: 'rgba(255, 255, 255, 0.05)' },
                    ticks: { color: '#94a3b8' }
                }
            }
        }
    });

    const updateDisplay = () => {
        const fluid = fluidSelect.value;
        const p_val = parseFloat(sliderP.value);
        const u_val = parseFloat(sliderU.value);
        const x_val = parseFloat(sliderX.value);
        const ts_val = parseInt(sliderTs.value);
        const tinf_val = parseInt(sliderTinf.value);
        const cs_val = parseInt(sliderCs.value);
        const cinf_val = parseInt(sliderCinf.value);

        const hydroVisible = cbHydro.checked;
        const thermVisible = cbTherm.checked && (ts_val !== tinf_val);
        const concVisible = cbConc.checked && (cs_val !== cinf_val);

        const tf = (ts_val + tinf_val) / 2;
        let nu_val, pr_val, sc_val, k_fluid;

        if (fluid === "custom") {
            document.querySelectorAll('.prandtl-custom-prop').forEach(el => el.style.display = "");
            sliderNu.disabled = false;
            sliderPr.disabled = false;
            sliderSc.disabled = false;
            if (numNu) numNu.disabled = false;
            if (numPr) numPr.disabled = false;

            nu_val = parseFloat(sliderNu.value) * 1e-5;
            pr_val = parseFloat(sliderPr.value);
            sc_val = parseFloat(sliderSc.value);
            k_fluid = 0.026; // arbitrary default for custom
        } else {
            document.querySelectorAll('.prandtl-custom-prop').forEach(el => el.style.display = "none");
            sliderNu.disabled = true;
            sliderPr.disabled = true;
            if (numNu) numNu.disabled = true;
            if (numPr) numPr.disabled = true;

            const props = getFluidProperties(fluid, tf, p_val);
            nu_val = props.nu;
            pr_val = props.Pr;
            k_fluid = props.k;

            // For Schmidt number, keep slider enabled since it depends on species, 
            // but we can set defaults based on fluid (like water vapor in air ~0.6)
            sc_val = parseFloat(sliderSc.value);
            sliderSc.disabled = false;

            // Update sliders visually to match calculated properties
            sliderNu.value = (nu_val * 1e5).toFixed(2);
            sliderPr.value = pr_val.toFixed(2);
            // Reflejar el mismo valor calculado en su input numérico hermano,
            // ya que al estar deshabilitado no recibe eventos de sync propios.
            if (numNu) numNu.value = sliderNu.value;
            if (numPr) numPr.value = sliderPr.value;
        }

        const newData = updatePrandtlData(u_val, nu_val, x_val, pr_val, sc_val);
        prandtlChart.data.labels = newData.yPoints;
        prandtlChart.data.datasets[0].data = newData.uPoints;

        const tol = (Math.max(30, Math.max(newData.delta_mm, Math.max(newData.delta_t_mm, newData.delta_c_mm)) * 1.5) / 100) * 1.5;
        prandtlChart.data.datasets[1].data = newData.yPoints.map(y => (Math.abs(y - newData.delta_mm) < tol) ? 1.0 : null);
        prandtlChart.data.datasets[2].data = newData.tPoints;
        prandtlChart.data.datasets[3].data = newData.yPoints.map(y => (Math.abs(y - newData.delta_t_mm) < tol) ? 1.0 : null);
        prandtlChart.data.datasets[4].data = newData.cPoints;
        prandtlChart.data.datasets[5].data = newData.yPoints.map(y => (Math.abs(y - newData.delta_c_mm) < tol) ? 1.0 : null);

        // Visibility
        prandtlChart.setDatasetVisibility(0, hydroVisible);
        prandtlChart.setDatasetVisibility(1, hydroVisible);
        prandtlChart.setDatasetVisibility(2, thermVisible);
        prandtlChart.setDatasetVisibility(3, thermVisible);
        prandtlChart.setDatasetVisibility(4, concVisible);
        prandtlChart.setDatasetVisibility(5, concVisible);

        // Update annotation if plugin exists
        if (prandtlChart.options.plugins && prandtlChart.options.plugins.annotation && prandtlChart.options.plugins.annotation.annotations && prandtlChart.options.plugins.annotation.annotations.regimeLabel) {
            prandtlChart.options.plugins.annotation.annotations.regimeLabel.content = newData.isTurbulent ? `RÉGIMEN TURBULENTO (Rex = ${newData.Rex.toExponential(2)})` : `RÉGIMEN LAMINAR (Rex = ${newData.Rex.toExponential(2)})`;
            prandtlChart.options.plugins.annotation.annotations.regimeLabel.backgroundColor = newData.isTurbulent ? 'rgba(239,68,68,0.2)' : 'rgba(16,185,129,0.2)';
            prandtlChart.options.plugins.annotation.annotations.regimeLabel.color = newData.isTurbulent ? '#ef4444' : '#10b981';
            prandtlChart.options.plugins.annotation.annotations.regimeLabel.yValue = Math.max(30, Math.max(newData.delta_mm, Math.max(newData.delta_t_mm, newData.delta_c_mm)) * 1.5) * 0.9;
        }

        // Update results panel
        const le = sc_val / pr_val;

        const elTf = document.getElementById("prandtl-tf-out");
        const elLe = document.getElementById("prandtl-le-out");
        const elRex = document.getElementById("prandtl-rex-out");
        const elRegime = document.getElementById("prandtl-regime-out");
        const elXc = document.getElementById("prandtl-xc-out");
        const elHx = document.getElementById("prandtl-hx-out");
        const elFormula = document.getElementById("prandtl-hx-formula");

        if (elTf) elTf.textContent = `${tf.toFixed(1)} °C`;
        if (elLe) elLe.textContent = le.toFixed(2);
        if (elRex) elRex.textContent = newData.Rex.toExponential(2);

        if (elRegime) {
            elRegime.textContent = newData.isTurbulent ? "TURBULENTO" : "LAMINAR";
            elRegime.style.color = newData.isTurbulent ? "#ef4444" : "#10b981";
        }

        const elDelta = document.getElementById("prandtl-delta-out");
        const elDeltaT = document.getElementById("prandtl-deltat-out");
        const elDeltaC = document.getElementById("prandtl-deltac-out");

        if (elDelta) elDelta.textContent = `${newData.delta_mm.toFixed(2)} mm`;
        if (elDeltaT) elDeltaT.textContent = `${newData.delta_t_mm.toFixed(2)} mm`;
        if (elDeltaC) elDeltaC.textContent = `${newData.delta_c_mm.toFixed(2)} mm`;

        if (elXc) {
            const xc = (500000 * nu_val) / u_val;
            elXc.textContent = `${xc.toFixed(2)} m`;
        }

        if (elHx && elFormula) {
            let nux, hx, formula;
            if (newData.isTurbulent) {
                nux = 0.0296 * Math.pow(newData.Rex, 0.8) * Math.pow(pr_val, 1 / 3);
                formula = "\\(Nu_x = 0.0296 Re_x^{4/5} Pr^{1/3}\\)<br>\\(h_x = \\frac{Nu_x k}{x}\\)";
            } else {
                nux = 0.332 * Math.pow(newData.Rex, 0.5) * Math.pow(pr_val, 1 / 3);
                formula = "\\(Nu_x = 0.332 Re_x^{1/2} Pr^{1/3}\\)<br>\\(h_x = \\frac{Nu_x k}{x}\\)";
            }
            hx = (nux * k_fluid) / x_val;

            elHx.innerHTML = `${hx.toFixed(2)} <span style="font-size: 0.8rem">W/m²K</span>`;

            // Only update formula if it changed to avoid excessive MathJax calls
            if (elFormula.dataset.formula !== formula) {
                elFormula.dataset.formula = formula;
                elFormula.innerHTML = formula;
                if (window.MathJax) {
                    MathJax.typesetPromise([elFormula]).catch(err => console.log(err));
                }
            }
        }

        // Update global results
        const elReL = document.getElementById("prandtl-rel-out");
        const elHL = document.getElementById("prandtl-hl-out");
        const elHLFormula = document.getElementById("prandtl-hl-formula");

        if (elReL && elHL && elHLFormula) {
            const L = parseFloat(sliderL.value) || 2.0; // The total length of the plate
            const ReL = (u_val * L) / nu_val;
            elReL.textContent = ReL.toExponential(2);

            let nuL_avg, formulaL;
            if (ReL < 500000) {
                nuL_avg = 0.664 * Math.pow(ReL, 0.5) * Math.pow(pr_val, 1 / 3);
                formulaL = "\\(\\overline{Nu}_L = 0.664 Re_L^{1/2} Pr^{1/3}\\)<br>\\(\\bar{h}_L = \\frac{\\overline{Nu}_L k}{L}\\)";
            } else {
                const A = 0.037 * Math.pow(500000, 0.8) - 0.664 * Math.pow(500000, 0.5); // A approx 871
                nuL_avg = (0.037 * Math.pow(ReL, 0.8) - A) * Math.pow(pr_val, 1 / 3);
                formulaL = `\\(\\overline{Nu}_L = (0.037 Re_L^{4/5} - ${Math.round(A)}) Pr^{1/3}\\)<br>\\(\\bar{h}_L = \\frac{\\overline{Nu}_L k}{L}\\)`;
            }

            const hL_avg = (nuL_avg * k_fluid) / L;
            elHL.innerHTML = `${hL_avg.toFixed(2)} <span style="font-size: 0.8rem">W/m²K</span>`;

            if (elHLFormula.dataset.formula !== formulaL) {
                elHLFormula.dataset.formula = formulaL;
                elHLFormula.innerHTML = formulaL;
                if (window.MathJax) {
                    MathJax.typesetPromise([elHLFormula]).catch(err => console.log(err));
                }
            }
        }

        // Update UI displays
        const L_val = parseFloat(sliderL.value) || 2.0;
        const elLTitleEs = document.getElementById("prandtl-l-display-title-es");
        const elLTitleEn = document.getElementById("prandtl-l-display-title-en");
        if (elLTitleEs) elLTitleEs.textContent = L_val.toFixed(2);
        if (elLTitleEn) elLTitleEn.textContent = L_val.toFixed(2);

        prandtlChart.update('none');
    };

    sliderU.addEventListener("input", updateDisplay);
    sliderNu.addEventListener("input", updateDisplay);
    sliderX.addEventListener("input", updateDisplay);
    sliderL.addEventListener("input", updateDisplay);
    sliderPr.addEventListener("input", updateDisplay);
    sliderTs.addEventListener("input", updateDisplay);
    sliderTinf.addEventListener("input", updateDisplay);
    sliderSc.addEventListener("input", updateDisplay);
    sliderCs.addEventListener("input", updateDisplay);
    sliderCinf.addEventListener("input", updateDisplay);
    fluidSelect.addEventListener("change", updateDisplay);
    sliderP.addEventListener("input", updateDisplay);

    cbHydro.addEventListener("change", updateDisplay);
    cbTherm.addEventListener("change", updateDisplay);
    cbConc.addEventListener("change", updateDisplay);

    syncSliderAndNumberInput(sliderP, document.getElementById('prandtl-p-num'), updateDisplay);
    syncSliderAndNumberInput(sliderU, document.getElementById('prandtl-u-num'), updateDisplay);
    syncSliderAndNumberInput(sliderNu, document.getElementById('prandtl-nu-num'), updateDisplay);
    syncSliderAndNumberInput(sliderX, document.getElementById('prandtl-x-num'), updateDisplay);
    syncSliderAndNumberInput(sliderL, document.getElementById('prandtl-l-num'), updateDisplay);
    syncSliderAndNumberInput(sliderPr, document.getElementById('prandtl-pr-num'), updateDisplay);
    syncSliderAndNumberInput(sliderTs, document.getElementById('prandtl-ts-num'), updateDisplay);
    syncSliderAndNumberInput(sliderTinf, document.getElementById('prandtl-tinf-num'), updateDisplay);
    syncSliderAndNumberInput(sliderSc, document.getElementById('prandtl-sc-num'), updateDisplay);
    syncSliderAndNumberInput(sliderCs, document.getElementById('prandtl-cs-num'), updateDisplay);
    syncSliderAndNumberInput(sliderCinf, document.getElementById('prandtl-cinf-num'), updateDisplay);

    // Ejecutar una vez al iniciar: sin esto, sliderNu/sliderPr (y sus
    // inputs numéricos hermanos) quedaban habilitados y con el valor por
    // defecto del HTML hasta el primer 'change' de fluidSelect, en vez de
    // reflejar de inmediato el fluido preseleccionado ("Aire").
    updateDisplay();

    // Particle animation logic
    const canvas = document.getElementById("boundaryLayerCanvas");
    const animCtx = canvas.getContext("2d");

    class Particle {
        constructor() {
            this.reset();
            this.x = Math.random() * canvas.width;
        }
        reset() {
            this.x = 0;
            this.y = Math.random() * (canvas.height - 15);
        }
        update(U, nu) {
            const physicalX = (this.x / canvas.width) * 2.0;
            const currentPr = parseFloat(sliderPr.value) || 0.7;
            const currentSc = parseFloat(sliderSc.value) || 0.7;
            const bl = getBoundaryLayer(U, nu, physicalX, currentPr, currentSc);
            const scaleY = canvas.height / 0.040; // 40mm fills the canvas
            const delta_pixels = bl.delta * scaleY;

            const distFromPlate = canvas.height - this.y;

            let u_ratio = 1.0;
            if (distFromPlate < delta_pixels) {
                const ratio = distFromPlate / delta_pixels;
                if (!bl.isTurbulent) {
                    u_ratio = 1.5 * ratio - 0.5 * Math.pow(ratio, 3);
                } else {
                    u_ratio = Math.pow(ratio, 1.0 / 7.0);
                }
                if (u_ratio < 0.05) u_ratio = 0.05;
            }

            this.x += 2.5 * u_ratio;
            if (this.x > canvas.width) {
                this.reset();
            }
        }
        draw() {
            animCtx.beginPath();
            animCtx.arc(this.x, this.y, 2, 0, 2 * Math.PI);
            animCtx.fillStyle = "rgba(6, 182, 212, 0.75)";
            animCtx.fill();
        }
    }

    const particles = [];
    const numParticles = 60;

    function resizeCanvas() {
        if (!canvas) return;
        canvas.width = canvas.clientWidth;
        canvas.height = canvas.clientHeight;
        particles.length = 0;
        for (let i = 0; i < numParticles; i++) {
            particles.push(new Particle());
        }
    }

    resizeCanvas();
    window.addEventListener("resize", resizeCanvas);

    function animateParticles() {
        if (!canvas || !animCtx) return;
        animCtx.clearRect(0, 0, canvas.width, canvas.height);

        // Draw flat plate at the bottom (solid line)
        animCtx.fillStyle = "#475569";
        animCtx.fillRect(0, canvas.height - 4, canvas.width, 4);

        const currentU = parseFloat(sliderU.value);
        const currentNu = parseFloat(sliderNu.value) * 1e-5;
        const currentX = parseFloat(sliderX.value);
        const currentPr = parseFloat(sliderPr.value) || 0.7;
        const currentSc = parseFloat(sliderSc.value) || 0.7;
        const hydroVisible = cbHydro.checked;
        const thermVisible = cbTherm.checked && (parseInt(sliderTs.value) !== parseInt(sliderTinf.value));
        const concVisible = cbConc.checked && (parseInt(sliderCs.value) !== parseInt(sliderCinf.value));
        const scaleY = canvas.height / 0.040; // 40mm fits canvas vertically

        // Draw hydrodynamic boundary layer boundary delta(x)
        if (hydroVisible) {
            animCtx.beginPath();
            animCtx.moveTo(0, canvas.height);
            for (let px = 0; px <= canvas.width; px += 5) {
                const physicalX = (px / canvas.width) * 2.0;
                const bl = getBoundaryLayer(currentU, currentNu, physicalX, currentPr, currentSc);
                const delta_pixels = bl.delta * scaleY;
                animCtx.lineTo(px, canvas.height - delta_pixels);
            }
            animCtx.strokeStyle = "rgba(239, 68, 68, 0.4)";
            animCtx.lineWidth = 2;
            animCtx.stroke();

            // Shade the hydrodynamic boundary layer area
            animCtx.beginPath();
            animCtx.moveTo(0, canvas.height);
            for (let px = 0; px <= canvas.width; px += 5) {
                const physicalX = (px / canvas.width) * 2.0;
                const bl = getBoundaryLayer(currentU, currentNu, physicalX, currentPr, currentSc);
                const delta_pixels = bl.delta * scaleY;
                animCtx.lineTo(px, canvas.height - delta_pixels);
            }
            animCtx.lineTo(canvas.width, canvas.height);
            animCtx.lineTo(0, canvas.height);
            animCtx.fillStyle = "rgba(239, 68, 68, 0.05)";
            animCtx.fill();
        }

        // Draw thermal boundary layer boundary delta_t(x)
        if (thermVisible) {
            animCtx.beginPath();
            animCtx.moveTo(0, canvas.height);
            for (let px = 0; px <= canvas.width; px += 5) {
                const physicalX = (px / canvas.width) * 2.0;
                const bl = getBoundaryLayer(currentU, currentNu, physicalX, currentPr, currentSc);
                const delta_t_pixels = bl.delta_t * scaleY;
                animCtx.lineTo(px, canvas.height - delta_t_pixels);
            }
            animCtx.strokeStyle = "rgba(245, 158, 11, 0.6)"; // orange
            animCtx.lineWidth = 2;
            animCtx.setLineDash([4, 4]);
            animCtx.stroke();
            animCtx.setLineDash([]);
        }

        // Draw concentration boundary layer boundary delta_c(x)
        if (concVisible) {
            animCtx.beginPath();
            animCtx.moveTo(0, canvas.height);
            for (let px = 0; px <= canvas.width; px += 5) {
                const physicalX = (px / canvas.width) * 2.0;
                const bl = getBoundaryLayer(currentU, currentNu, physicalX, currentPr, currentSc);
                const delta_c_pixels = bl.delta_c * scaleY;
                animCtx.lineTo(px, canvas.height - delta_c_pixels);
            }
            animCtx.strokeStyle = "rgba(139, 92, 246, 0.6)"; // purple
            animCtx.lineWidth = 2;
            animCtx.setLineDash([2, 4]);
            animCtx.stroke();
            animCtx.setLineDash([]);
        }

        // Draw sliderX location line
        const indicatorPx = (currentX / 2.0) * canvas.width;
        animCtx.beginPath();
        animCtx.moveTo(indicatorPx, 0);
        animCtx.lineTo(indicatorPx, canvas.height);
        animCtx.strokeStyle = "rgba(255, 255, 255, 0.2)";
        animCtx.setLineDash([4, 4]);
        animCtx.stroke();
        animCtx.setLineDash([]);

        // Draw velocity profile arrows at indicatorPx
        const numArrows = 8;
        const arrowMaxPx = 60; // max length of arrow for V_infinity
        const physicalX_ind = currentX;
        const bl_ind = getBoundaryLayer(currentU, currentNu, physicalX_ind, currentPr, currentSc);
        const delta_pixels_ind = bl_ind.delta * scaleY;

        // Draw curve connecting tips
        animCtx.beginPath();
        animCtx.moveTo(indicatorPx, canvas.height);
        for (let i = 0; i <= 30; i++) {
            const distFromPlate = (i / 30) * Math.min(canvas.height, delta_pixels_ind * 1.5);
            const y = canvas.height - distFromPlate;
            let u_ratio = 1.0;
            if (distFromPlate < delta_pixels_ind) {
                const ratio = distFromPlate / delta_pixels_ind;
                if (!bl_ind.isTurbulent) {
                    u_ratio = 1.5 * ratio - 0.5 * Math.pow(ratio, 3);
                } else {
                    u_ratio = Math.pow(ratio, 1.0 / 7.0);
                }
            }
            animCtx.lineTo(indicatorPx + u_ratio * arrowMaxPx, y);
        }
        animCtx.strokeStyle = "rgba(16, 185, 129, 0.8)"; // emerald curve
        animCtx.lineWidth = 2;
        animCtx.stroke();

        // Draw individual arrows
        for (let i = 0; i <= numArrows; i++) {
            const distFromPlate = (i / numArrows) * Math.min(canvas.height, delta_pixels_ind * 1.5);
            const y = canvas.height - distFromPlate;

            if (y < 0) continue;

            let u_ratio = 1.0;
            if (distFromPlate < delta_pixels_ind) {
                const ratio = distFromPlate / delta_pixels_ind;
                if (!bl_ind.isTurbulent) {
                    u_ratio = 1.5 * ratio - 0.5 * Math.pow(ratio, 3);
                } else {
                    u_ratio = Math.pow(ratio, 1.0 / 7.0);
                }
            }

            const arrowLen = u_ratio * arrowMaxPx;

            // Draw line
            animCtx.beginPath();
            animCtx.moveTo(indicatorPx, y);
            animCtx.lineTo(indicatorPx + arrowLen, y);
            animCtx.strokeStyle = "rgba(16, 185, 129, 0.9)";
            animCtx.lineWidth = 1.5;
            animCtx.stroke();

            // Draw arrowhead
            if (arrowLen > 2) {
                animCtx.beginPath();
                animCtx.moveTo(indicatorPx + arrowLen, y);
                animCtx.lineTo(indicatorPx + arrowLen - 6, y - 3);
                animCtx.lineTo(indicatorPx + arrowLen - 6, y + 3);
                animCtx.fillStyle = "rgba(16, 185, 129, 0.9)";
                animCtx.fill();
            }
        }

        // Draw text labels for boundary conditions
        animCtx.fillStyle = "rgba(248, 250, 252, 0.9)"; // slate-50 color
        animCtx.font = "12px 'Outfit', sans-serif";

        // No-slip condition label
        animCtx.fillText("u=0 (No deslizamiento)", indicatorPx + 8, canvas.height - 8);

        // Free stream velocity label
        animCtx.fillText("u ≈ U∞", indicatorPx + arrowMaxPx + 8, canvas.height - (delta_pixels_ind * 1.3));

        // Update and draw particles
        particles.forEach(p => {
            p.update(currentU, currentNu);
            p.draw();
        });

        requestAnimationFrame(animateParticles);
    }
    animateParticles();
}

/* =========================================================================

/* =========================================================================
   INVERSE SQUARE LAW SIMULATOR
   ========================================================================= */
let invsqChart;

function initInvSqSimulation() {
    const sliderPower = document.getElementById("invsq-power");
    const sliderDist = document.getElementById("invsq-dist");
    const ctx = document.getElementById("invsqChart");
    if (!ctx) return;

    function calcIntensity(P, r) {
        return P / (4 * Math.PI * r * r);
    }

    function updateInvSqData(P) {
        const distances = [];
        const intensities = [];
        for (let r = 0.5; r <= 10; r += 0.1) {
            distances.push(parseFloat(r.toFixed(1)));
            intensities.push(calcIntensity(P, r));
        }
        return { distances, intensities };
    }

    let P = parseInt(sliderPower.value);
    let r_active = parseFloat(sliderDist.value);
    let simData = updateInvSqData(P);

    invsqChart = new Chart(ctx.getContext("2d"), {
        type: 'line',
        data: {
            labels: simData.distances,
            datasets: [{
                label: `Intensidad para P=${P}W`,
                data: simData.intensities,
                borderColor: '#eab308',
                backgroundColor: 'rgba(234, 179, 8, 0.1)',
                borderWidth: 3,
                fill: true,
                tension: 0.4,
                pointRadius: 0
            }, {
                label: 'Punto Actual',
                data: [{ x: r_active, y: calcIntensity(P, r_active) }],
                backgroundColor: '#ef4444',
                borderColor: '#ef4444',
                pointRadius: 6,
                type: 'scatter'
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                x: {
                    title: { display: true, text: 'Distancia r (m)', color: '#94a3b8' },
                    grid: { color: 'rgba(255, 255, 255, 0.05)' },
                    ticks: { color: '#94a3b8' },
                    type: 'linear',
                    min: 0.5,
                    max: 10
                },
                y: {
                    title: { display: true, text: 'Intensidad Incidente I (W/m²)', color: '#94a3b8' },
                    grid: { color: 'rgba(255, 255, 255, 0.05)' },
                    ticks: { color: '#94a3b8' }
                }
            },
            plugins: {
                legend: { labels: { color: '#f1f5f9', font: { family: 'Outfit', size: 12 } } },
                tooltip: {
                    callbacks: {
                        label: function (context) {
                            return `I = ${context.parsed.y.toFixed(2)} W/m²`;
                        }
                    }
                }
            }
        }
    });

    const updateDisplay = () => {
        const p_val = parseInt(sliderPower.value);
        const r_val = parseFloat(sliderDist.value);

        const I = calcIntensity(p_val, r_val);
        document.getElementById("invsq-intensity-val").innerHTML = `${I.toFixed(2)} W/m&sup2;`;

        const newData = updateInvSqData(p_val);
        invsqChart.data.datasets[0].label = `Intensidad para P=${p_val}W`;
        invsqChart.data.datasets[0].data = newData.intensities;

        // Update scatter point
        invsqChart.data.datasets[1].data = [{ x: r_val, y: I }];

        invsqChart.update('none');
    };

    sliderPower.addEventListener("input", updateDisplay);
    sliderDist.addEventListener("input", updateDisplay);

    syncSliderAndNumberInput(sliderPower, document.getElementById('invsq-power-num'), updateDisplay);
    syncSliderAndNumberInput(sliderDist, document.getElementById('invsq-dist-num'), updateDisplay);

    updateDisplay();
}

/* =========================================================================
   FIN COOLING SIMULATOR
   ========================================================================= */
let finChart;

function initFinSimulation() {
    const sliderL = document.getElementById("fin-length");
    const sliderK = document.getElementById("fin-k");
    const sliderH = document.getElementById("fin-h");
    const sliderTL = document.getElementById("fin-tl");
    const sliderTinf = document.getElementById("fin-tinf");
    const sliderD = document.getElementById("fin-d");
    const ctx = document.getElementById("finChart");
    if (!ctx) return;

    // Constants
    let Tb = 100; // Base temperature 100 °C

    function calcHeatRates(L_m, k, h, TL, Tinf, P, A) {

        const m = Math.sqrt((h * P) / (k * A));
        const theta_b = Tb - Tinf;
        const M = Math.sqrt(h * P * k * A) * theta_b;
        const h_mk = h / (m * k);
        const mL = m * L_m;

        // Infinitamente Larga
        const q_inf = M;

        // Punta Aislada
        const q_iso = M * Math.tanh(mL);

        // Punta con Convección
        const numConv = Math.sinh(mL) + h_mk * Math.cosh(mL);
        const denConv = Math.cosh(mL) + h_mk * Math.sinh(mL);
        const q_conv = M * (numConv / denConv);

        // Punta Temperatura Especificada
        const theta_L = TL - Tinf;
        const q_spec = M * (Math.cosh(mL) - (theta_L / theta_b)) / Math.sinh(mL);

        // Longitud Corregida
        const L_c = L_m + A / P;
        const q_corr = M * Math.tanh(m * L_c);

        return { q_iso, q_conv, q_spec, q_inf, q_corr };
    }

    function calcTemps(x, L, k, h, TL, Tinf, P, A) {

        const m = Math.sqrt((h * P) / (k * A));
        const theta_b = Tb - Tinf;
        const h_mk = h / (m * k);

        // Punta aislada (Adiabática)
        const numIso = Math.cosh(m * (L - x));
        const denIso = Math.cosh(m * L);
        const T_iso = Tinf + theta_b * (numIso / denIso);

        // Punta con convección
        const numConv = Math.cosh(m * (L - x)) + h_mk * Math.sinh(m * (L - x));
        const denConv = Math.cosh(m * L) + h_mk * Math.sinh(m * L);
        const T_conv = Tinf + theta_b * (numConv / denConv);

        // Punta a temperatura especificada
        const theta_L = TL - Tinf;
        const numSpec = (theta_L / theta_b) * Math.sinh(m * x) + Math.sinh(m * (L - x));
        const denSpec = Math.sinh(m * L);
        const T_spec = Tinf + theta_b * (numSpec / denSpec);

        // Infinitamente Larga
        const T_infLong = Tinf + theta_b * Math.exp(-m * x);
        const L_c = L + A / P;
        const numCorr = Math.cosh(m * (L_c - x));
        const denCorr = Math.cosh(m * L_c);
        const T_corr = Tinf + theta_b * (numCorr / denCorr);
        return { T_iso, T_conv, T_spec, T_infLong, T_corr };
    }

    function updateFinData(L_cm, k, h, TL, Tinf, P, A) {
        const L = L_cm / 100.0;
        const x_cm_arr = [];
        const T_iso_arr = [];
        const T_conv_arr = [];
        const T_spec_arr = [];
        const T_infLong_arr = [];
        const T_corr_arr = [];

        // 50 points along the fin
        for (let i = 0; i <= 50; i++) {
            const x_cm = (i / 50) * L_cm;
            const x = x_cm / 100.0;
            x_cm_arr.push(parseFloat(x_cm.toFixed(2)));

            const temps = calcTemps(x, L, k, h, TL, Tinf, P, A);
            T_iso_arr.push(temps.T_iso);
            T_conv_arr.push(temps.T_conv);
            T_spec_arr.push(temps.T_spec);
            T_infLong_arr.push(temps.T_infLong);
            T_corr_arr.push(temps.T_corr);
        }
        return { x_cm_arr, T_iso_arr, T_conv_arr, T_spec_arr, T_infLong_arr, T_corr_arr };
    }

    let L_cm = parseInt(sliderL.value);
    let k = parseInt(sliderK.value);
    let h = parseInt(sliderH.value);
    let TL = parseInt(sliderTL.value);
    let Tinf = parseInt(sliderTinf.value);
    let D_mm = parseInt(sliderD.value);
    let P_init = Math.PI * (D_mm / 1000.0);
    let Ac_init = (Math.PI / 4) * Math.pow(D_mm / 1000.0, 2);
    let simData = updateFinData(L_cm, k, h, TL, Tinf, P_init, Ac_init);

    finChart = new Chart(ctx.getContext("2d"), {
        type: 'line',
        data: {
            labels: simData.x_cm_arr,
            datasets: [{
                label: `Punta Aislada`,
                data: simData.T_iso_arr,
                borderColor: '#ef4444',
                backgroundColor: 'rgba(239, 68, 68, 0.1)',
                borderWidth: 3,
                fill: true,
                tension: 0.4,
                pointRadius: 0
            }, {
                label: `Punta c/ Convección`,
                data: simData.T_conv_arr,
                borderColor: '#3b82f6',
                backgroundColor: 'rgba(59, 130, 246, 0.0)',
                borderWidth: 3,
                borderDash: [5, 5],
                fill: false,
                tension: 0.4,
                pointRadius: 0
            }, {
                label: `Temp. Especificada`,
                data: simData.T_spec_arr,
                borderColor: '#10b981',
                backgroundColor: 'rgba(16, 185, 129, 0.0)',
                borderWidth: 3,
                borderDash: [2, 2],
                fill: false,
                tension: 0.4,
                pointRadius: 0
            }, {
                label: `Infinitamente Larga`,
                data: simData.T_infLong_arr,
                borderColor: '#eab308',
                backgroundColor: 'rgba(234, 179, 8, 0.0)',
                borderWidth: 3,
                borderDash: [10, 5],
                fill: false,
                tension: 0.4,
                pointRadius: 0
            }, {
                label: `Long. Corregida`,
                data: simData.T_corr_arr,
                borderColor: '#a855f7',
                backgroundColor: 'rgba(168, 85, 247, 0.0)',
                borderWidth: 3,
                borderDash: [8, 4],
                fill: false,
                tension: 0.4,
                pointRadius: 0
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                x: {
                    title: { display: true, text: 'Distancia x (cm)', color: '#94a3b8' },
                    grid: { color: 'rgba(255, 255, 255, 0.05)' },
                    ticks: { color: '#94a3b8' }
                },
                y: {
                    title: { display: true, text: 'Temperatura T (°C)', color: '#94a3b8' },
                    grid: { color: 'rgba(255, 255, 255, 0.05)' },
                    ticks: { color: '#94a3b8' }
                }
            },
            plugins: {
                legend: { labels: { color: '#f1f5f9', font: { family: 'Outfit', size: 12 } } },
                tooltip: {
                    callbacks: {
                        label: function (context) {
                            return `${context.dataset.label}: ${context.parsed.y.toFixed(1)} °C`;
                        }
                    }
                }
            }
        }
    });

    const updateDisplay = () => {
        const sliderTb = document.getElementById("fin-tb");
        const valTb = document.getElementById("fin-tb-val");
        if (sliderTb) {
            Tb = parseFloat(sliderTb.value);
            if (valTb) valTb.textContent = Tb;
        }
        const l_val = parseInt(sliderL.value);
        const k_val = parseInt(sliderK.value);
        const h_val = parseInt(sliderH.value);
        const tl_val = parseInt(sliderTL.value);
        const tinf_val = parseInt(sliderTinf.value);
        const d_val = parseInt(sliderD.value);
        const w_val = parseInt(document.getElementById("fin-w").value);
        const t_val = parseInt(document.getElementById("fin-t").value);
        const shape = document.getElementById("fin-shape").value;

        // LOTE 3: los badges de sólo lectura fin-d-val/fin-w-val/fin-t-val/
        // fin-length-val/fin-k-val/fin-h-val/fin-tinf-val/fin-tl-val fueron
        // reemplazados por <input type="number"> (ver index.html); su valor
        // ya lo mantiene sincronizado syncSliderAndNumberInput() (LOTE 2),
        // así que estas escrituras quedaron obsoletas y se retiraron.

        let Ac, P;
        if (shape === 'circular') {
            const D_m = d_val / 1000.0;
            Ac = (Math.PI / 4) * Math.pow(D_m, 2);
            P = Math.PI * D_m;
        } else {
            const W_m = w_val / 1000.0;
            const T_m = t_val / 1000.0;
            Ac = W_m * T_m;
            P = 2 * (W_m + T_m);
        }

        const newData = updateFinData(l_val, k_val, h_val, tl_val, tinf_val, P, Ac);
        finChart.data.labels = newData.x_cm_arr;
        finChart.data.datasets[0].data = newData.T_iso_arr;
        finChart.data.datasets[1].data = newData.T_conv_arr;
        finChart.data.datasets[2].data = newData.T_spec_arr;
        finChart.data.datasets[3].data = newData.T_infLong_arr;
        if (finChart.data.datasets[4]) finChart.data.datasets[4].data = newData.T_corr_arr;

        // Update tip temperatures
        const tipTempIso = newData.T_iso_arr[newData.T_iso_arr.length - 1];
        const tipTempConv = newData.T_conv_arr[newData.T_conv_arr.length - 1];
        const tipTempSpec = newData.T_spec_arr[newData.T_spec_arr.length - 1];
        const tipTempInf = newData.T_infLong_arr[newData.T_infLong_arr.length - 1];
        const tipTempCorr = newData.T_corr_arr[newData.T_corr_arr.length - 1];
        document.getElementById("fin-tip-temp-iso-val").innerHTML = `${tipTempIso.toFixed(1)} &deg;C`;
        document.getElementById("fin-tip-temp-conv-val").innerHTML = `${tipTempConv.toFixed(1)} &deg;C`;
        document.getElementById("fin-tip-temp-spec-val").innerHTML = `${tipTempSpec.toFixed(1)} &deg;C`;
        document.getElementById("fin-tip-temp-inf-val").innerHTML = `${tipTempInf.toFixed(1)} &deg;C`;
        const elTipCorr = document.getElementById("fin-tip-temp-corr-val");
        if (elTipCorr) elTipCorr.innerHTML = `${tipTempCorr.toFixed(1)} &deg;C`;

        finChart.update('none');

        const sliderX = document.getElementById("fin-x");
        if (sliderX) {
            sliderX.max = l_val;
            let x_val = parseFloat(sliderX.value);
            if (x_val > l_val) { x_val = l_val; sliderX.value = l_val; }
            // LOTE 3: fin-x-val ahora es <input type="number"> (fin-x-num),
            // sincronizado por syncSliderAndNumberInput() — ver arriba. El
            // "max" del número debe seguir al del slider (que cambia con
            // fin-length) para no bloquear valores que el slider sí admite.
            const finXNum = document.getElementById('fin-x-num');
            if (finXNum) {
                finXNum.max = l_val;
                if (document.activeElement !== finXNum) finXNum.value = x_val.toFixed(1);
            }

            const x_m = x_val / 100.0;
            const L_m = l_val / 100.0;
            const tempsAtX = calcTemps(x_m, L_m, k_val, h_val, tl_val, tinf_val, P, Ac);

            const elIso = document.getElementById("fin-x-iso-val");
            const elConv = document.getElementById("fin-x-conv-val");
            const elSpec = document.getElementById("fin-x-spec-val");
            const elInf = document.getElementById("fin-x-inf-val");
            const elCorr = document.getElementById("fin-x-corr-val");

            if (elIso) elIso.innerHTML = tempsAtX.T_iso.toFixed(1);
            if (elConv) elConv.innerHTML = tempsAtX.T_conv.toFixed(1);
            if (elSpec) elSpec.innerHTML = tempsAtX.T_spec.toFixed(1);
            if (elInf) elInf.innerHTML = tempsAtX.T_infLong.toFixed(1);
            if (elCorr) elCorr.innerHTML = tempsAtX.T_corr.toFixed(1);
        }

        // Calculate and update heat rates, efficiency, and effectiveness
        const L_m = l_val / 100.0;
        const A_c = Ac; // already calculated above
        const heats = calcHeatRates(L_m, k_val, h_val, tl_val, tinf_val, P, A_c);
        const theta_b = Tb - tinf_val;

        const q_no_fin = h_val * A_c * theta_b;
        const q_max = h_val * P * L_m * theta_b;

        const m_val = Math.sqrt((h_val * P) / (k_val * A_c));
        const acElem = document.getElementById("fin-ac-display-val");
        const mElem = document.getElementById("fin-m-display-val");
        if (acElem) acElem.innerHTML = A_c.toExponential(4);
        if (mElem) mElem.innerHTML = m_val.toFixed(2);

        document.getElementById("fin-q-iso-val").innerHTML = `${heats.q_iso.toFixed(2)}`;
        document.getElementById("fin-q-conv-val").innerHTML = `${heats.q_conv.toFixed(2)}`;
        document.getElementById("fin-q-spec-val").innerHTML = `${heats.q_spec.toFixed(2)}`;
        document.getElementById("fin-q-inf-val").innerHTML = `${heats.q_inf.toFixed(2)}`;
        const elQCorr = document.getElementById("fin-q-corr-val");
        if (elQCorr) elQCorr.innerHTML = `${heats.q_corr.toFixed(2)}`;

        // Efficiency (eta)
        document.getElementById("fin-eff-iso-val").innerHTML = Math.abs(q_max) > 1e-6 ? `${(heats.q_iso / q_max * 100).toFixed(1)}` : `0.0`;
        document.getElementById("fin-eff-conv-val").innerHTML = Math.abs(q_max) > 1e-6 ? `${(heats.q_conv / q_max * 100).toFixed(1)}` : `0.0`;
        document.getElementById("fin-eff-spec-val").innerHTML = Math.abs(q_max) > 1e-6 ? `${(heats.q_spec / q_max * 100).toFixed(1)}` : `0.0`;
        const elEffCorr = document.getElementById("fin-eff-corr-val");
        if (elEffCorr) elEffCorr.innerHTML = Math.abs(q_max) > 1e-6 ? `${(heats.q_corr / q_max * 100).toFixed(1)}` : `0.0`;

        // Effectiveness (epsilon)
        document.getElementById("fin-eps-iso-val").innerHTML = Math.abs(q_no_fin) > 1e-6 ? `${(heats.q_iso / q_no_fin).toFixed(1)}` : `0.0`;
        document.getElementById("fin-eps-conv-val").innerHTML = Math.abs(q_no_fin) > 1e-6 ? `${(heats.q_conv / q_no_fin).toFixed(1)}` : `0.0`;
        document.getElementById("fin-eps-spec-val").innerHTML = Math.abs(q_no_fin) > 1e-6 ? `${(heats.q_spec / q_no_fin).toFixed(1)}` : `0.0`;
        document.getElementById("fin-eps-inf-val").innerHTML = Math.abs(q_no_fin) > 1e-6 ? `${(heats.q_inf / q_no_fin).toFixed(1)}` : `0.0`;
        const elEpsCorr = document.getElementById("fin-eps-corr-val");
        if (elEpsCorr) elEpsCorr.innerHTML = Math.abs(q_no_fin) > 1e-6 ? `${(heats.q_corr / q_no_fin).toFixed(1)}` : `0.0`;
    };

    sliderD.addEventListener("input", updateDisplay);
    document.getElementById("fin-w").addEventListener("input", updateDisplay);
    document.getElementById("fin-t").addEventListener("input", updateDisplay);
    document.getElementById("fin-shape").addEventListener("change", function () {
        if (this.value === 'circular') {
            document.getElementById('fin-d-group').style.display = 'block';
            document.getElementById('fin-w-group').style.display = 'none';
            document.getElementById('fin-t-group').style.display = 'none';
        } else {
            document.getElementById('fin-d-group').style.display = 'none';
            document.getElementById('fin-w-group').style.display = 'block';
            document.getElementById('fin-t-group').style.display = 'block';
        }
        updateDisplay();
    });
    const sliderTb = document.getElementById("fin-tb");
    if (sliderTb) sliderTb.addEventListener("input", updateDisplay);
    sliderL.addEventListener("input", updateDisplay);
    sliderK.addEventListener("input", updateDisplay);
    sliderH.addEventListener("input", updateDisplay);
    sliderTL.addEventListener("input", updateDisplay);
    sliderTinf.addEventListener("input", updateDisplay);
    const sliderX = document.getElementById("fin-x");
    if (sliderX) sliderX.addEventListener("input", updateDisplay);

    // LOTE 3 — entrada numérica directa: conecta cada slider con su
    // <input type="number"> hermano vía el helper global del LOTE 2,
    // reutilizando updateDisplay sin duplicar lógica.
    [
        ['fin-tb-num', sliderTb], ['fin-d-num', sliderD], ['fin-w-num', document.getElementById('fin-w')],
        ['fin-t-num', document.getElementById('fin-t')], ['fin-length-num', sliderL], ['fin-k-num', sliderK],
        ['fin-h-num', sliderH], ['fin-tinf-num', sliderTinf], ['fin-tl-num', sliderTL], ['fin-x-num', sliderX]
    ].forEach(([numId, sliderEl]) => {
        const numEl = document.getElementById(numId);
        if (numEl && sliderEl) syncSliderAndNumberInput(sliderEl, numEl, updateDisplay);
    });

    updateDisplay();
}

// ----------------------------------------------------
let genChartInstance = null;

function initGenerationSimulation() {
    const sliderQdot = document.getElementById('gen-qdot');
    const sliderK = document.getElementById('gen-k');
    const sliderH = document.getElementById('gen-h');
    const sliderTinf = document.getElementById('gen-tinf');
    const sliderW = document.getElementById('gen-w');

    const valQdot = document.getElementById('gen-qdot-val');
    const valK = document.getElementById('gen-k-val');
    const valH = document.getElementById('gen-h-val');
    const valTinf = document.getElementById('gen-tinf-val');
    const valW = document.getElementById('gen-w-val');

    const valTs = document.getElementById('gen-ts-val');
    const valDeltaT = document.getElementById('gen-deltat-val');
    const valTmax = document.getElementById('gen-tmax-val');
    const valTsCyl = document.getElementById('gen-ts-cyl');
    const valTmaxCyl = document.getElementById('gen-tmax-cyl');
    const valTsSph = document.getElementById('gen-ts-sph');
    const valTmaxSph = document.getElementById('gen-tmax-sph');

    // Panel consolidado de ecuaciones (#gen-equations-summary-panel): referencias DOM
    const valEqEgot = document.getElementById('gen-eq-egot-val');
    const valEqTs = document.getElementById('gen-eq-ts-val');
    const valEqDtmax = document.getElementById('gen-eq-dtmax-val');
    const valEqTmax = document.getElementById('gen-eq-tmax-val');
    const geomCells = document.querySelectorAll('#gen-equations-summary-panel .geom-cell[data-geom]');

    // Geometría activa del panel de ecuaciones (Pared Plana por defecto,
    // seleccionable al hacer clic/Enter sobre cualquier celda de geometría).
    let activeGenGeometry = 'plate';
    const GEN_GEOMETRY_N = { plate: 1, cylinder: 2, sphere: 3 }; // factor de forma n

    const ctx = document.getElementById('genChart').getContext('2d');

    genChartInstance = new Chart(ctx, {
        type: 'line',
        data: {
            labels: [],
            datasets: [
                {
                    label: 'Pared Plana',
                    data: [],
                    borderColor: '#f97316',
                    backgroundColor: 'rgba(249, 115, 22, 0.05)',
                    borderWidth: 3,
                    pointRadius: 0,
                    fill: false,
                    tension: 0.4
                },
                {
                    label: 'Cilindro Infinito',
                    data: [],
                    borderColor: '#06b6d4',
                    backgroundColor: 'rgba(6, 182, 212, 0.05)',
                    borderWidth: 3,
                    pointRadius: 0,
                    fill: false,
                    tension: 0.4
                },
                {
                    label: 'Esfera',
                    data: [],
                    borderColor: '#10b981',
                    backgroundColor: 'rgba(16, 185, 129, 0.05)',
                    borderWidth: 3,
                    pointRadius: 0,
                    fill: false,
                    tension: 0.4
                }
            ]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                x: {
                    type: 'linear',
                    title: { display: true, text: 'Posición x (m)', color: '#94a3b8' },
                    grid: { color: 'rgba(255,255,255,0.1)' },
                    ticks: { color: '#cbd5e1' }
                },
                y: {
                    title: { display: true, text: 'Temperatura (°C)', color: '#94a3b8' },
                    grid: { color: 'rgba(255,255,255,0.1)' },
                    ticks: { color: '#cbd5e1' }
                }
            },
            plugins: {
                legend: { labels: { color: '#e2e8f0' } },
                annotation: {
                    annotations: {
                        leftWall: {
                            type: 'line',
                            xMin: 0,
                            xMax: 0,
                            borderColor: '#38bdf8',
                            borderWidth: 2,
                            borderDash: [5, 5],
                            label: {
                                display: true,
                                content: 'Superficie',
                                position: 'end',
                                backgroundColor: 'rgba(56, 189, 248, 0.8)'
                            }
                        },
                        rightWall: {
                            type: 'line',
                            xMin: 0,
                            xMax: 0,
                            borderColor: '#38bdf8',
                            borderWidth: 2,
                            borderDash: [5, 5],
                            label: {
                                display: true,
                                content: 'Superficie',
                                position: 'end',
                                backgroundColor: 'rgba(56, 189, 248, 0.8)'
                            }
                        }
                    }
                }
            }
        }
    });

    // Cálculo explícito de Ts, ΔT_max y T_max a partir del factor de forma n
    // (n = 1 pared plana, n = 2 cilindro infinito, n = 3 esfera):
    //   Ts       = T∞ + (q̇·L) / (n·h)
    //   ΔT_max   = (q̇·L²) / (2·n·k)
    //   T_max    = Ts + ΔT_max
    function calcGenTemps(qdot, L, h, k, Tinf, n) {
        const Ts = Tinf + (qdot * L) / (n * h);
        const deltaT = (qdot * L * L) / (2 * n * k);
        const Tmax = Ts + deltaT;
        return { Ts, deltaT, Tmax };
    }

    // ---------------------------------------------------------------
    // Balance Global de Energía (Tareas 1-4)
    // ---------------------------------------------------------------
    // Tarea 1 (parámetros geométricos activos): el simulador reutiliza el
    // mismo semi-espesor L como radio r0 para cilindro y esfera (las
    // tarjetas de resultados los describen como "Diámetro = 2L"). Como el
    // laboratorio no expone sliders de área/longitud propios, se usa una
    // base unitaria de referencia: A = 1 m² de pared y H = 1 m de cilindro.
    const GEN_UNIT_AREA = 1;   // A: área unitaria de la pared plana [m²]
    const GEN_UNIT_LENGTH = 1; // H: longitud unitaria del cilindro [m]

    // Tarea 2: Volumen geométrico V según el tipo de cuerpo.
    //   Pared plana : V = 2AL
    //   Cilindro    : V = π r0² H
    //   Esfera      : V = (4/3) π r0³
    function calcGenVolume(geometry, L, r0, A, H) {
        switch (geometry) {
            case 'plate': return 2 * A * L;
            case 'cylinder': return Math.PI * r0 * r0 * H;
            case 'sphere': return (4 / 3) * Math.PI * Math.pow(r0, 3);
            default: return NaN;
        }
    }

    // Área superficial de convección As según el tipo de cuerpo.
    //   Pared plana (ambas caras) : As = 2A
    //   Cilindro                  : As = 2π r0 H
    //   Esfera                    : As = 4π r0²
    function calcGenSurfaceArea(geometry, r0, A, H) {
        switch (geometry) {
            case 'plate': return 2 * A;
            case 'cylinder': return 2 * Math.PI * r0 * H;
            case 'sphere': return 4 * Math.PI * r0 * r0;
            default: return NaN;
        }
    }

    // Evita solapar llamadas a MathJax.typesetPromise sobre el panel de
    // ecuaciones mientras una anterior sigue en curso (tipografiado seguro).
    let genBalanceTypesetPending = false;
    function typesetGenEnergyBalance() {
        const panel = document.getElementById('gen-equations-summary-panel');
        if (!panel || !window.MathJax || typeof MathJax.typesetPromise !== 'function') return;
        if (genBalanceTypesetPending) return;
        genBalanceTypesetPending = true;
        MathJax.typesetPromise([panel])
            .catch(function (err) {
                console.log('MathJax gen-equations-summary-panel error:', err);
            })
            .finally(function () {
                genBalanceTypesetPending = false;
            });
    }

    // Resalta con .active-geom-row la(s) celda(s) de la geometría activa
    // en las tres cuadrículas de comparación del panel (Volumen, Ts, ΔT_max).
    function updateActiveGeomHighlight() {
        geomCells.forEach(cell => {
            cell.classList.toggle('active-geom-row', cell.dataset.geom === activeGenGeometry);
        });
    }

    // Cambia la geometría activa (llamado al hacer clic/Enter sobre una
    // celda) y fuerza el recálculo + resaltado + tipografiado del panel.
    function setActiveGenGeometry(geometry) {
        if (!GEN_GEOMETRY_N[geometry] || geometry === activeGenGeometry) return;
        activeGenGeometry = geometry;
        updateSimulation();
    }

    geomCells.forEach(cell => {
        cell.style.cursor = 'pointer';
        cell.setAttribute('role', 'button');
        cell.setAttribute('tabindex', '0');
        cell.addEventListener('click', () => setActiveGenGeometry(cell.dataset.geom));
        cell.addEventListener('keydown', (e) => {
            if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                setActiveGenGeometry(cell.dataset.geom);
            }
        });
    });

    function updateSimulation() {
        const qdot = parseFloat(sliderQdot.value) * 1000;
        const k = parseFloat(sliderK.value);
        const h = parseFloat(sliderH.value);
        const Tinf = parseFloat(sliderTinf.value);
        const w = parseFloat(sliderW.value);
        const L = w / 2;

        // Pared Plana (n = 1)
        const { Ts, deltaT, Tmax } = calcGenTemps(qdot, L, h, k, Tinf, 1);
        valTs.textContent = Ts.toFixed(1) + " °C";
        if (valDeltaT) valDeltaT.textContent = deltaT.toFixed(1) + " °C";
        valTmax.textContent = Tmax.toFixed(1) + " °C";

        // Cilindro Infinito (n = 2)
        const { Ts: TsCyl, Tmax: TmaxCyl } = calcGenTemps(qdot, L, h, k, Tinf, 2);
        if (valTsCyl) valTsCyl.textContent = TsCyl.toFixed(1) + " °C";
        if (valTmaxCyl) valTmaxCyl.textContent = TmaxCyl.toFixed(1) + " °C";

        // Esfera (n = 3)
        const { Ts: TsSph, Tmax: TmaxSph } = calcGenTemps(qdot, L, h, k, Tinf, 3);
        if (valTsSph) valTsSph.textContent = TsSph.toFixed(1) + " °C";
        if (valTmaxSph) valTmaxSph.textContent = TmaxSph.toFixed(1) + " °C";

        // -------------------------------------------------------------
        // Panel de Ecuaciones (#gen-equations-summary-panel): V, Ė_gen,
        // T_s, ΔT_max y T_max según la GEOMETRÍA ACTIVA seleccionada
        // (Pared: n=1 → 2k; Cilindro: n=2 → 4k; Esfera: n=3 → 6k),
        // reutilizando calcGenTemps() con el factor de forma n correcto.
        // -------------------------------------------------------------
        const activeN = GEN_GEOMETRY_N[activeGenGeometry] || 1;
        const activeR0 = L; // radio de cilindro/esfera == semi-espesor de la pared
        const { Ts: activeTs, deltaT: activeDeltaT, Tmax: activeTmax } =
            calcGenTemps(qdot, L, h, k, Tinf, activeN);

        // Tarea 1: Volumen (V) y Tasa Total de Generación Ė_gen = q̇·V [W]
        const activeVolume = calcGenVolume(activeGenGeometry, L, activeR0, GEN_UNIT_AREA, GEN_UNIT_LENGTH);
        const activeEgen = qdot * activeVolume;

        // Validación numérica del balance estacionario Ė_gen = Q̇_conv
        // (Q̇_conv = h·As·(Ts-T∞)) para la geometría activa.
        const activeAs = calcGenSurfaceArea(activeGenGeometry, activeR0, GEN_UNIT_AREA, GEN_UNIT_LENGTH);
        const activeQconv = h * activeAs * (activeTs - Tinf);
        const activeBalanceError = Math.abs(activeEgen - activeQconv);
        if (activeBalanceError >= Math.max(1e-6, Math.abs(activeEgen) * 1e-3)) {
            console.warn('[gen-sim] Balance de energía Ė_gen ≠ Q̇_conv (' + activeGenGeometry + '):',
                { activeEgen, activeQconv, activeBalanceError });
        }

        // Tarea 2: inyección de los valores formateados ante cualquier evento
        // de cambio en los controles (sliders) o en la geometría activa.
        if (valEqEgot) {
            valEqEgot.textContent = Math.abs(activeEgen) >= 1000
                ? (activeEgen / 1000).toFixed(2) + " kW"
                : activeEgen.toFixed(1) + " W";
        }
        if (valEqTs) valEqTs.textContent = activeTs.toFixed(1) + " °C";
        if (valEqDtmax) valEqDtmax.textContent = activeDeltaT.toFixed(1) + " °C";
        if (valEqTmax) valEqTmax.textContent = activeTmax.toFixed(1) + " °C";

        // Tarea 3: resalta la geometría activa y tipografía MathJax de forma segura.
        updateActiveGeomHighlight();
        typesetGenEnergyBalance();

        const points = 50;
        const dataPlate = [];
        const dataCyl = [];
        const dataSph = [];
        const dx = w / points;

        for (let i = 0; i <= points; i++) {
            const x = -L + i * dx;
            const r = Math.abs(x);

            // Plate
            const T_plate = Ts + (qdot / (2 * k)) * (L * L - x * x);
            dataPlate.push({ x: x, y: T_plate });

            // Cylinder
            const T_cyl = TsCyl + (qdot / (4 * k)) * (L * L - r * r);
            dataCyl.push({ x: x, y: T_cyl });

            // Sphere
            const T_sph = TsSph + (qdot / (6 * k)) * (L * L - r * r);
            dataSph.push({ x: x, y: T_sph });
        }

        genChartInstance.data.datasets[0].data = dataPlate;
        genChartInstance.data.datasets[1].data = dataCyl;
        genChartInstance.data.datasets[2].data = dataSph;

        genChartInstance.options.plugins.annotation.annotations.leftWall.xMin = -L;
        genChartInstance.options.plugins.annotation.annotations.leftWall.xMax = -L;
        genChartInstance.options.plugins.annotation.annotations.rightWall.xMin = L;
        genChartInstance.options.plugins.annotation.annotations.rightWall.xMax = L;

        const margin = Math.max(10, (Tmax - Tinf) * 0.2);
        genChartInstance.options.scales.y.min = Math.floor(Tinf - margin);
        genChartInstance.options.scales.y.max = Math.ceil(Tmax + margin);
        genChartInstance.options.scales.x.min = -L * 1.2;
        genChartInstance.options.scales.x.max = L * 1.2;

        genChartInstance.update();
    }

    [sliderQdot, sliderK, sliderH, sliderTinf, sliderW].forEach(slider => {
        slider.addEventListener('input', updateSimulation);
    });

    syncSliderAndNumberInput(sliderQdot, document.getElementById('gen-qdot-num'), updateSimulation);
    syncSliderAndNumberInput(sliderK, document.getElementById('gen-k-num'), updateSimulation);
    syncSliderAndNumberInput(sliderH, document.getElementById('gen-h-num'), updateSimulation);
    syncSliderAndNumberInput(sliderTinf, document.getElementById('gen-tinf-num'), updateSimulation);
    syncSliderAndNumberInput(sliderW, document.getElementById('gen-w-num'), updateSimulation);

    window.addEventListener('resize', () => {
        if (document.getElementById('gen-sim').classList.contains('active')) {
            genChartInstance.resize();
            updateSimulation();
        }
    });

    updateSimulation();

    // Asegura el tipografiado MathJax del panel de teoría (Ts, ΔT_max, T_max)
    // por si el laboratorio se inicializa mientras su pestaña aún estaba
    // oculta durante el tipografiado global de la página.
    const genFormulaBlock = document.querySelector('#gen-sim .gen-formula-block');
    if (genFormulaBlock && window.MathJax && typeof MathJax.typesetPromise === 'function') {
        MathJax.typesetPromise([genFormulaBlock]).catch(function (err) {
            console.log('MathJax gen-sim error:', err);
        });
    }
}

// ==========================================
// Newton's Cooling Simulation
// ==========================================
function initNewtonSimulation() {
    const canvas = document.getElementById('newtonCanvas');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');

    const sliderTi = document.getElementById('newton-ti');
    const sliderTinf = document.getElementById('newton-tinf');
    const sliderD = document.getElementById('newton-d');
    const sliderK = document.getElementById('newton-k');
    const sliderRho = document.getElementById('newton-rho');
    const sliderCp = document.getElementById('newton-cp');

    const valTi = document.getElementById('newton-ti-val');
    const valTinf = document.getElementById('newton-tinf-val');
    const valD = document.getElementById('newton-d-val');
    const valK = document.getElementById('newton-k-val');
    const valRho = document.getElementById('newton-rho-val');
    const valCp = document.getElementById('newton-cp-val');

    const resTime = document.getElementById('newton-time');
    const tbodyResults = document.getElementById('newton-results-tbody');

    const startBtn = document.getElementById('newton-start-btn');
    const resetBtn = document.getElementById('newton-reset-btn');

    const graphCanvas = document.getElementById('newtonGraph');
    const graphCtx = graphCanvas.getContext('2d');

    const L_cylinder = 0.1;

    const mediums = [
        { name: "Aire Quieto", h: 15, color: "#8b5cf6" },   // Purple
        { name: "Aire Forzado", h: 70, color: "#3b82f6" },  // Blue
        { name: "Aceite", h: 300, color: "#eab308" },       // Yellow
        { name: "Agua", h: 1000, color: "#06b6d4" }         // Cyan
    ];

    let currentChartMax = 200;

    let chartInstance = new Chart(graphCtx, {
        type: 'line',
        data: {
            datasets: [
                ...mediums.map(m => ({
                    label: m.name,
                    data: [],
                    borderColor: m.color,
                    backgroundColor: m.color,
                    borderWidth: 2,
                    pointRadius: 0,
                    fill: false,
                    tension: 0.1
                })),
                {
                    label: 'Tiempo Actual',
                    data: [],
                    borderColor: '#f97316',
                    borderWidth: 1.5,
                    pointRadius: 0,
                    showLine: true,
                    fill: false
                },
                {
                    label: 'Puntos de Estado',
                    data: [],
                    borderColor: '#ffffff',
                    backgroundColor: '#ffffff',
                    pointRadius: 4,
                    showLine: false,
                    fill: false
                }
            ]
        },
        options: {
            legend: { display: true, position: 'top', labels: { color: '#e2e8f0', boxWidth: 12 } },
            plugins: { legend: { display: true, position: 'top', labels: { color: '#e2e8f0', boxWidth: 12 } } },
            responsive: true,
            maintainAspectRatio: false,
            animation: false,
            scales: {
                x: {
                    type: 'linear',
                    title: { display: true, text: 'Tiempo (s)', color: '#94a3b8' },
                    ticks: {
                        color: '#cbd5e1',
                        stepSize: 10,
                        precision: 0,
                        callback: function (value) {
                            if (currentChartMax <= 200) {
                                if (value % 10 === 0) return value;
                            } else {
                                if (value % 100 === 0) return value;
                            }
                        }
                    },
                    grid: { color: 'rgba(255,255,255,0.1)' }
                },
                y: {
                    title: { display: true, text: 'Temperatura (°C)', color: '#94a3b8' },
                    ticks: { color: '#cbd5e1' },
                    grid: { color: 'rgba(255,255,255,0.1)' }
                }
            }
        }
    });

    let animationId;
    let simTime = 0;
    let particles = [];
    const timeScale = 50;
    let lastTimestamp = 0;
    let isPlaying = false;

    let simSpeedMultiplier = 1;

    let currentTi, currentTinf, currentD, currentK, currentRho, currentCp;
    let simData = [];

    let currentTemps = [20, 20, 20, 20];
    let visualR = 40;

    // Umbral de equilibrio térmico: por debajo de este ΔT la convección natural
    // no tiene fuerza impulsora (ΔρAG → 0) y la animación del fluido debe
    // quedar estática. Física: cuando T_cilindro → T_∞, ΔT → 0 → β·g·ΔT → 0.
    const EQUILIBRIUM_EPSILON = 0.1; // °C

    // ── Escala proporcional de posiciones de partículas al redimensionar ────────
    // En vez de destruir y recrear el arreglo completo, traslada cada partícula
    // al nuevo espacio preservando su trayectoria. Se usa cuando ya existe un
    // arreglo de partículas con posiciones válidas y las dimensiones del canvas
    // cambian (resize de ventana, toggle fullscreen).
    // Las velocidades NO se escalan: son absolutas (px/frame) y pequeñas; el
    // motor de física ya las ajusta dinámicamente en cada frame via heatFactor.
    function rescaleParticles(oldW, oldH, newW, newH) {
        if (!oldW || !oldH || !newW || !newH) return;
        const sx = newW / oldW;
        const sy = newH / oldH;
        particles.forEach(p => {
            p.x *= sx;
            p.y *= sy;
        });
    }

    function initParticles() {
        // Leer siempre las dimensiones renderizadas del contenedor.
        // getBoundingClientRect() devuelve el tamaño real post-layout,
        // evitando el 0 que puede dar clientWidth antes del primer paint.
        const shell = canvas.closest('.newton-canvas-shell');
        const shellRect = shell ? shell.getBoundingClientRect() : null;
        const shellW = shellRect && shellRect.width > 0 ? shellRect.width : 0;
        const shellH = shellRect && shellRect.height > 0 ? shellRect.height : 0;

        const newW = shellW > 0 ? Math.floor(shellW) : (canvas.clientWidth || canvas.offsetWidth || 600);
        const newH = shellH > 0 ? Math.floor(shellH) : (canvas.clientHeight || canvas.offsetHeight || 300);

        // Solo reasignar si las dimensiones realmente cambiaron
        if (canvas.width !== newW || canvas.height !== newH) {
            canvas.width = newW;
            canvas.height = newH;
        }

        particles = [];
        const numCylinders = 4;
        const spacing = canvas.width / numCylinders;   // recalcula con ancho real
        const currentD_init = parseFloat(sliderD.value);
        const visualR_init = 15 + (currentD_init / 0.30) * 50;

        for (let zone = 0; zone < numCylinders; zone++) {
            const cx = spacing * zone + spacing / 2;
            const cy = canvas.height / 2;
            for (let i = 0; i < 20; i++) {
                particles.push(new NewtonPlumeParticle(cx, cy, visualR_init, zone, i));
            }
        }
    }

    class NewtonPlumeParticle {
        constructor(cx, cy, baseR, zone, idx) {
            this.zone = zone;
            this.idx = idx;
            this.reset(cx, cy, baseR);
            // Stagger initial progress
            this.y = cy + (Math.random() - 0.5) * canvas.height;
            this.x = cx + (Math.random() - 0.5) * (baseR * 2);
            if (this.zone === 1) { // Forced Air
                this.x = (canvas.width / 4) * 1 + Math.random() * (canvas.width / 4);
                this.y = Math.random() * canvas.height;
            }
            this.life = Math.random();
        }

        reset(cx, cy, baseR) {
            this.life = 1.0;
            this.decay = 0.0015 + Math.random() * 0.0025;

            if (this.zone === 1) {
                // Forced air spawns at the left boundary of Zone 1
                const xMin = (canvas.width / 4) * 1;
                this.x = xMin;
                this.y = Math.random() * canvas.height;
                this.vx = 1.2 + Math.random() * 1.5;
                this.vy = (Math.random() - 0.5) * 0.15;
                this.size = 1.2 + Math.random() * 1.6;
            } else {
                // Natural convection: spawn below the cylinder
                const angle = (Math.PI / 2) + (Math.random() - 0.5) * Math.PI;
                this.x = cx + Math.cos(angle) * (baseR + 2);
                this.y = cy + Math.sin(angle) * (baseR + 2);
                this.side = Math.sign(this.x - cx) || 1;

                let speedScale = 1.0;
                if (this.zone === 0) speedScale = 0.5; // Aire Quieto
                else if (this.zone === 2) speedScale = 0.25; // Aceite
                else if (this.zone === 3) speedScale = 1.2; // Agua

                this.vx = (Math.random() - 0.5) * 0.04 * speedScale;
                this.vy = (-0.12 - Math.random() * 0.18) * speedScale;
                this.size = 1.2 + Math.random() * 2.0;
            }
        }

        update(cx, cy, baseR, heatFactor, w, h) {
            this.life -= this.decay;
            if (this.life <= 0) {
                this.reset(cx, cy, baseR);
                return;
            }

            const xMinZone = (canvas.width / 4) * this.zone;
            const xMaxZone = (canvas.width / 4) * (this.zone + 1);

            if (this.zone === 1) {
                // Forced Air update logic: fluid particles stream past and curve smoothly
                // around the cylinder, like a real flow wrapping around an obstacle
                const forceX = 0.05 * (1.0 + heatFactor);
                this.vx = Math.min(3.5, this.vx + forceX);

                const dx = this.x - cx;
                const dy = this.y - cy;
                const dist = Math.sqrt(dx * dx + dy * dy) || 0.0001;
                const minAllowedDist = baseR + 3;
                const influenceDist = baseR + 22;

                if (dist < influenceDist) {
                    const nx = dx / dist;
                    const ny = dy / dist;

                    // Cancel the velocity component pointing into the cylinder instead of
                    // letting the particle collide with (and bounce off) the solid surface
                    const dot = this.vx * nx + this.vy * ny;
                    if (dot < 0) {
                        this.vx -= dot * nx;
                        this.vy -= dot * ny;
                    }

                    // Smooth tangential acceleration that grows closer to the surface,
                    // curving the path gradually around the cylinder
                    const proximity = (influenceDist - dist) / influenceDist;
                    const tx = -ny;
                    const ty = nx;
                    const dir = Math.sign(dy) || 1;
                    const curve = 0.18 * proximity;
                    this.vx += tx * dir * curve;
                    this.vy += ty * dir * curve;

                    // Hard floor only to keep the particle out of the solid, no bounce impulse
                    if (dist < minAllowedDist) {
                        this.x = cx + nx * minAllowedDist;
                        this.y = cy + ny * minAllowedDist;
                    }
                }

                this.x += this.vx;
                this.y += this.vy;

                if (this.x > xMaxZone) {
                    this.reset(cx, cy, baseR);
                }
                if (this.y < 0 || this.y > h) {
                    this.y = Math.random() * h;
                    this.x = xMinZone;
                }
            } else {
                // Natural Convection update logic
                let speedScale = 1.0;
                if (this.zone === 0) speedScale = 0.5; // Aire Quieto
                else if (this.zone === 2) speedScale = 0.25; // Aceite
                else if (this.zone === 3) speedScale = 1.2; // Agua

                // ── FÍSICA CORRECTA ─────────────────────────────────────────────────────
                // La fuerza de flotación es β·g·ΔT·ρ, proporcional a ΔT = T_cil − T_∞.
                // heatFactor = ΔT / (Ti − T∞) ∈ [0,1]; cuando ΔT ≤ ε → heatFactor = 0
                // (forzado en draw()) → no hay gradiente de densidad → sin flujo convectivo
                // → las partículas deben decelerar hasta el reposo completo.
                // ────────────────────────────────────────────────────────────────────────
                const atEquilibrium = (heatFactor <= 0);

                if (atEquilibrium) {
                    // Sin fuerza impulsora: amortiguación viscosa hasta v = 0
                    this.vx *= 0.82;
                    this.vy *= 0.82;
                    if (Math.abs(this.vx) < 0.005 && Math.abs(this.vy) < 0.005) {
                        this.vx = 0;
                        this.vy = 0;
                    }
                } else {
                    // Fuerza de flotación proporcional a ΔT (no a un mínimo artificial)
                    const buoyancyForce = Math.min(0.5, heatFactor * 0.5);
                    this.vy -= buoyancyForce * 0.015 * speedScale;

                    // Agitación molecular aleatoria también proporcional a ΔT
                    this.vx += (Math.random() - 0.5) * 0.012 * heatFactor * speedScale;
                    this.vy += (Math.random() - 0.5) * 0.012 * heatFactor * speedScale;

                    const maxVy = (0.35 + heatFactor * 0.45) * speedScale;
                    const maxVx = 0.22 * speedScale;
                    this.vx = Math.max(-maxVx, Math.min(maxVx, this.vx));
                    this.vy = Math.max(-maxVy, Math.min(maxVy, this.vy));
                }

                this.x += this.vx;
                this.y += this.vy;

                // La fuerza de hugging y la oscilación de pluma solo actúan si hay ΔT.
                // buoyancyForce y waveAmp son proporcionales a heatFactor (no a un mínimo).
                const activeBuoyancy = atEquilibrium ? 0 : Math.min(0.5, heatFactor * 0.5);

                const dx = this.x - cx;
                const dy = this.y - cy;
                const dist = Math.sqrt(dx * dx + dy * dy);
                const minAllowedDist = baseR + 2;
                const huggingDist = baseR + 12;

                if (dist < huggingDist) {
                    const nx = dx / dist;
                    const ny = dy / dist;

                    if (dist < minAllowedDist) {
                        this.x = cx + nx * minAllowedDist;
                        this.y = cy + ny * minAllowedDist;
                    }

                    const inSeparationZone = (ny < -0.15); // separates at the top

                    if (!inSeparationZone) {
                        const dotProduct = this.vx * nx + this.vy * ny;
                        if (dotProduct < 0) {
                            this.vx -= dotProduct * nx;
                            this.vy -= dotProduct * ny;
                        }
                        const pullForce = 0.03 * (huggingDist - dist);
                        this.vx -= nx * pullForce;
                        this.vy -= ny * pullForce;

                        const tx = -ny;
                        const ty = nx;
                        const sweepDirection = -Math.sign(ty) || 1;
                        // sweepForce → 0 cuando ΔT → 0 (sin convección natural)
                        const sweepForce = (0.1 + Math.random() * 0.15) * (0.3 + activeBuoyancy);
                        this.vx += tx * sweepDirection * sweepForce * 0.15;
                        this.vy += ty * sweepDirection * sweepForce * 0.15;
                    } else {
                        if (!atEquilibrium) this.vy -= 0.05 * speedScale;
                    }
                }

                // Wave oscillation above cylinder: se apaga cuando ΔT → 0
                const yDist = cy - this.y;
                if (yDist > baseR && !atEquilibrium) {
                    const waveAmp = Math.min(6, (yDist - baseR) * 0.05 * Math.min(2, heatFactor * 5));
                    const waveOffset = Math.sin(this.y * 0.04 - performance.now() * 0.003) * waveAmp;
                    this.x += waveOffset * 0.05;
                }

                if (this.y < -10) {
                    this.reset(cx, cy, baseR);
                }
                if (this.x < xMinZone + 5) {
                    this.x = xMinZone + 5;
                    this.vx = Math.abs(this.vx);
                }
                if (this.x > xMaxZone - 5) {
                    this.x = xMaxZone - 5;
                    this.vx = -Math.abs(this.vx);
                }
            }
        }

        draw(ctx, heatFactor) {
            ctx.beginPath();
            ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);

            const alpha = this.life * 0.5;

            if (this.zone === 0) {
                // Aire quieto: warm amber
                ctx.fillStyle = `rgba(251, 191, 36, ${alpha})`;
            } else if (this.zone === 1) {
                // Aire forzado: light blue
                ctx.fillStyle = `rgba(147, 197, 253, ${alpha})`;
            } else if (this.zone === 2) {
                // Aceite: golden orange
                ctx.fillStyle = `rgba(249, 115, 22, ${alpha})`;
            } else {
                // Agua: cyan
                ctx.fillStyle = `rgba(34, 211, 238, ${alpha})`;
            }
            ctx.fill();
        }
    }

    let newtonTime = 0;

    function updateSimulationParams() {
        currentTi = parseFloat(sliderTi.value);
        currentTinf = parseFloat(sliderTinf.value);
        currentD = parseFloat(sliderD.value);
        currentK = parseFloat(sliderK.value);
        currentRho = parseFloat(sliderRho.value);
        currentCp = parseFloat(sliderCp.value);

        if (valTi) valTi.textContent = currentTi;
        if (valTinf) valTinf.textContent = currentTinf;
        if (valD) valD.textContent = currentD.toFixed(2);
        if (valK) valK.textContent = currentK.toFixed(1);
        if (valRho) valRho.textContent = currentRho;
        if (valCp) valCp.textContent = currentCp;

        const r = currentD / 2;
        const As = 2 * Math.PI * r * L_cylinder + 2 * Math.PI * r * r;
        const V = Math.PI * r * r * L_cylinder;
        const Lc = V / As;

        simData = mediums.map(m => {
            const Bi = (m.h * Lc) / currentK;
            const tau_lump = (currentRho * V * currentCp) / (m.h * As);
            const tau = tau_lump * (1 + Bi);
            return {
                name: m.name,
                h: m.h,
                Bi: Bi,
                tau: tau,
                color: m.color
            };
        });

        if (tbodyResults) {
            tbodyResults.innerHTML = '';
            const lang = (typeof getLang === 'function') ? getLang() : 'es';
            simData.forEach(d => {
                // ── Tiempos de equilibrio térmico ──────────────────────────────────────
                // τ es la constante de tiempo de la capacitancia global.
                // t₉₅ ≈ 3τ → el cilindro ha recorrido el 95.0% de (Ti − T∞)  [1−e⁻³ ≈ 0.950]
                // t₉₉ ≈ 5τ → el cilindro ha recorrido el 99.3% de (Ti − T∞)  [1−e⁻⁵ ≈ 0.993]
                const t95 = 3 * d.tau;
                const t99 = 5 * d.tau;

                // Helper: formatea segundos → "X.X s" o "X.X min" si ≥ 120 s
                function fmtTime(secs) {
                    return secs >= 120
                        ? (secs / 60).toFixed(1) + ' min'
                        : secs.toFixed(1) + ' s';
                }

                const tr = document.createElement('tr');
                tr.style.borderBottom = '1px solid rgba(255,255,255,0.05)';

                // Columna: Medio
                const tdName = document.createElement('td');
                tdName.style.padding = '4px';
                tdName.style.color = d.color;
                tdName.textContent = d.name + ` (h=${d.h})`;

                // Columna: Número de Biot
                const tdBi = document.createElement('td');
                tdBi.style.padding = '4px';
                const biValid = d.Bi < 0.1;
                const biTooltip = biValid
                    ? (lang === 'en' ? 'Bi < 0.1: Lumped Capacitance valid' : 'Bi < 0.1: Capacitancia global válida')
                    : (lang === 'en' ? 'Bi ≥ 0.1: Significant internal gradient' : 'Bi ≥ 0.1: Gradiente interno significativo');
                tdBi.innerHTML = d.Bi.toFixed(4) +
                    (biValid
                        ? ` <span style='color:#10b981;font-size:0.7em;' title='${biTooltip}'>(V)</span>`
                        : ` <span style='color:#ef4444;font-size:0.7em;' title='${biTooltip}'>(I)</span>`);

                // Columna: Tiempo característico τ
                const tdTau = document.createElement('td');
                tdTau.style.padding = '4px';
                tdTau.textContent = d.tau.toFixed(1);

                // Columna: t₉₅ = 3τ  (95% de equilibrio)
                const tdT95 = document.createElement('td');
                tdT95.style.padding = '4px';
                tdT95.style.color = '#fbbf24';
                tdT95.title = lang === 'en'
                    ? `95% thermal equilibrium ≈ 3τ = ${fmtTime(t95)}`
                    : `Equilibrio térmico al 95% ≈ 3τ = ${fmtTime(t95)}`;
                tdT95.textContent = fmtTime(t95);

                // Columna: t₉₉ = 5τ  (99.3% de equilibrio)
                const tdT99 = document.createElement('td');
                tdT99.style.padding = '4px';
                tdT99.style.color = '#34d399';
                tdT99.title = lang === 'en'
                    ? `99.3% thermal equilibrium ≈ 5τ = ${fmtTime(t99)}`
                    : `Equilibrio térmico al 99.3% ≈ 5τ = ${fmtTime(t99)}`;
                tdT99.textContent = fmtTime(t99);

                // Columna: t_obj (Tiempo para llegar a T_inf ± 1°C)
                const T_obj_diff = 1.0;
                let t_obj = 0;
                let t_obj_text = "N/A";
                let t_obj_tooltip_es = "";
                let t_obj_tooltip_en = "";
                if (Math.abs(currentTi - currentTinf) > T_obj_diff) {
                    t_obj = d.tau * Math.log(Math.abs(currentTi - currentTinf) / T_obj_diff);
                    t_obj_text = fmtTime(t_obj);
                    t_obj_tooltip_es = `Tiempo para T_obj = T_inf ± ${T_obj_diff}°C: ${t_obj_text}`;
                    t_obj_tooltip_en = `Time for T_obj = T_inf ± ${T_obj_diff}°C: ${t_obj_text}`;
                } else {
                    t_obj_text = "≈ 0 s";
                    t_obj_tooltip_es = `T_i ya está dentro de ±${T_obj_diff}°C de T_inf`;
                    t_obj_tooltip_en = `T_i is already within ±${T_obj_diff}°C of T_inf`;
                }

                const tdTObj = document.createElement('td');
                tdTObj.style.padding = '4px';
                tdTObj.style.color = '#60a5fa'; // Light blue
                tdTObj.title = lang === 'en' ? t_obj_tooltip_en : t_obj_tooltip_es;
                tdTObj.textContent = t_obj_text;

                tr.appendChild(tdName);
                tr.appendChild(tdBi);
                tr.appendChild(tdTau);
                tr.appendChild(tdT95);
                tr.appendChild(tdT99);
                tr.appendChild(tdTObj);
                tbodyResults.appendChild(tr);
            });
        }

        if (!isPlaying) {
            simTime = 0;
            if (resTime) resTime.innerHTML = simTime.toFixed(1) + " s";
        }

        lastTimestamp = performance.now();

        // Reset the visible time window whenever the parameters change
        currentChartMax = 200;
        updateChartCurves();
    }

    function updateChartCurves() {
        if (!chartInstance) return;
        const tMax = currentChartMax;
        simData.forEach((d, idx) => {
            if (chartInstance.data.datasets[idx]) {
                const data = [];
                for (let t = 0; t <= tMax; t += tMax / 50) {
                    const T = currentTinf + (currentTi - currentTinf) * Math.exp(-t / d.tau);
                    data.push({ x: t, y: T });
                }
                chartInstance.data.datasets[idx].data = data;
            }
        });
        chartInstance.options.scales.x.max = tMax;
        chartInstance.options.scales.x.ticks.stepSize = tMax > 200 ? 100 : 10;
        const maxTemp = Math.max(currentTi, currentTinf);
        const minTemp = Math.min(currentTi, currentTinf);
        chartInstance.options.scales.y.max = maxTemp > 500 ? Math.ceil(maxTemp / 100) * 100 : (Math.ceil(maxTemp / 10) * 10 + 10);
        chartInstance.options.scales.y.min = minTemp < 0 ? Math.floor(minTemp / 10) * 10 : (minTemp > 20 ? 0 : Math.floor(minTemp / 10) * 10 - 10);
        chartInstance.update();
    }

    function draw(timestamp) {
        if (!timestamp) timestamp = performance.now();
        if (isPlaying) {
            const dt = (timestamp - lastTimestamp) / 1000;
            simTime += dt * 5 * simSpeedMultiplier;
        }
        lastTimestamp = timestamp;

        if (resTime) resTime.innerHTML = simTime.toFixed(1) + " s";

        // ── Resize guard ────────────────────────────────────────────────────
        // Leer SIEMPRE desde el shell (padre con height CSS fijo: 280 px).
        // Nunca de canvas.clientHeight directamente: si el shell no tuviese
        // altura explícita el canvas devolvería su propio tamaño → bucle
        // infinito de estiramiento vertical en cada frame de rAF.
        // getBoundingClientRect() devuelve el tamaño ya pintado por el browser
        // y no genera reflow adicional dentro del loop de animación.
        const shell = canvas.closest('.newton-canvas-shell');
        const shellRect = shell ? shell.getBoundingClientRect() : null;
        const targetW = shellRect && shellRect.width > 0
            ? Math.floor(shellRect.width)
            : (canvas.clientWidth || canvas.offsetWidth || 0);
        // Si el shell no tiene altura > 0, NO redimensionamos: evita el bucle.
        const targetH = shellRect && shellRect.height > 0
            ? Math.floor(shellRect.height)
            : 0;

        if (targetW > 0 && targetH > 0 &&
            (canvas.width !== targetW || canvas.height !== targetH)) {
            const _oldW = canvas.width;
            const _oldH = canvas.height;
            canvas.width = targetW;
            canvas.height = targetH;
            // Preservar trayectorias escalando posiciones; solo reinicializar si
            // el arreglo está vacío (primera carga) o las dimensiones previas son 0.
            if (particles.length > 0 && _oldW > 0 && _oldH > 0) {
                rescaleParticles(_oldW, _oldH, targetW, targetH);
            } else {
                initParticles();
            }

            // Notificar a Chart.js que el contenedor cambió de tamaño
            if (chartInstance) {
                chartInstance.resize();
            }
        }

        ctx.clearRect(0, 0, canvas.width, canvas.height);

        const spacing = canvas.width / 4;
        const visualR = 15 + (currentD / 0.30) * 50;

        // draw cylinders
        simData.forEach((d, idx) => {
            const T = currentTinf + (currentTi - currentTinf) * Math.exp(-simTime / d.tau);
            currentTemps[idx] = T;
            const cx = spacing * idx + spacing / 2;
            const cy = canvas.height / 2;

            // Draw gradient representation of cylinder temperature
            const grad = ctx.createRadialGradient(cx, cy, 2, cx, cy, visualR);
            // Incandescent color based on temperature: hot is red/orange, cold is grey/dark blue
            const ratio = Math.max(0, Math.min(1, (T - currentTinf) / Math.max(1, currentTi - currentTinf)));
            const rVal = Math.round(50 + 205 * ratio);
            const gVal = Math.round(70 + 80 * ratio);
            const bVal = Math.round(90 - 40 * ratio);

            grad.addColorStop(0, `rgb(${rVal}, ${gVal}, ${bVal})`);
            grad.addColorStop(1, '#1e293b');

            ctx.beginPath();
            ctx.arc(cx, cy, visualR, 0, Math.PI * 2);
            ctx.fillStyle = grad;
            ctx.strokeStyle = d.color;
            ctx.lineWidth = 2;
            ctx.fill();
            ctx.stroke();

            ctx.fillStyle = d.color;
            ctx.font = "bold 11px sans-serif";
            ctx.textAlign = "center";
            ctx.fillText(d.name, cx, cy - visualR - 10);

            ctx.fillStyle = "#fff";
            ctx.font = "bold 12px sans-serif";
            ctx.textAlign = "center";
            ctx.fillText(T.toFixed(1) + "°C", cx, cy + visualR + 20);
        });

        // draw particles
        particles.forEach(p => {
            const cx = spacing * p.zone + spacing / 2;
            const cy = canvas.height / 2;
            const T = currentTemps[p.zone];
            const dT = T - currentTinf;

            // Aplicar umbral físico de equilibrio: cuando |ΔT| < ε la diferencia de
            // densidad β·ΔT → 0, por lo que no existe fuerza de flotación y la
            // convección natural cesa. Se fuerza heatFactor = 0 para que el bloque
            // `atEquilibrium` de NewtonPlumeParticle.update() amortigue las partículas
            // hasta el reposo. (Corrección física: EQUILIBRIUM_EPSILON = 0.1 °C)
            const rawHeatFactor = Math.max(0, dT) / Math.max(1, currentTi - currentTinf);
            const heatFactor = (Math.abs(dT) < EQUILIBRIUM_EPSILON) ? 0 : rawHeatFactor;

            p.update(cx, cy, visualR, heatFactor, spacing, canvas.height);
            p.draw(ctx, heatFactor);
        });

        // Expand the chart's visible time window once the simulation passes it,
        // so the curves keep showing beyond the initial 200 s range
        if (simTime > currentChartMax * 0.9) {
            currentChartMax = currentChartMax * 2;
            updateChartCurves();
        }

        // Update current time vertical line on the chart
        if (chartInstance) {
            chartInstance.data.datasets[4].data = [
                { x: simTime, y: chartInstance.options.scales.y.min },
                { x: simTime, y: chartInstance.options.scales.y.max }
            ];

            const statePoints = simData.map((d, idx) => {
                const T = currentTemps[idx];
                return { x: simTime, y: T };
            });
            chartInstance.data.datasets[5].data = statePoints;
            chartInstance.update();
        }

        if (isPlaying || simTime === 0) {
            animationId = requestAnimationFrame(draw);
        }
    }

    [sliderTi, sliderTinf, sliderD, sliderK, sliderRho, sliderCp].forEach(el => {
        if (el) el.addEventListener('input', updateSimulationParams);
    });

    syncSliderAndNumberInput(sliderTi, document.getElementById('newton-ti-num'), updateSimulationParams);
    syncSliderAndNumberInput(sliderTinf, document.getElementById('newton-tinf-num'), updateSimulationParams);
    syncSliderAndNumberInput(sliderD, document.getElementById('newton-d-num'), updateSimulationParams);
    syncSliderAndNumberInput(sliderK, document.getElementById('newton-k-num'), updateSimulationParams);
    syncSliderAndNumberInput(sliderRho, document.getElementById('newton-rho-num'), updateSimulationParams);
    syncSliderAndNumberInput(sliderCp, document.getElementById('newton-cp-num'), updateSimulationParams);

    // Speed buttons event listeners — estilos manejados por CSS (.active en style.css)
    const speedButtons = document.querySelectorAll('.newton-speed-btn');
    speedButtons.forEach(btn => {
        btn.addEventListener('click', () => {
            speedButtons.forEach(b => b.classList.remove('active'));
            btn.classList.add('active');
            simSpeedMultiplier = parseFloat(btn.getAttribute('data-speed')) || 1;
        });
    });

    if (startBtn) {
        startBtn.addEventListener('click', () => {
            isPlaying = !isPlaying;
            if (isPlaying) {
                // Actualizar texto dentro de los spans bilingües (preserva estructura HUD)
                const esSpan = startBtn.querySelector('.lang-es');
                const enSpan = startBtn.querySelector('.lang-en');
                if (esSpan) esSpan.textContent = 'Pausar';
                if (enSpan) enSpan.textContent = 'Pause';
                startBtn.style.background = 'linear-gradient(135deg,#92400e,#eab308)';
                lastTimestamp = performance.now();
                animationId = requestAnimationFrame(draw);
            } else {
                const esSpan = startBtn.querySelector('.lang-es');
                const enSpan = startBtn.querySelector('.lang-en');
                if (esSpan) esSpan.textContent = 'Iniciar Enfriamiento';
                if (enSpan) enSpan.textContent = 'Start Cooling';
                startBtn.style.background = '';   // deja que el CSS lo controle
            }
        });
    }

    if (resetBtn) {
        resetBtn.addEventListener('click', () => {
            isPlaying = false;
            simTime = 0;
            if (startBtn) {
                const esSpan = startBtn.querySelector('.lang-es');
                const enSpan = startBtn.querySelector('.lang-en');
                if (esSpan) esSpan.textContent = 'Iniciar Enfriamiento';
                if (enSpan) enSpan.textContent = 'Start Cooling';
                startBtn.style.background = '';   // restaura gradiente CSS
            }
            updateSimulationParams();
            initParticles();
        });
    }

    // ── HUD: fill dinámico del riel de cada slider ──────────────────────────
    // Actualiza la CSS custom property --val-pct para que el degradé del riel
    // refleje la posición actual del thumb (compatible con style.css § Newton HUD).
    function updateSliderFill(slider) {
        const min = parseFloat(slider.min) || 0;
        const max = parseFloat(slider.max) || 100;
        const pct = ((parseFloat(slider.value) - min) / (max - min)) * 100;
        slider.style.setProperty('--val-pct', pct.toFixed(1) + '%');
    }

    [sliderTi, sliderTinf, sliderD, sliderK, sliderRho, sliderCp].forEach(s => {
        if (!s) return;
        updateSliderFill(s);                          // valor inicial
        s.addEventListener('input', () => updateSliderFill(s));
    });

    // ── HUD: ResizeObserver para canvas de animación ─────────────────────────
    // Cuando el usuario abre/cierra el modal fullscreen el shell cambia de tamaño;
    // forzamos el redimensionamiento del canvas para que la animación llene el área.
    if (typeof ResizeObserver !== 'undefined') {
        const canvasShell = canvas.closest('.newton-canvas-shell');
        if (canvasShell) {
            let resizeRAF = null; // debounce con rAF para no disparar en cada px
            const shellObserver = new ResizeObserver(() => {
                if (resizeRAF) cancelAnimationFrame(resizeRAF);
                resizeRAF = requestAnimationFrame(() => {
                    // El canvas de animación lo redimensiona el guard interno de draw(),
                    // que llama a rescaleParticles() preservando trayectorias continuas.
                    // Aquí solo actualizamos Chart.js para evitar el triple disparo
                    // de initParticles() que causaba parpadeo visible.
                    if (chartInstance) {
                        chartInstance.resize();
                    }
                });
            });
            shellObserver.observe(canvasShell);

            // También observar el contenedor del gráfico directamente
            const chartShell = graphCanvas
                ? graphCanvas.closest('.chart-container, .newton-chart-area')
                : null;
            if (chartShell) {
                shellObserver.observe(chartShell);
            }
        }
    }

    // ── Listener para el evento newton:resize emitido por resizeNewtonAssets() ──
    // El IIFE fullscreen controller despacha este evento DESPUÉS de actualizar
    // c.width/c.height, incluyendo las dimensiones anteriores (oldW/oldH) para
    // que podamos escalar posiciones en vez de reinicializar completamente.
    function onNewtonResize(e) {
        const detail = e && e.detail ? e.detail : {};
        const newW = detail.w  || canvas.width;
        const newH = detail.h  || canvas.height;
        const oldW = detail.oldW || 0;
        const oldH = detail.oldH || 0;
        // Escalar trayectorias si ya hay partículas y conocemos las dimensiones previas;
        // reinicializar solo en la primera carga (arreglo vacío) o si no hay oldW/oldH.
        if (particles.length > 0 && oldW > 0 && oldH > 0) {
            rescaleParticles(oldW, oldH, newW, newH);
        } else {
            initParticles();
        }
        if (chartInstance) chartInstance.resize();
    }
    window.addEventListener('newton:resize', onNewtonResize);

    // ── Reanuda el bucle draw() si fue cancelado por el IntersectionObserver ──
    // Al abrir/cerrar fullscreen el modal se teletransporta al body; el canvas
    // puede salir del viewport original y el IntersectionObserver cancela el rAF.
    // El IIFE despacha 'newton:resume' tras la transición para reiniciar el bucle.
    function onNewtonResume() {
        if (animationId) cancelAnimationFrame(animationId);
        lastTimestamp = performance.now();
        animationId = requestAnimationFrame(draw);
    }
    window.addEventListener('newton:resume', onNewtonResume);

    // ── window.resize: solo actualiza Chart.js ───────────────────────────────
    // El canvas de animación lo redimensiona el guard interno de draw() (Route 1)
    // y el IIFE via 'newton:resize' (Route 4). Esta ruta solo sincroniza Chart.js
    // para evitar el triple disparo de initParticles() que causaba parpadeo.
    let _winResizeRAF = null;
    function onWindowResize() {
        if (_winResizeRAF) cancelAnimationFrame(_winResizeRAF);
        _winResizeRAF = requestAnimationFrame(() => {
            if (chartInstance) chartInstance.resize();
        });
    }
    window.addEventListener('resize', onWindowResize);

    const observer = new IntersectionObserver((entries) => {
        if (entries[0].isIntersecting) {
            // Diferir un frame para que el browser haya aplicado
            // el CSS grid 2fr/1fr antes de leer las dimensiones del canvas
            requestAnimationFrame(() => {
                initParticles();          // lee getBoundingClientRect() ya correcto
                updateSimulationParams();
                if (chartInstance) chartInstance.resize(); // gráfica al ancho 2fr
                lastTimestamp = performance.now();
                animationId = requestAnimationFrame(draw);
            });
        } else {
            if (animationId) {
                cancelAnimationFrame(animationId);
                animationId = null;
            }
        }
    });

    observer.observe(canvas);
}
// ==========================================
// 12. NUSSELT SIMULATION
// ==========================================
function initNusseltSimulation() {
    if (window._nusseltInited) return; // Evitar doble init (ya inicializado con dimensiones válidas)
    const uSlider = document.getElementById("nu-u");
    const kSlider = document.getElementById("nu-k");
    const lcSlider = document.getElementById("nu-lc");
    const tsSlider = document.getElementById("nu-ts");
    const tinfSlider = document.getElementById("nu-tinf");

    const uVal = document.getElementById("nu-u-val");
    const kVal = document.getElementById("nu-k-val");
    const lcVal = document.getElementById("nu-lc-val");
    const tsVal = document.getElementById("nu-ts-val");
    const tinfVal = document.getElementById("nu-tinf-val");

    const resQCond = document.getElementById("nu-qcond-res");
    const resQConv = document.getElementById("nu-qconv-res");
    const resNu = document.getElementById("nu-res");

    const canvas = document.getElementById("nusseltChart");
    const animCanvas = document.getElementById("nusseltCanvas");
    if (!canvas || !animCanvas) return;

    // GUARD "Lazy Init": si el canvas o su contenedor padre aún tienen
    // dimensiones 0x0 (pestaña 'nusselt-sim' oculta con display:none al
    // cargar la página), abortar la inicialización. Instanciar aquí el
    // Chart.js y las partículas del perfil de velocidad sobre un canvas
    // 0x0 corrompe sus posiciones/tamaño y Chart.js nunca se recupera
    // correctamente después, aunque el contenedor se haga visible más
    // tarde. switchTab reintenta esta función una vez la pestaña esté
    // realmente visible (ver bloque 'nusselt-sim' en switchTab).
    const animParent = animCanvas.parentElement;
    const hasNoSize = (animCanvas.offsetWidth === 0 && animCanvas.offsetHeight === 0) ||
        (animParent && animParent.offsetWidth === 0 && animParent.offsetHeight === 0);
    if (hasNoSize) return;

    const ctx = canvas.getContext("2d");
    const actx = animCanvas.getContext("2d");

    let chartInstance = new Chart(ctx, {
        type: "line",
        data: {
            datasets: [
                {
                    label: "",
                    data: [],
                    borderColor: "#94a3b8",
                    backgroundColor: "rgba(148, 163, 184, 0.1)",
                    borderWidth: 2,
                    borderDash: [5, 5],
                    fill: false,
                    tension: 0
                },
                {
                    label: "",
                    data: [],
                    borderColor: "#38bdf8",
                    backgroundColor: "rgba(56, 189, 248, 0.2)",
                    borderWidth: 3,
                    fill: true,
                    tension: 0.4
                }
            ]
        },
        options: {
            legend: { display: false },
            plugins: { legend: { display: false } },
            responsive: true,
            maintainAspectRatio: false,
            animation: false,
            scales: {
                x: {
                    type: "linear",
                    min: 0,
                    max: 0.2,
                    title: { display: true, text: "Distancia desde la pared y (m)", color: "#94a3b8" },
                    ticks: { color: "#cbd5e1" },
                    grid: { color: "rgba(255,255,255,0.1)" }
                },
                y: {
                    min: 20,
                    max: 100,
                    title: { display: true, text: "Temperatura (°C)", color: "#94a3b8" },
                    ticks: { color: "#cbd5e1" },
                    grid: { color: "rgba(255,255,255,0.1)" }
                }
            },

        }
    });

    let particles = [];
    const numParticles = 80;

    function initParticles() {
        particles = [];
        for (let i = 0; i < numParticles; i++) {
            particles.push({
                y: Math.random() * animCanvas.height,
                xRel: Math.random(),
                size: 1.5 + Math.random() * 2
            });
        }
    }

    function getColorForTemp(T, minT = 20, maxT = 100) {
        const normalized = (maxT === minT) ? 0.5 : Math.max(0, Math.min(1, (T - minT) / (maxT - minT)));
        const r = Math.round(normalized * 220 + 35);
        const g = Math.round(normalized * 50 + 30);
        const b = Math.round((1 - normalized) * 200 + 55);
        return `rgb(${r}, ${g}, ${b})`;
    }

    let animationId;
    let lastTimestamp = 0;

    let currentU = 0;
    let currentK = 0.6;
    let currentLc = 0.05;
    let currentNu = 1.0;
    let currentTs = 100;
    let currentTinf = 20;

    function updateSimulation() {
        currentU = parseFloat(uSlider.value);
        currentK = parseFloat(kSlider.value);
        currentLc = parseFloat(lcSlider.value);

        currentTs = tsSlider ? parseFloat(tsSlider.value) : 100;
        currentTinf = tinfSlider ? parseFloat(tinfSlider.value) : 20;

        // Propiedades de referencia del fluido (tipo agua)
        const rho = 1000; // kg/m³
        const cp = 4180;  // J/kg·K
        const mu = 0.001; // Pa·s

        // Prandtl y Reynolds
        const Pr = (mu * cp) / currentK;
        const Re = (rho * currentU * currentLc) / mu;

        currentNu = 1.0;
        if (currentU > 0) {
            // Relación clásica de correlación
            currentNu = 1.0 + 0.03 * Math.sqrt(Re) * Math.pow(Pr, 1 / 3);
        }

        const h = (currentK / currentLc) * currentNu;

        const q_cond = currentK * (currentTs - currentTinf) / currentLc;
        const q_conv = h * (currentTs - currentTinf);

        resQCond.textContent = q_cond.toFixed(1) + " W/m²";
        resQConv.textContent = q_conv.toFixed(1) + " W/m²";
        resNu.textContent = currentNu.toFixed(2);

        chartInstance.options.scales.x.max = Math.max(0.2, currentLc);
        chartInstance.options.scales.y.max = currentTs;
        chartInstance.options.scales.y.min = currentTinf;

        const condData = [];
        const convData = [];
        const numPoints = 50;
        for (let i = 0; i <= numPoints; i++) {
            const y = (i / numPoints) * currentLc;
            const T_cond = currentTs - (currentTs - currentTinf) * (y / currentLc);
            condData.push({ x: y, y: T_cond });

            const T_conv = currentTinf + (currentTs - currentTinf) * Math.pow(1 - y / currentLc, currentNu);
            convData.push({ x: y, y: T_conv });
        }

        chartInstance.data.datasets[0].data = condData;
        chartInstance.data.datasets[1].data = convData;
        chartInstance.update();
    }

    function draw(timestamp) {
        if (!lastTimestamp) lastTimestamp = timestamp;
        const dt = (timestamp - lastTimestamp) / 1000;
        lastTimestamp = timestamp;

        const parent = animCanvas.parentElement;
        if (animCanvas.width !== parent.clientWidth || animCanvas.height !== parent.clientHeight) {
            animCanvas.width = parent.clientWidth;
            animCanvas.height = parent.clientHeight;
            initParticles();
        }

        actx.clearRect(0, 0, animCanvas.width, animCanvas.height);

        // 1. Dibujar Pared Sólida (izquierda, caliente)
        const wallWidth = 60;
        actx.fillStyle = "#ef4444";
        actx.fillRect(0, 0, wallWidth, animCanvas.height);

        actx.fillStyle = "#ffffff";
        actx.font = "bold 12px Outfit";
        actx.textAlign = "center";
        actx.fillText("PARED", wallWidth / 2, animCanvas.height / 2 - 10);
        actx.fillText(currentTs.toFixed(0) + "°C", wallWidth / 2, animCanvas.height / 2 + 10);

        // 2. Dibujar Capa de Fluido con gradiente de temperatura
        const maxFluidPxWidth = animCanvas.width - wallWidth - 45;
        const fluidPxWidth = (currentLc / 0.2) * maxFluidPxWidth;
        const fluidEnd = wallWidth + fluidPxWidth;

        for (let px = 0; px < fluidPxWidth; px++) {
            const yRel = px / fluidPxWidth;
            const T = currentTinf + (currentTs - currentTinf) * Math.pow(1 - yRel, currentNu);
            actx.fillStyle = getColorForTemp(T, currentTinf, currentTs);
            actx.fillRect(wallWidth + px, 0, 1.5, animCanvas.height);
        }

        // 3. Dibujar Medio Exterior
        actx.fillStyle = "#1e293b";
        actx.fillRect(fluidEnd, 0, animCanvas.width - fluidEnd, animCanvas.height);

        actx.fillStyle = "#38bdf8";
        actx.font = "bold 11px Outfit";
        actx.textAlign = "left";
        actx.fillText("T∞ = " + currentTinf.toFixed(0) + "°C", fluidEnd + 10, animCanvas.height / 2);

        // 4. Partículas
        actx.fillStyle = "rgba(255, 255, 255, 0.4)";
        particles.forEach(p => {
            const speed = currentU * 50 * p.xRel;
            p.y -= speed * dt;
            if (p.y < 0) {
                p.y = animCanvas.height;
                p.xRel = Math.random();
            }

            const xPx = wallWidth + p.xRel * fluidPxWidth;
            actx.beginPath();
            actx.arc(xPx, p.y, p.size, 0, Math.PI * 2);
            actx.fill();
        });

        // 5. Límites
        actx.strokeStyle = "rgba(255,255,255,0.2)";
        actx.lineWidth = 1;
        actx.beginPath();
        actx.moveTo(fluidEnd, 0);
        actx.lineTo(fluidEnd, animCanvas.height);
        actx.stroke();

        actx.fillStyle = "#ffffff";
        actx.font = "bold 10px Outfit";
        actx.textAlign = "center";
        actx.fillText(`Espesor Lc = ${currentLc.toFixed(2)}m`, wallWidth + fluidPxWidth / 2, 20);

        animationId = requestAnimationFrame(draw);
    }

    uSlider.addEventListener("input", updateSimulation);
    kSlider.addEventListener("input", updateSimulation);
    lcSlider.addEventListener("input", updateSimulation);
    if (tsSlider) tsSlider.addEventListener("input", updateSimulation);
    if (tinfSlider) tinfSlider.addEventListener("input", updateSimulation);

    syncSliderAndNumberInput(uSlider, document.getElementById('nu-u-num'), updateSimulation);
    syncSliderAndNumberInput(kSlider, document.getElementById('nu-k-num'), updateSimulation);
    syncSliderAndNumberInput(lcSlider, document.getElementById('nu-lc-num'), updateSimulation);
    if (tsSlider) syncSliderAndNumberInput(tsSlider, document.getElementById('nu-ts-num'), updateSimulation);
    if (tinfSlider) syncSliderAndNumberInput(tinfSlider, document.getElementById('nu-tinf-num'), updateSimulation);

    const observer = new IntersectionObserver((entries) => {
        if (entries[0].isIntersecting) {
            updateSimulation();
            lastTimestamp = performance.now();
            animationId = requestAnimationFrame(draw);
        } else {
            if (animationId) cancelAnimationFrame(animationId);
        }
    });

    // Como ya pasamos la guarda "Lazy Init" de arriba, el canvas tiene
    // dimensiones reales en este punto: forzamos el primer sizing +
    // instanciación de partículas aquí mismo, sin depender de la primera
    // notificación asíncrona del IntersectionObserver (evita la carrera
    // entre este cálculo y resizeNusseltAssets() del controlador de
    // pantalla completa, que antes dejaba `particles` vacío).
    animCanvas.width = animParent.clientWidth || animCanvas.offsetWidth;
    animCanvas.height = animParent.clientHeight || animCanvas.offsetHeight;
    initParticles();

    window._nusseltInited = true;
    window.resetNusseltParticles = initParticles;

    observer.observe(animCanvas);
}

/* =========================================================================
   BOUNDARY LAYER & ANALOGY SIMULATOR
   ========================================================================= */
function initBoundaryLayerSimulation() {
    const prSlider = document.getElementById("bl-pr");
    const scSlider = document.getElementById("bl-sc");
    const tcondSelect = document.getElementById("bl-tcond");

    const prVal = document.getElementById("bl-pr-val");
    const scVal = document.getElementById("bl-sc-val");

    const resDeltaT = document.getElementById("bl-deltat-res");
    const resDeltaC = document.getElementById("bl-deltac-res");
    const resLe = document.getElementById("bl-le-res");
    const resRatio = document.getElementById("bl-ratio-res");

    const canvas = document.getElementById("blChart");
    if (!canvas) return;
    const ctx = canvas.getContext("2d");

    let chartInstance = new Chart(ctx, {
        type: "line",
        data: {
            datasets: [
                {
                    label: "Velocidad: u* = u / U_∞",
                    data: [],
                    borderColor: "#3b82f6",
                    backgroundColor: "rgba(59, 130, 246, 0.1)",
                    borderWidth: 2,
                    fill: true,
                    tension: 0.4
                },
                {
                    label: "Temperatura: Perfil Normalizado",
                    data: [],
                    borderColor: "#ef4444",
                    backgroundColor: "rgba(239, 68, 68, 0.1)",
                    borderWidth: 2,
                    borderDash: [5, 5],
                    fill: false,
                    tension: 0.4
                },
                {
                    label: "Concentración: C* = (C - C_s) / (C_∞ - C_s)",
                    data: [],
                    borderColor: "#10b981",
                    backgroundColor: "rgba(16, 185, 129, 0.1)",
                    borderWidth: 2,
                    borderDash: [2, 2],
                    fill: false,
                    tension: 0.4
                }
            ]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                x: {
                    type: "linear",
                    position: "bottom",
                    title: {
                        display: true,
                        text: "Distancia adimensional, y / δ",
                        color: "#94a3b8"
                    },
                    min: 0,
                    max: 1.5,
                    grid: { color: "#334155" },
                    ticks: { color: "#94a3b8" }
                },
                y: {
                    title: {
                        display: true,
                        text: "Perfiles adimensionales (u*, T*, C*)",
                        color: "#94a3b8"
                    },
                    min: 0,
                    max: 1.05,
                    grid: { color: "#334155" },
                    ticks: { color: "#94a3b8" }
                }
            },
            plugins: {
                legend: { labels: { color: "#cbd5e1" } }
            }
        }
    });

    function updateSimulation() {
        const Pr = parseFloat(prSlider.value);
        const Sc = parseFloat(scSlider.value);

        const delta_t_ratio = Math.pow(Pr, -1 / 3);
        const delta_c_ratio = Math.pow(Sc, -1 / 3);
        const Le = Sc / Pr;
        const thickness_ratio = delta_t_ratio / delta_c_ratio;

        resDeltaT.textContent = delta_t_ratio.toFixed(2) + " δ";
        resDeltaC.textContent = delta_c_ratio.toFixed(2) + " δ";
        if (resLe) resLe.textContent = Le.toFixed(2);
        if (resRatio) resRatio.textContent = thickness_ratio.toFixed(2);

        const velData = [];
        const tempData = [];
        const concData = [];

        const tCond = tcondSelect ? tcondSelect.value : "cold";

        const numPoints = 50;
        for (let i = 0; i <= numPoints; i++) {
            const y = (i / numPoints) * 1.5;

            let u_ratio = 1.0;
            if (y <= 1.0) {
                u_ratio = 2 * y - Math.pow(y, 2);
            }
            velData.push({ x: y, y: u_ratio });

            let y_t = y / delta_t_ratio;
            let t_ratio = 1.0;
            if (y_t <= 1.0) {
                t_ratio = 2 * y_t - Math.pow(y_t, 2);
            }
            if (tCond === "hot") {
                // If Ts > Tinf, temperature drops from 1 to 0
                if (y_t <= 1.0) {
                    t_ratio = 1.0 - (2 * y_t - Math.pow(y_t, 2));
                } else {
                    t_ratio = 0.0;
                }
            }
            tempData.push({ x: y, y: t_ratio });

            let y_c = y / delta_c_ratio;
            let c_ratio = 1.0;
            if (y_c <= 1.0) {
                c_ratio = 2 * y_c - Math.pow(y_c, 2);
            }
            concData.push({ x: y, y: c_ratio });
        }

        chartInstance.data.datasets[0].data = velData;
        chartInstance.data.datasets[1].data = tempData;
        chartInstance.data.datasets[2].data = concData;

        chartInstance.update();
    }

    prSlider.addEventListener('input', updateSimulation);
    scSlider.addEventListener('input', updateSimulation);
    if (tcondSelect) tcondSelect.addEventListener('change', updateSimulation);

    syncSliderAndNumberInput(prSlider, document.getElementById('bl-pr-num'), updateSimulation);
    syncSliderAndNumberInput(scSlider, document.getElementById('bl-sc-num'), updateSimulation);

    updateSimulation();
}

function initViewFactorSimulation() {
    const sliderW = document.getElementById("vf-w");
    const sliderL = document.getElementById("vf-l");
    const sliderD = document.getElementById("vf-d");
    const canvas = document.getElementById("viewFactorGeometry");
    const chartCtx = document.getElementById("viewFactorChart");
    if (!canvas || !chartCtx) return;

    let viewFactorChart = null;
    const ctx = canvas.getContext("2d");

    function calcF12(W, L, D) {
        const X = W / D;
        const Y = L / D;

        const term1 = Math.log(Math.sqrt(((1 + X * X) * (1 + Y * Y)) / (1 + X * X + Y * Y)));
        const term2 = X * Math.sqrt(1 + Y * Y) * Math.atan(X / Math.sqrt(1 + Y * Y));
        const term3 = Y * Math.sqrt(1 + X * X) * Math.atan(Y / Math.sqrt(1 + X * X));
        const term4 = -X * Math.atan(X);
        const term5 = -Y * Math.atan(Y);

        const F12 = (2 / (Math.PI * X * Y)) * (term1 + term2 + term3 + term4 + term5);
        return F12;
    }

    function drawViewFactorGeometry(W, L, D) {
        const width = canvas.width;
        const height = canvas.height;

        ctx.clearRect(0, 0, width, height);

        const cx = width / 2 - 45;
        const cy = height / 2;

        const angleX = Math.PI / 6; // 30 deg
        const angleZ = 5 * Math.PI / 6; // 150 deg

        const spanVert = D + (W + L) * Math.sin(angleX);
        const spanHoriz = (W + L) * Math.cos(angleX);

        const scaleX = (width * 0.8) / Math.max(spanHoriz, 0.1);
        const scaleY = (height * 0.7) / Math.max(spanVert, 0.1);
        const scale = Math.min(scaleX, scaleY);

        function project(x, y, z) {
            const px = cx + (x * Math.cos(angleX) + z * Math.cos(angleZ)) * scale;
            const py = cy - (y * scale) + (x * Math.sin(angleX) + z * Math.sin(angleZ)) * scale;
            return { x: px, y: py };
        }

        function drawPlate(y_offset, color, fillStyle, label) {
            const hw = W / 2;
            const hl = L / 2;

            const p1 = project(hw, y_offset, hl);
            const p2 = project(hw, y_offset, -hl);
            const p3 = project(-hw, y_offset, -hl);
            const p4 = project(-hw, y_offset, hl);

            ctx.beginPath();
            ctx.moveTo(p1.x, p1.y);
            ctx.lineTo(p2.x, p2.y);
            ctx.lineTo(p3.x, p3.y);
            ctx.lineTo(p4.x, p4.y);
            ctx.closePath();

            ctx.fillStyle = fillStyle;
            ctx.fill();

            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.stroke();

            // Label
            ctx.fillStyle = color;
            ctx.font = "bold 11px Outfit";
            ctx.textAlign = "center";
            ctx.fillText(label, (p1.x + p3.x) / 2, (p1.y + p3.y) / 2 + 4);

            return { p1, p2, p3, p4 };
        }

        function drawConnector(pBottom, pTop) {
            ctx.beginPath();
            ctx.moveTo(pBottom.x, pBottom.y);
            ctx.lineTo(pTop.x, pTop.y);
            ctx.strokeStyle = 'rgba(255, 255, 255, 0.2)';
            ctx.lineWidth = 1;
            ctx.setLineDash([4, 4]);
            ctx.stroke();
            ctx.setLineDash([]);
        }

        const yTop = D / 2;
        const yBottom = -D / 2;

        const bottomCorners = drawPlate(yBottom, '#60a5fa', 'rgba(96, 165, 250, 0.15)', "Placa 1 (Emisora)");
        const topCorners = drawPlate(yTop, '#facc15', 'rgba(250, 204, 21, 0.15)', "Placa 2 (Receptora)");

        drawConnector(bottomCorners.p1, topCorners.p1);
        drawConnector(bottomCorners.p2, topCorners.p2);
        drawConnector(bottomCorners.p3, topCorners.p3);
        drawConnector(bottomCorners.p4, topCorners.p4);
    }

    function updateViewFactorData(W, L) {
        const d_arr = [];
        const f12_arr = [];
        for (let i = 1; i <= 50; i++) {
            const Dist = i * 0.2;
            d_arr.push(Dist.toFixed(1));
            f12_arr.push(calcF12(W, L, Dist));
        }
        return { d_arr, f12_arr };
    }

    let w_val = parseFloat(sliderW.value);
    let l_val = parseFloat(sliderL.value);
    let simData = updateViewFactorData(w_val, l_val);

    viewFactorChart = new Chart(chartCtx.getContext("2d"), {
        type: 'line',
        data: {
            labels: simData.d_arr,
            datasets: [{
                label: 'F12 vs Separación (D)',
                data: simData.f12_arr,
                borderColor: '#f97316',
                backgroundColor: 'rgba(249, 115, 22, 0.05)',
                borderWidth: 2,
                fill: true,
                tension: 0.3,
                pointRadius: 0
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                x: {
                    title: { display: true, text: 'Distancia D (m)', color: '#94a3b8', font: { size: 9 } },
                    grid: { color: 'rgba(255, 255, 255, 0.05)' },
                    ticks: { color: '#94a3b8', font: { size: 9 } }
                },
                y: {
                    title: { display: true, text: 'F12', color: '#94a3b8', font: { size: 9 } },
                    grid: { color: 'rgba(255, 255, 255, 0.05)' },
                    ticks: { color: '#94a3b8', font: { size: 9 } },
                    min: 0,
                    max: 1
                }
            },
            plugins: {
                legend: { display: false },
                tooltip: {
                    callbacks: {
                        label: function (context) {
                            return `F12: ${context.parsed.y.toFixed(4)}`;
                        }
                    }
                }
            }
        }
    });

    const updateDisplay = () => {
        const w = parseFloat(sliderW.value);
        const l = parseFloat(sliderL.value);
        const d = parseFloat(sliderD.value);

        const newData = updateViewFactorData(w, l);
        viewFactorChart.data.labels = newData.d_arr;
        viewFactorChart.data.datasets[0].data = newData.f12_arr;
        viewFactorChart.update('none');

        const currentF12 = calcF12(w, l, d);
        document.getElementById("vf-f12-val").textContent = currentF12.toFixed(4);
        document.getElementById("vf-escape-val").textContent = `${((1 - currentF12) * 100).toFixed(1)}%`;

        drawViewFactorGeometry(w, l, d);
    };

    [sliderW, sliderL, sliderD].forEach(el => {
        el.addEventListener("input", updateDisplay);
    });

    syncSliderAndNumberInput(sliderW, document.getElementById('vf-w-num'), updateDisplay);
    syncSliderAndNumberInput(sliderL, document.getElementById('vf-l-num'), updateDisplay);
    syncSliderAndNumberInput(sliderD, document.getElementById('vf-d-num'), updateDisplay);

    window.addEventListener("resize", updateDisplay);

    const observer = new IntersectionObserver((entries) => {
        if (entries[0].isIntersecting) {
            updateDisplay();
        }
    });
    observer.observe(canvas);

    updateDisplay();
}

